/*
 PrimeVideoDB - Microsoft SQL Server 2019+
 Versión robusta para uso académico.
 - Base creada si no existe.
 - Carga transaccional.
 - Unicode con NVARCHAR.
 - person.name usa NVARCHAR(MAX).
 - content_person fue deduplicada por (content_id, person_id, role).
*/

IF DB_ID(N'primevideodb') IS NULL
BEGIN
    CREATE DATABASE primevideodb;
END;
GO

USE primevideodb;
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    IF OBJECT_ID(N'dbo.vw_content_summary', N'V') IS NOT NULL
        DROP VIEW dbo.vw_content_summary;

    IF OBJECT_ID(N'dbo.content_country', N'U') IS NOT NULL DROP TABLE dbo.content_country;
    IF OBJECT_ID(N'dbo.content_genre', N'U') IS NOT NULL DROP TABLE dbo.content_genre;
    IF OBJECT_ID(N'dbo.content_person', N'U') IS NOT NULL DROP TABLE dbo.content_person;
    IF OBJECT_ID(N'dbo.country', N'U') IS NOT NULL DROP TABLE dbo.country;
    IF OBJECT_ID(N'dbo.genre', N'U') IS NOT NULL DROP TABLE dbo.genre;
    IF OBJECT_ID(N'dbo.person', N'U') IS NOT NULL DROP TABLE dbo.person;
    IF OBJECT_ID(N'dbo.content', N'U') IS NOT NULL DROP TABLE dbo.content;

    CREATE TABLE dbo.content (
        id INT NOT NULL CONSTRAINT pk_content PRIMARY KEY,
        source_id NVARCHAR(20) NOT NULL CONSTRAINT uq_content_source UNIQUE,
        content_type NVARCHAR(20) NOT NULL,
        title NVARCHAR(500) NOT NULL,
        date_added DATE NULL,
        release_year SMALLINT NULL,
        rating NVARCHAR(30) NULL,
        duration_value INT NULL,
        duration_unit NVARCHAR(20) NULL,
        duration_text NVARCHAR(50) NULL,
        description NVARCHAR(MAX) NULL,
        CONSTRAINT chk_content_type CHECK (content_type IN (N'MOVIE', N'TV_SHOW', N'OTHER')),
        CONSTRAINT chk_duration_unit CHECK (
            duration_unit IS NULL OR duration_unit IN (N'MINUTES', N'SEASONS', N'OTHER')
        )
    );

    CREATE TABLE dbo.person (
        id INT NOT NULL CONSTRAINT pk_person PRIMARY KEY,
        name NVARCHAR(MAX) NOT NULL
    );

    CREATE TABLE dbo.genre (
        id INT NOT NULL CONSTRAINT pk_genre PRIMARY KEY,
        name NVARCHAR(150) NOT NULL CONSTRAINT uq_genre_name UNIQUE
    );

    CREATE TABLE dbo.country (
        id INT NOT NULL CONSTRAINT pk_country PRIMARY KEY,
        name NVARCHAR(150) NOT NULL CONSTRAINT uq_country_name UNIQUE
    );

    CREATE TABLE dbo.content_person (
        content_id INT NOT NULL,
        person_id INT NOT NULL,
        role NVARCHAR(20) NOT NULL,
        credit_order INT NOT NULL CONSTRAINT df_content_person_order DEFAULT 0,
        CONSTRAINT pk_content_person PRIMARY KEY (content_id, person_id, role),
        CONSTRAINT fk_cp_content FOREIGN KEY (content_id)
            REFERENCES dbo.content(id) ON DELETE CASCADE,
        CONSTRAINT fk_cp_person FOREIGN KEY (person_id)
            REFERENCES dbo.person(id) ON DELETE CASCADE,
        CONSTRAINT chk_cp_role CHECK (role IN (N'DIRECTOR', N'CAST'))
    );

    CREATE TABLE dbo.content_genre (
        content_id INT NOT NULL,
        genre_id INT NOT NULL,
        CONSTRAINT pk_content_genre PRIMARY KEY (content_id, genre_id),
        CONSTRAINT fk_cg_content FOREIGN KEY (content_id)
            REFERENCES dbo.content(id) ON DELETE CASCADE,
        CONSTRAINT fk_cg_genre FOREIGN KEY (genre_id)
            REFERENCES dbo.genre(id) ON DELETE CASCADE
    );

    CREATE TABLE dbo.content_country (
        content_id INT NOT NULL,
        country_id INT NOT NULL,
        CONSTRAINT pk_content_country PRIMARY KEY (content_id, country_id),
        CONSTRAINT fk_cc_content FOREIGN KEY (content_id)
            REFERENCES dbo.content(id) ON DELETE CASCADE,
        CONSTRAINT fk_cc_country FOREIGN KEY (country_id)
            REFERENCES dbo.country(id) ON DELETE CASCADE
    );

    CREATE INDEX idx_content_title ON dbo.content(title);
    CREATE INDEX idx_content_year ON dbo.content(release_year);
    CREATE INDEX idx_content_type ON dbo.content(content_type);
    CREATE INDEX idx_cp_person ON dbo.content_person(person_id);
    CREATE INDEX idx_cg_genre ON dbo.content_genre(genre_id);
    CREATE INDEX idx_cc_country ON dbo.content_country(country_id);




Copyright: TV TOKYO'),
(701, N's701', N'MOVIE', N'The Curse of Robert', NULL, 2016, N'16+', 80, N'MINUTES', N'80 min', N'Emily Barker is a cash strapped student trying to make money as a cleaner, working nights at the East Falls Museum. But her peaceful graveyard shift turns into a time of terror when she discovers that one of the exhibits, a creepy vintage doll named Robert, is alive and wreaking havoc after hours.'),
(702, N's702', N'MOVIE', N'The Curse Of Hobbes House', NULL, 2020, NULL, 83, N'MINUTES', N'83 min', N'When down on her luck Jane Dormant learns about the death of her Aunt Alexandra she expects a life-saving inheritance but finds herself battling bloodthirsty Zombies instead, fighting for her life.'),
(703, N's703', N'MOVIE', N'The Curse of Buckout Road', NULL, 2019, N'18+', 96, N'MINUTES', N'96 min', N'A college class project on creation and destruction of modern myth, turns terrifying when a trio of young people come to realize the urban legends surrounding the famed Buckout Road may, in fact, be REAL.'),
(704, N's704', N'MOVIE', N'The Creepy Line', NULL, 2018, N'7+', 81, N'MINUTES', N'81 min', N'The Creepy Line reveals the stunning degree to which society is manipulated by Google and Facebook and blows the lid off the remarkably subtle - hence powerful - manner in which they do it. Offering first-hand accounts, scientific experiments and detailed analysis, the film examines what is at risk when these tech titans have free reign to utilize the public''s most private and personal data.'),
(705, N's705', N'MOVIE', N'The Creeping Flesh', NULL, 1973, N'PG', 92, N'MINUTES', N'92 min', N'A Victorian-age scientist returns to London with his paleontological bag-of-bones discovery from Papua New Guinea. Unfortunately, when exposed to water, flesh returns to the bones unleashing a malevolent being on the scientist''s family and friends.'),
(706, N's706', N'MOVIE', N'The Cowboy And The Senorita', NULL, 1944, N'13+', 54, N'MINUTES', N'54 min', N'A shady gambler attempts to snatch the rights to a teenage girl''s inherited gold mining claim, until a cowboy and his friend save the day.'),
(707, N's707', N'MOVIE', N'The Cowboy and The Lady', NULL, 1936, N'7+', 92, N'MINUTES', N'92 min', N'A lonely socialite masquerades as a maid and meets an unpretentious, plain-spoken cowboy who is unaware of her true identity.'),
(708, N's708', N'MOVIE', N'The Coverup', NULL, 2009, N'R', 95, N'MINUTES', N'95 min', N'Based on a True Story - surrounding the 1984 death of an Iowa teenager (Michael Welch) after his arrest by the Marshalltown Police Department. A young lawyer (Gabriel Mann) is hired to fight a corrupt Police Department and bring healing to a fractured family in this small town legal drama.'),
(709, N's709', N'MOVIE', N'The Court Jester', NULL, 1956, N'ALL', 101, N'MINUTES', N'101 min', N'Danny Kaye plays kind-hearted entertainer Hawkins who disguises himself as the legendary king of jesters, Giacomo. Hawkins infiltrates the court of the evil villain Basil Rathbone, but when a sorceress hypnotises him, royal chaos ensues.'),
(710, N's710', N'MOVIE', N'The Courageous Dr. Christian', NULL, 1940, N'ALL', 66, N'MINUTES', N'66 min', N'In this second movie in the Dr. Christian series, kindly Dr. Christian tends to the needs of the inhabitants living in the squalor of the town''s shanty district. The indigents and Dr. Christian are largely ignored by the local townspeople, until an epidemic of spinal meningitis threatens the entire community.'),
(711, N's711', N'MOVIE', N'The Count of Monte Cristo', NULL, 1975, N'13+', 103, N'MINUTES', N'103 min', N'A classic tale of injustice, revenge and retribution, in which Edmond Dantes is falsely accused by three men of conspiring with Napoleon. Richard Chamberlain stars in this definitive adaptation of Alexandre Dumas'' perennial favourite novel.'),
(712, N's712', N'MOVIE', N'The Cotton Pickin Truth Still On The Plantation', NULL, 2020, N'18+', 94, N'MINUTES', N'94 min', N'The Cotton Pickin'' Truth... Still On The Plantation is a documentary film that calls for the re-writing of American history as we know it. The film uncovers modern-day slavery in the Mississippi Delta in 2009. As a result of the film''s exposure to many dedicated Mississippians, the state of Mississippi ratified the 13th amendment in totality in February of 2013.'),
(713, N's713', N'MOVIE', N'The Corrupted', NULL, 2020, N'R', 104, N'MINUTES', N'104 min', N'Liam McDonagh (Sam Claflin), an ex-con attempting to live a peaceful life is thrust into action when his brother becomes entangled in a dangerous web of corruption. Liam must risk it all to save his family.'),
(714, N's714', N'MOVIE', N'The Confessor', NULL, 2005, N'PG-13', 91, N'MINUTES', N'91 min', N'A worldly and urbane priest is forced to challenge his comfortable existence as an ecclesiastical spin-doctor when he comes to believe in the innocence of a young priest accused of murder. His only ally, a journalist, is also his former sweetheart...'),
(715, N's715', N'MOVIE', N'The Competition', NULL, 1980, N'PG', 126, N'MINUTES', N'126 min', N'While competing against each other in a music contest, two pianists (Richard Dreyfuss, Amy Irving) fall in love and must battle to stay together in case either of them wins. Oscar-nominated for Best Song and Best Film Editing.'),
(716, N's716', N'MOVIE', N'The Collector', NULL, 2009, N'R', 90, N'MINUTES', N'90 min', N'Desperate to repay his debt to his ex-wife, an ex-con plots a heist at his new employer''s country home, unaware that a second criminal has also targeted the property, and rigged it with a series of deadly traps.'),
(717, N's717', N'MOVIE', N'The Cleansing', NULL, 2019, N'18+', 98, N'MINUTES', N'98 min', N'A young girl in medieval Britain must watch her mother undergo torture and murder for practicing witchcraft by The Cleanser.'),
(718, N's718', N'MOVIE', N'The Christmas Lodge', NULL, 2014, N'G', 89, N'MINUTES', N'89 min', N'During a weekend trip to the mountains, Mary finds herself at the now run-down lodge where she spent the holidays with her family growing up. She becomes determined to restore the building to its former glory. Inspired by her grandfather and guided by her grandmother in heaven, Mary throws herself into the project.'),
(719, N's719', N'MOVIE', N'The Christmas Elves', NULL, 2016, N'ALL', 52, N'MINUTES', N'52 min', N'Catch this whimsical holiday film bursting with comical elfin escapades! Based on the classic tale of the Shoemaker and the Elves, Hans the shoemaker is helped by a group of mismatched elves who want to work for Santa Claus. Produced by Golden Films.'),
(720, N's720', N'MOVIE', N'The Christmas Candle', NULL, 2013, N'PG', 100, N'MINUTES', N'100 min', N'Legend has it every 25 years an angel touches a single candle, and whomever lights this candle receives a miracle on Christmas Eve. But in 1890, at the dawn of the electric age, this centuries old legend may come to an end when a progressive young minister arrives. Now, the fiery candlemaker must fight to preserve the legacy of the Christmas Candle. From bestselling author, Max Lucado.'),
(721, N's721', N'MOVIE', N'The Changeling', NULL, 1993, NULL, 90, N'MINUTES', N'90 min', N'Bob Hoskins stars in an adaptation of Thomas Middleton and William Rowley''s classic Jacobean tragedy. A tale of lust and revenge between two ambiguous, guilt-ridden individuals.'),
(722, N's722', N'TV_SHOW', N'The Challenge: ETA', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'The Challenge ETA is an eight-episode documentary series about the Guardia Civil''s fight against the Basque terrorist band ETA. A fight that lasted for half a century, until the dissolution of the band and its definitive renunciation of weapons. The Challenge ETA is an ambitious production that aims to mark a milestone in this important episode of the recent history of Spain.'),
(723, N's723', N'TV_SHOW', N'The Carol Burnett Show', NULL, 1972, N'13+', 1, N'SEASONS', N'1 Season', N'For over a decade, this extravaganza of comedy, song and dance defined entertainment for TV viewers. The Carol Burnett Show brought the actors and audience close together. Beloved for her signature audience Questions and Answers famous Tarzan yell, Burnett''s brilliant troupe stars Harvey Korman, Vicki Lawrence and Lyle Waggoner.'),
(724, N's724', N'MOVIE', N'The Capture', NULL, 1950, N'18+', 102, N'MINUTES', N'102 min', N'Lin Vanner (Ayres) captures and turns in a fellow oil company employee whom he believes was behind a payroll robbery. The accused man dies in police custody, and Lin feels overwhelmingly responsible for the man''s death, wondering if he was actually innocent of the crime. His guilt causes Lin to lose his job and his fiancee, and to soothe his conscience, Lin seeks out the dead man''s widow, Evelyn (Wright). The two fall in love and marry without Evelyn ever knowing about Lin''s past and feelings of guilt. When Lin discovers who really commited the robbery, he goes after the man, who dies accidentally in the ensuing chase. Lin is now accused of murdering the man, and must become a fugitive on the run. This is the lost masterpiece of director John Sturges.'),
(725, N's725', N'MOVIE', N'The Bumble Nums - Season 4', NULL, 2020, N'ALL', 43, N'MINUTES', N'43 min', N'Humble, Stumble and Grumble are back! This time their adventures are taking them to lots of exciting places. There''s riding a shopping cart in Upsidedown Town, swinging on vines in an enchanted forest, surfing in the ocean and trying to capture a colossal cauliflower from an uncharted island!'),
(726, N's726', N'MOVIE', N'The Bridgewater Triangle', NULL, 2013, N'13+', 91, N'MINUTES', N'91 min', N'"The Bridgewater Triangle" hosts an unusually high volume of reports involving strange happenings, baffling mysteries and sinister deeds. From ghostly hauntings and cryptid animal sightings, to UFO encounters and evidence of satanic ritual sacrifice, this 200-square mile region in Southeastern Massachusetts serves as one of the world''s most diverse and well-known hotspots for paranormal activity'),
(727, N's727', N'MOVIE', N'The Bridges at Toko-Ri', NULL, 1955, N'13+', 103, N'MINUTES', N'103 min', N'Set during the Korean War, a Navy fighter pilot must come to terms with his own ambivalence towards the war and the fear of having to bomb a set of highly defended bridges. The ending of this grim war is all tension.'),
(728, N's728', N'MOVIE', N'The Bray Road Beast', NULL, 2020, N'13+', 67, N'MINUTES', N'67 min', N'In the early 1990''s a rural Wisconsin community called Elkhorn was at the center of a series of real-life werewolf sightings. As local reporter, Linda Godfrey, began her investigations into the "Beast of Bray Road".'),
(729, N's729', N'MOVIE', N'THE BRANCH', NULL, 2019, N'ALL', 89, N'MINUTES', N'89 min', N'The employees of the Industrial Zone Branch of the Banco Nacional Obrero, after a long vacation, must return to work and resume their routine, something that will not be easy, because their bosses came up with the idea of conducting a survey of work environment, which will reveal true personalities in the office.'),
(730, N's730', N'MOVIE', N'The Boys of St. Vincent', NULL, 1992, N'16+', 93, N'MINUTES', N'93 min', N'This realistic dramatization follows the desperate struggle by young residents of a Roman Catholic orphanage to escape their nightmare of physical and sexual abuse. Their cries for help go unheeded, although a concerned janitor and a no-nonsense cop wage a personal crusade to uncover the terrible truth, and end the suffering.'),
(731, N's731', N'TV_SHOW', N'The Boys', NULL, 2020, N'18+', 2, N'SEASONS', N'2 Seasons', N'All Episodes Available. In a more intense Season 2 of THE BOYS, Butcher, Hughie and the team reel from their losses in Season 1. On the run from the law, they struggle to fight back against the Superheroes. Meanwhile Vought, the hero management company, cashes in on the panic over Supervillains, and a new hero, Stormfront, shakes up the company and challenges an already unstable Homelander.'),
(732, N's732', N'TV_SHOW', N'The Bold and the Beautiful', NULL, 2015, N'13+', 1, N'SEASONS', N'1 Season', N'The Bold and the Beautiful is a three-time Emmy Award-winning drama set in Los Angeles that tells the story of high fashion glamour, honor, romance, passion and most importantly, family.'),
(733, N's733', N'TV_SHOW', N'The Boat Show', NULL, 2018, N'13+', 1, N'SEASONS', N'1 Season', N'The Boat Show is a program dedicated to nautical lovers and boat owners. It is the only show in the world completely dedicated to the nautical world, made with passion by a team of experts with more than 15 years of experience.'),
(734, N's734', N'TV_SHOW', N'The Block', NULL, 2018, N'13+', 7, N'SEASONS', N'7 Seasons', N'The Block introduces four couples who are taking on one of the potentially most rewarding challenges they will ever face.'),
(735, N's735', N'MOVIE', N'The Black Velvet Gown', NULL, 1993, NULL, 103, N'MINUTES', N'103 min', N'In 1830s England, a mother and daughter fight for a better life and challenge the prejudice of their society in this International Emmy® Award winner for Best Drama.'),
(736, N's736', N'MOVIE', N'The Black Kungfu Experience', NULL, 2013, NULL, 56, N'MINUTES', N'56 min', N'This film focuses on how a group of African American pioneers became respected masters in a subculture dominated by Chinese and white men.'),
(737, N's737', N'MOVIE', N'The Black Candle', NULL, 1991, N'16+', 103, N'MINUTES', N'103 min', N'Joe Skinner marries Lily Whitmore, to give a name to her illegitimate child by Lionel, the opportunistic son of an impoverished aristocrat. Lionel, however, has his sights set on Victoria, the cousin of hard-working Bridget Mordaunt. When Joe''s brother Fred threatens his marriage plans, Lionel murders him and the blame falls on Joe.'),
(738, N's738', N'MOVIE', N'The Bishop''s Wife', NULL, 1948, N'13+', 110, N'MINUTES', N'110 min', N'An angel in human form enters the life of a bishop in order to help him build a new cathedral and repair his fractured marriage.'),
(739, N's739', N'MOVIE', N'The Bigamist', NULL, 1953, N'13+', 79, N'MINUTES', N'79 min', N'Harry and Eve Graham are trying to adopt a baby. The head of the agency senses Harry has a secret and does some investigating. He soon discovers Harry has done an unusual amount of traveling from his home in San Francisco to LA.'),
(740, N's740', N'MOVIE', N'The Big Sleep', NULL, 2007, N'NR', 29, N'MINUTES', N'29 min', N'The Big Sleep play the Insound party - complete with beach balls, cheap beer, and good instrumental music.'),
(741, N's741', N'MOVIE', N'The Big Cat', NULL, 1949, N'18+', 77, N'MINUTES', N'77 min', N'The story of the struggle for survival of a few inhabitants in the "high country" of Utah in 1933, during the worst draught they have ever known in the Great Depression. City boy Danny arrives at his Uncle Gil''s ranch to help the family out. Although lacking in ranch hand skills, the boy manages to save his uncle''s life when a "Big Cat" (a cougar) comes onto the ranch, desperate for the water it needs to survive. A local backwoodsman spends the film trying to track and kill the cougar before it kills a human, and a romance blooms between two young locals. A beautifully filmed outdoor drama.'),
(742, N's742', N'MOVIE', N'The Big Black Comedy Show, Vol. 5', NULL, 2006, NULL, 88, N'MINUTES', N'88 min', N'An outrageously funny stand-up comedy special with an all-star line-up of African American entertainers, hosted by the multi-talented Michael Colyar.'),
(743, N's743', N'TV_SHOW', N'The Beverly Hillbillies', NULL, 1963, N'TV-PG', 1, N'SEASONS', N'1 Season', N'The Clampett family are simple folk, happily living off the land in the Ozarks. They want for nothing and ask for nothing. When Jed Clampett accidentally discovers oil on his family''s property, they strike it rich, becoming millionaires. With their newfound wealth, the Clampetts decide to enter a new life... in Beverly Hills, California.'),
(744, N's744', N'TV_SHOW', N'The Best of The Three Stooges in Color!', NULL, 1936, N'7+', 1, N'SEASONS', N'1 Season', N'The Stooges are back in these hilarious episodes, where you''ll see Larry, Curly, Moe and Shemp perform the comedy that made them famous. Remastered from the original 35mm film elements, these classic Three Stooges shorts are brought to you fully restored and in color, looking better than they ever have before!'),
(745, N's745', N'TV_SHOW', N'The Best of Mister Rogers'' Neighborhood', NULL, 1975, N'TV-Y', 1, N'SEASONS', N'1 Season', N'MISTER ROGERS'' NEIGHBORHOOD is more than a television program - it''s a visit with a trusted friend and guide, exploring with children things that matter in their everyday world - feelings, questions and concerns.'),
(746, N's746', N'TV_SHOW', N'The Bernie Mac Show', NULL, 2006, N'TV-PG', 5, N'SEASONS', N'5 Seasons', N'A stand up comedian suddenly becomes a father when he takes custody of his sister''s three children.'),
(747, N's747', N'MOVIE', N'The Benefactor', NULL, 2016, N'16+', 93, N'MINUTES', N'93 min', N'A newly married couple are forced to navigate the all-consuming interest of a powerful, mysterious, and possessive philanthropist.'),
(748, N's748', N'MOVIE', N'The Beckoning Silence', NULL, 2007, N'13+', 73, N'MINUTES', N'73 min', N'The climber Joe Simpson was 25 when he had an accident that nearly killed him. He wrote a book - Touching the Void - about his extraordinary battle to survive. Now he is going back to the mountain that first him inspired to climb. To tell a story that has haunted him since he was a boy.'),
(749, N's749', N'MOVIE', N'The Beautician And The Beast', NULL, 1997, N'PG', 107, N'MINUTES', N'107 min', N'A New York cosmetologist mistakenly thought to be a science teacher is offered a job to teach the children of an Eastern European dictator.'),
(750, N's750', N'MOVIE', N'The Beastmaster', NULL, 1982, N'13+', 118, N'MINUTES', N'118 min', N'Marc Singer and Tanya Roberts in a sword-and-sorcery fantasy about a young man''s search for revenge. Armed with supernatural powers, the handsome hero and his animal allies wage war against marauding forces.'),
(751, N's751', N'MOVIE', N'The Beach Boys: An American Band', NULL, 1985, N'PG-13', 103, N'MINUTES', N'103 min', N'An authorized biography of the Beach Boys by the band themselves which tracks the band from their early days to the mid-1980s.'),
(752, N's752', N'MOVIE', N'The Basket', NULL, 2000, N'PG', 105, N'MINUTES', N'105 min', N'A picturesque Pacific Northwest community raising its wheat and children in the midst of a nation reeling from World War I sets the stage for The Basket. In a time of pain and prejudice woven against a background of beauty, The Basket ultimately points to triumph and hope in a changing America.'),
(753, N's753', N'MOVIE', N'The Band''s Visit', NULL, 2008, N'PG-13', 87, N'MINUTES', N'87 min', N'A band comprised of members of the Egyptian police force head to Israel to play at the inaugural ceremony of an Arab arts center, only to find themselves lost in the wrong town.'),
(754, N's754', N'TV_SHOW', N'The Ave', NULL, 2021, N'18+', 2, N'SEASONS', N'2 Seasons', N'The Ave centers around inspiring entrepreneurs'' lives, operating a secretive check defrauding business while trying to rise above the gritty streets of Brooklyn, New York.'),
(755, N's755', N'TV_SHOW', N'The Attackers', NULL, 2013, N'13+', 1, N'SEASONS', N'1 Season', N'Set during World War 2. Young air force pilots, Leonid and Boris, arrive at flight training school only to find that they have been enlisted to the active force regiment and will be going directly to the frontline. They are The Attackers and will have to show courage during every moment of battle and execute the most complex military orders, without hesitation or fear for their lives.'),
(756, N's756', N'MOVIE', N'The Astral Factor', NULL, 1977, NULL, 96, N'MINUTES', N'96 min', N'A suspenseful tale of intrigue, murder and the supernatural. After discovering secret methods on how to make himself invisible, a murderer escapes from an institution for the criminally insane and sets out to kill those who testified against him. Detectives must race against time to find him before he finds and kills all his victims.'),
(757, N's757', N'MOVIE', N'The Asian Connection', NULL, 2016, N'R', 92, N'MINUTES', N'92 min', N'Two American expatriates, Jack and Sam, unwittingly steal a drug lord''s money when they rob a series of banks in Southeast Asia and become the target of the gang''s vengeance. When Sam is killed, Jack turns to the love of his life, Pom, and the couple becomes a modern-day Bonnie and Clyde that takes the fight to the gang.'),
(758, N's758', N'MOVIE', N'The Ash Lad: In Search of the Golden Castle', NULL, 2019, N'13+', 98, N'MINUTES', N'98 min', N'When the King and Queen are poisoned, brothers Per and Pål are arrested as suspects. Younger brother Espen "The Ash Lad" and Princess Kristin set out on a quest to find the mythical Soria Moria castle, said to be built of pure gold and contain the Water of Life, which can cure Kristin''s parents. If they fail, it will spell the end for the brothers, the kingdom, and perhaps the entire world.'),
(759, N's759', N'MOVIE', N'The Art of War II: Betrayal', NULL, 2008, N'R', 103, N'MINUTES', N'103 min', N'Agent Neil Shaw is called out of retirement and finds himself in the midst of a plot to assassinate several leading Senators with himself set-up to take the rap for a recent killing.'),
(760, N's760', N'MOVIE', N'The Appleseed Cast', NULL, 2007, N'NR', 49, N'MINUTES', N'49 min', N'Lawrence, KS rockers, the Appleseed Cast, play songs from their new album, "Peregrine."'),
(761, N's761', N'MOVIE', N'The Annuals', NULL, 2007, N'NR', 36, N'MINUTES', N'36 min', N'This North Carolina group, the Annuals, invades NYC''s Webster Hall, reminding all attendees that you can''t properly rock without two able-armed drummers.'),
(762, N's762', N'MOVIE', N'The Angry Red Planet', NULL, 1960, N'13+', 83, N'MINUTES', N'83 min', N'A science-fiction tale of an expedition to the "angry red planet" of Mars...running into all sorts of alien terrors, including unfriendly Martian plants and a terrifying kind of giant mouse/spider hybrid.'),
(763, N's763', N'MOVIE', N'The Amish Shunned', NULL, 2014, N'16+', 112, N'MINUTES', N'112 min', N'The Amish: Shunned follows seven former members of the Amish community as they reflect on their decisions to leave one of the most closed and tightly-knit communities in the United States. Estranged from family, the ex-Amish find themselves struggling to understand and make their way in modern America.'),
(764, N's764', N'MOVIE', N'The Amish and the Reformation', NULL, 2017, N'ALL', 54, N'MINUTES', N'54 min', N'A heartbreaking, yet redemptive journey into the history of the Amish People. The year 2017 is the five hundred year anniversary of Martin Luther nailing the 95 Theses to the church door in Wittenberg and starting the Reformation in Germany. This film considers the impact of the Reformation Era on the Amish Church in America today. Was the work of the Reformers effective?'),
(765, N's765', N'TV_SHOW', N'The Americans', NULL, 2018, N'NR', 6, N'SEASONS', N'6 Seasons', N'The Americans is an FX original drama that stars Keri Russell and Matthew Rhys as undercover KGB spies during the Cold War.'),
(766, N's766', N'TV_SHOW', N'The American West', NULL, 2016, N'TV-14', 1, N'SEASONS', N'1 Season', N'From Executive Producer Robert Redford, The American West tells the story of the aftermath of the Civil War and how the United States transformed into the "land of opportunity."'),
(767, N's767', N'TV_SHOW', N'The American Dream Project', NULL, 2015, N'7+', 1, N'SEASONS', N'1 Season', N'Filmmaker James Marshall and his friend Todd Williams embark on an iconic journey across the United States determined to rediscover the American dream. Through the stories of individuals they encounter along the way, they find that the optimistic spirit that built this country is still very much alive.'),
(768, N's768', N'TV_SHOW', N'The American Civil War: A Union Divided', NULL, 2019, N'18+', 1, N'SEASONS', N'1 Season', N'During four dark years of bitter and bloody fighting between the northern and southern states, more than six hundred thousand troops from both sides lost their lives. Towns and cities were destroyed. The country was torn apart as the military, political and ideological struggle dragged on and on.'),
(769, N's769', N'TV_SHOW', N'The Amazing World Of War Machines', NULL, 2008, N'7+', 1, N'SEASONS', N'1 Season', N'From gunpowder to the Gatling gun, the first tank to the latest unmanned drones, we review the mechanisms and machinery man has created to wage war. Historical achievements through to modern day technologies are examined as we travel land, sea and air in this comprehensive, fascinating chronological journey of war machines.'),
(770, N's770', N'TV_SHOW', N'The Amazing World Of Aviation Series - 13-Part', NULL, 2013, N'ALL', 1, N'SEASONS', N'1 Season', N'When the Wright brothers successfully took to the sky in 1903, the world paid attention. Civil aviation has since developed into a multi-billion dollar industry. We look at the incredible history and development of civil aviation in this series. From ailed beginnings through to modern marvels such as the Boeing 787, we present 13 themed episodes suitable for all audiences.'),
(771, N's771', N'TV_SHOW', N'The Amazing Race', NULL, 2017, N'TV-PG', 29, N'SEASONS', N'29 Seasons', N'In a brand new twist, all 22 Racers are complete strangers who will meet on the starting line. Before "GO," Racers will immediately compete in a challenge that will determine the order for picking a Teammate, based on nothing but first impressions. Phil Keoghan hosts.'),
(772, N's772', N'MOVIE', N'The Amazing Adventure', NULL, 1937, N'13+', 62, N'MINUTES', N'62 min', N'Ernest must earn his own living for one year using none of his current wealth. Ernest bets him 50,000 English pounds that he can.'),
(773, N's773', N'TV_SHOW', N'The Aliens', NULL, 2016, N'TV-MA', 1, N'SEASONS', N'1 Season', N'Aliens have landed in the UK and are now unwanted immigrants living in a walled off section of town. Lewis is a border guard making sure aliens and humans remain separate, but when he discovers that he''s half alien, his whole world is turned on its head.'),
(774, N's774', N'MOVIE', N'The African Queen', NULL, 1952, N'13+', 105, N'MINUTES', N'105 min', N'In Africa during WW1, a gin-swilling riverboat owner/captain is persuaded by a strait-laced missionary to use his boat to attack an enemy warship.'),
(775, N's775', N'MOVIE', N'The Affairs of Cappy Ricks', NULL, 1937, N'13+', 58, N'MINUTES', N'58 min', N'Captain Cappy Ricks returns home after an extended trip overseas to find his daughter engaged to a man he doesn''t approve of, his shipping business taken over by his future mother-in-law, his beloved yacht completely automated, and it appears no one in the family will honor his authority anymore. So he makes a plan with his friend Bill (Talbot) to trap his entire family on board the yacht, to try to gain back his position as the head of the family by bossing everyone around, which backfires. Then Cappy and Bill fake a fire on board to shipwreck the family on an island as a last resort, but the plan goes wrong once again, and the whole group becomes shipwrecked for real! A zany comedy filled with great laughs and slapstick mis-adventures.'),
(776, N's776', N'TV_SHOW', N'The Affair', NULL, 2019, N'TV-MA', 5, N'SEASONS', N'5 Seasons', N'Noah and Helen must face their past in order to truly move on.'),
(777, N's777', N'TV_SHOW', N'The Adventures of Tintin', NULL, 2019, N'7+', 3, N'SEASONS', N'3 Seasons', N'The show tells the story of a young Belgian reporter named Tintin, and all the dangerous, exciting and humorous adventures he has all over the world.'),
(778, N's778', N'MOVIE', N'The Admiral Was A Lady', NULL, 1950, N'13+', 102, N'MINUTES', N'102 min', N'Ex-WAVE encounters four fun-loving, work-hating men, all of whom want to marry her.'),
(779, N's779', N'TV_SHOW', N'The A Word', NULL, 2016, N'TV-NR', 2, N'SEASONS', N'2 Seasons', N'Two years on, Joe knows he is different. As he starts to struggle, it''s up to his family to help him make sense of the world.'),
(780, N's780', N'MOVIE', N'The 5th King- Iran "The Blade" Barkley Story', NULL, 2019, N'13+', 66, N'MINUTES', N'66 min', N'The 5th King is a compelling first hand account of the rise and fall of one of boxing''s legendary fighters from the golden era of boxing. Iran "The Blade" Barkley escaped the major pitfalls of his economic depressed area of South Bronx to become 3-time boxing champ of the world only to endure tragedy events after boxing.'),
(781, N's781', N'MOVIE', N'The 36th Chamber of Shaolin', NULL, 1978, N'R', 112, N'MINUTES', N'112 min', N'This internationally renowned, award-winning, trailblazing masterpiece broke all the rules (and box-office records). The legendary director''s charismatic adoptive brother stars as an anti-Ching rebel who learns what it truly takes to be a martial arts master, chamber by challenging chamber...'),
(782, N's782', N'MOVIE', N'That Uncertain Feeling', NULL, 1941, N'PG', 94, N'MINUTES', N'94 min', N'Six years into their marriage, Jill Baker (Oberson) contracts a case of recurring hiccups. Her busy husband Larry (Douglas) sends Jill to Freudian psychologist Vengard and he concludes that the hiccups are caused by her marital problems. When Jill meets hilarious but highly neurotic concert pianist Sebastian (Meredith) in the doctor''s waiting room, she decides to begin a relationship with Sebastian and file for divorce. Larry, still in love with Jill, initially agrees, but the separation doesn''t last long and they reunite after a multitude of hilarious hijinks. Meredith steals the film.'),
(783, N's783', N'MOVIE', N'That Sugar Film', NULL, 2015, N'7+', 102, N'MINUTES', N'102 min', N'In the vein of "Supersize Me", Damon Gameau becomes a human guinea-pig when he puts himself through a grueling 6 week diet consuming the equivalent of 40 teaspoons of sugar a day.'),
(784, N's784', N'MOVIE', N'Thappad (4K UHD)', NULL, 2020, N'13+', 142, N'MINUTES', N'142 min', N'Thappad is a story of Amrita whose seemingly perfect life is shattered when her husband slaps her once in a party. But is one slap enough to question what a relationship stands for?'),
(785, N's785', N'MOVIE', N'Thappad', NULL, 2020, N'13+', 142, N'MINUTES', N'142 min', N'Thappad is a story of Amrita whose seemingly perfect life is shattered when her husband slaps her once in a party. But is one slap enough to question what a relationship stands for?'),
(786, N's786', N'MOVIE', N'Thao and the Get Down Stay Down', NULL, 2011, N'NR', 56, N'MINUTES', N'56 min', N'The first thing you''re bound to notice here is Thao Nguyen, a spirited musician sicking erratic, electric scratches into her surely beaten-all-to-hell hollow body guitar.'),
(787, N's787', N'TV_SHOW', N'Texas Rising', NULL, 2015, N'TV-14', 1, N'SEASONS', N'1 Season', N'Picking up right after the Alamo, this gritty historical drama reveals the origins of the Texas Rangers through the eyes of soldiers on both sides of the conflict. This true-story Western features an all-star cast, including Bill Paxton ("Aliens"), Jeffrey Dean Morgan ("The Walking Dead"), Crispin Glover ("Back to the Future"), Ray Liotta ("Goodfellas") and Brendan Fraser ("The Mummy").'),
(788, N's788', N'MOVIE', N'Texas Legionaires', NULL, 1943, N'13+', 55, N'MINUTES', N'55 min', N'Roy returns home to find a range feud between the cattlemen and the sheepmen.'),
(789, N's789', N'MOVIE', N'Testing title - Parichey is using this title', NULL, 2020, N'ALL', 0, N'MINUTES', N'0 min', N'Test movie for upload'),
(790, N's790', N'MOVIE', N'Terrordactyl', NULL, 2016, N'18+', 98, N'MINUTES', N'98 min', N'When a meteor shower rains down outside Los Angeles, Jonas and Lars head out to find a meteor and strike it rich. After recovering one, they start being stalked by terrordactyls, flying reptiles that launch a full-on assault on the city. Trying to survive, they go on the run with Candice, a bartender; Valerie, her sultry roommate; and Sampson, a brash ex-marine.'),
(791, N's791', N'MOVIE', N'Terror By Night', NULL, 1946, N'PG', 56, N'MINUTES', N'56 min', N'Sherlock Holmes solves mystery of stolen diamond on a London-to-Edinburgh train.'),
(792, N's792', N'MOVIE', N'Tennessee Queer', NULL, 2014, N'16+', 90, N'MINUTES', N'90 min', N'Religion, politics and gay pride clash in a small Tennessee town when out, proud and living in New York Jason Potts returns home to make life better for the LGBT teenagers.'),
(793, N's793', N'MOVIE', N'Tenkai Knights - Rise of the Knights', NULL, 2014, N'ALL', 72, N'MINUTES', N'72 min', N'Ripped through space and time, four teenagers emerge in a new world where everything can transform and shape shift. The unlikely heroes use their powers to stop an evil army of shape shifting robots from destroying two worlds.'),
(794, N's794', N'TV_SHOW', N'Tenkai Knights', NULL, 2014, N'TV-Y7', 1, N'SEASONS', N'1 Season', N'Teens from earth Guren, Ceylan, Toxsa, and Chooki find an interdimensional portal to Quarton where they are chosen by the Guardians to become the new generation of Tenkai Knights and prevent Vilius to take control of both worlds.'),
(795, N's795', N'MOVIE', N'Templar Nation', NULL, 2013, N'13+', 84, N'MINUTES', N'84 min', N'After an archaeologist and his students excavate a Templar Knight''s tomb, they are thrown into the middle of an ancient blood feud. They must either follow the Templar''s ancient path or face destruction at the hands of a dark league of assassin.'),
(796, N's796', N'TV_SHOW', N'Telmo and Tula: Volume 3', NULL, 2016, N'ALL', 1, N'SEASONS', N'1 Season', N'Join Telmo and Tula for more fun-filled adventures in the world of cooking and crafts!'),
(797, N's797', N'TV_SHOW', N'Tell Me Your Secrets', NULL, 2021, N'16+', 1, N'SEASONS', N'1 Season', N'Tell Me Your Secrets is a complex thriller revolving around three characters, each with troubling pasts clouding their intersecting motives: Emma (Lily Rabe) is a young woman who once loved a dangerous killer, John (Hamish Linklater) is a former serial predator desperate for redemption, and a grieving mother Mary (Amy Brenneman) who is obsessed with finding her missing daughter.'),
(798, N's798', N'MOVIE', N'Tel Aviv On Fire', NULL, 2019, N'13+', 96, N'MINUTES', N'96 min', N'Salam, an inexperienced young Palestinian man, becomes a writer on a popular soap opera after a chance meeting with an Israeli soldier. His creative career is on the rise - until the soldier and the show''s financial backers disagree about how the show should end, and Salam is caught in the middle.'),
(799, N's799', N'MOVIE', N'Teenkahon', NULL, 2014, N'18+', 124, N'MINUTES', N'124 min', N'Teenkahon (Three Obsessions) is a triptych film in Bengali by debutant filmmaker Bauddhayan Mukherji. It is a rare international art house film from Bengal which, as a piece of social document, tries to capture the changing face of morality, the degeneration of values, the increasing pollution of the spoken language and the changing social fabric of Bengal through three stories.'),
(800, N's800', N'MOVIE', N'Teenage Bank Heist', NULL, 2012, NULL, 86, N'MINUTES', N'86 min', N'When a teenager is kidnapped during a daring bank robbery, her mother vows to find her.');

He cannot stay away from the bath houses, once he sees one. Once inside the bath... there awaits a little piece of heaven.'),
(859, N's859', N'TV_SHOW', N'Sunshine Sento-Sake (Subbed)', NULL, 2016, N'TV-NR', 1, N'SEASONS', N'1 Season', N'Takayuki Utsumi (Shigeyuki Totsugi) is a 42-year-old salesman. A year ago, he was transferred to the sales department, but he is always at the bottom of the sales pyramid. What keeps him going, is ditching work and going to the "Sento" (bath house) during the day, on weekdays.
He cannot stay away from the bath houses, once he sees one. Once inside the bath... there awaits a little piece of heaven.'),
(860, N's860', N'MOVIE', N'Sunshine Hotel', NULL, 2002, N'13+', 99, N'MINUTES', N'99 min', N'[Remastered 2017] As seen on Sundance Channel. A journey into the last "flophouse" on New York City''s infamous skidrow, The Bowery. Filmmaker Michael Dominic takes his camera behind the doors of the Sunshine Hotel, one of the few remaining affordable refuges for the destitute and out of luck, a world that has seemingly stood still for more than eight decades.'),
(861, N's861', N'MOVIE', N'Sunset On The Desert', NULL, 1942, N'PG', 55, N'MINUTES', N'55 min', N'Roy''s strong resemblance to a notorious crook gives him a chance to infiltrate the gang, but the usual complications arise when the look-alike desperado returns. It''s fun to watch Roy Rogers play the tough guy.'),
(862, N's862', N'MOVIE', N'Sunrise on the Bosphorus', NULL, 2019, N'ALL', 30, N'MINUTES', N'30 min', N'Relax with a beautiful sunrise over the Bosphorus Strait overlooking the world famous Bosphorus Bridge. Filmed in early summer, the strait comes to life with birds, boats as early morning slowly turns into day.'),
(863, N's863', N'MOVIE', N'Sunnyside', NULL, 1979, N'R', 101, N'MINUTES', N'101 min', N'An emotionally charged saga of explosive violence and romance set in New York City as a family fight for survival in an area infested by street gangs.'),
(864, N's864', N'TV_SHOW', N'Sunny Bunnies', NULL, 2018, N'TV-Y', 2, N'SEASONS', N'2 Seasons', N'Our little fluffy-eared friends Sunny Bunnies like keeping themselves busy and continue to do so in Season 3: they discover the world of magic, getting sporty, constructing things, growing plants, explore different cultures and even race the Wolf in their little racing cars!'),
(865, N's865', N'MOVIE', N'Sundown Saunders', NULL, 1935, N'PG', 70, N'MINUTES', N'70 min', N'Sundown Saunders (Steele) wins a ranch on a prime piece of property, but when he arrives there with his friend Smokey, he finds Dad Preston and his daughter Bess already living on the ranch. The Prestons are close to buying the ranch from Taggart, a criminal posing an an offical Federal land agent. Taggart shoots Mace, one of his own men, pinning the act on Sundown. Taggart ambushes Dad Preston to retrieve the fake deed and plans to rob the bank. Mace tells the Sheriff before he dies that Sundown didn''t shoot him and of the robbery plans. A posse is formed leading to a final exciting showdown.'),
(866, N's866', N'MOVIE', N'Sundown', NULL, 1941, N'7+', 90, N'MINUTES', N'90 min', N'In Africa, during World War II, British major Coombescannot abide the local Arab population, and has even less time for district commissioner Crawford, who has befriended the natives.'),
(867, N's867', N'TV_SHOW', N'Summer 2019 American Road Trip', NULL, 2020, N'7+', 1, N'SEASONS', N'1 Season', N'One man''s dream to drive cross-country and see the extreme points of the contiguous mainland United States'),
(868, N's868', N'TV_SHOW', N'Suits', NULL, 2019, N'NR', 9, N'SEASONS', N'9 Seasons', N'Suits centers on a fast-paced Manhattan corporate law firm led by legendary lawyer Harvey Specter (Gabriel Macht), his intelligent but delicate partner, Louis Litt (Rick Hoffman), and secretary-turned-COO Donna Paulsen (Sarah Rafferty).'),
(869, N's869', N'MOVIE', N'Suicide', NULL, 2001, N'18+', 84, N'MINUTES', N'84 min', N'A young couple film people committing suicide and broadcast the deaths on their up-and-coming website!'),
(870, N's870', N'MOVIE', N'Sui Dhaaga - Made In India', NULL, 2018, N'7+', 122, N'MINUTES', N'122 min', N'"Sui Dhaaga - Made in India" is a heart-warming story of pride and self-reliance. Through Mauji (Varun Dhawan) & his wife Mamta (Anushka Sharma), the film talks about the need of entrepreneurship as a tool for social & economic development of our artisans. Set in a small town in India, it is the journey of an honest man from a humble background,who pursues his passion, overcoming all odds'),
(871, N's871', N'MOVIE', N'Sufiyum Sujatayum', NULL, 2020, N'13+', 123, N'MINUTES', N'123 min', N'Dr. Rajeev (Jayasurya) and his wife SUJATA (Aditi rao hydari) come from Dubai to participate in the last rituals of Sujata''s friend and ex love affair who was a Sufi. The events which happen when they land in the village forms the rest of the plot.'),
(872, N's872', N'TV_SHOW', N'Subaru Launch Control', NULL, 2021, N'13+', 3, N'SEASONS', N'3 Seasons', N'Season 8 documents a year of upheaval and persistence including an all-new rally driver lineup with Travis Pastrana and Brandon Semenuk, a season delayed and shortened by COVID-19, and the return of rallycross ace Scott Speed after a season-ending back injury. The season concludes with a two-part miniseries covering the build of a one-off car for Subaru''s return to the gymkhana franchise.'),
(873, N's873', N'MOVIE', N'Student of the Year 2', NULL, 2019, N'13+', 146, N'MINUTES', N'146 min', N'Rohan (Tiger Shroff) is a student, athlete from a mediocre Pishorilal Chamandas College. He dreams of becoming the Student of the Year one day. His life takes a turn, when he gets accepted to St. Teresa College, encounters his rival Manav & has the beautiful Shreya and Mia who begin to fall for him. Their life gets tangled through competition, failure, manipulation and heartbreaks.'),
(874, N's874', N'MOVIE', N'Striking Range', NULL, 2006, N'R', 96, N'MINUTES', N'96 min', N'Ted Billings (Glenn Morshower) is a corrupt businessman in need of protection. His security chief, Emily (Yancy Butler), recommends her former lover Vash (Lou Diamond Phillips), an experienced mercenary with an arsenal of weapons he''s itching to use.'),
(875, N's875', N'TV_SHOW', N'Streets of Compton', NULL, 2016, N'TV-14', 1, N'SEASONS', N'1 Season', N'Streets of Compton, a three-part documentary film, features rapper The Gam as he revisits his hometown of Compton and explores its storied history with notable residents.'),
(876, N's876', N'MOVIE', N'Street Dance', NULL, 2013, N'13+', 99, N'MINUTES', N'99 min', N'A high-energy dance drama about a street dance crew and a group of Royal ballet dancers. The two groups form an unlikely alliance and created an exciting new form of modern dance.'),
(877, N's877', N'MOVIE', N'Strategic Air Command', NULL, 1955, N'7+', 114, N'MINUTES', N'114 min', N'Aviation and sports come together as a baseball player is recalled to Air Force duty.'),
(878, N's878', N'MOVIE', N'Strange Wilderness', NULL, 2008, N'R', 85, N'MINUTES', N'85 min', N'With the ratings dropping for a wilderness-themed television show, two animal fans go to the Andes Mountains in search of Bigfoot.comed'),
(879, N's879', N'TV_SHOW', N'Strange Love', NULL, 2005, N'16+', 1, N'SEASONS', N'1 Season', N'Fans of The Surreal Life on VH1 know that Brigitte Nielsen and Flavor Flav made a splash together in and out of the swimming pool. Now, VH1 is reuniting the ghetto-flash and Euro-trash duo to see if their love is the real deal. Brigitte, now back at her home in Milan living her clothing-optional lifestyle, can''t stop thinking about her rambunctious "Fuffy-Fuffy." Was it just a fling?'),
(880, N's880', N'TV_SHOW', N'Strange Empire Series', NULL, 2015, N'13+', 1, N'SEASONS', N'1 Season', N'With most of their men gone, and those who remain battling for control, the women struggle to survive, to find their independence, and to build a life in which to thrive and raise families. As the stories of Janestown''s citizens unfold we see the clash between a power-hungry father and son and the deep prejudices among races, but also the start of something akin to community in this Wild West.'),
(881, N's881', N'MOVIE', N'Straight Shooter', NULL, 1940, N'13+', 48, N'MINUTES', N'48 min', N'Federal Agent "Lightning" Bill Carson (McCoy) is on the trail of a gang of outlaws who robbed a train carrying half a million dollars in government bonds, killing an agent in the process. Gang leader Brainard murders one of his men after he reveals where he hid the stolen bonds on a ranch up for auction. Carson goes undercover as rancher Sam Brown to fight Brainard for ownership of the ranch. With Tim McCoy advertised as one of the fastest guns in Hollywood in the late 1930''s, there is plenty of fast gun fights and action scenes to highlight McCoys prowess with a gun.'),
(882, N's882', N'MOVIE', N'Storytime with Mila and Morphle', NULL, 2019, N'ALL', 38, N'MINUTES', N'38 min', N'In this compilation of My Magic Pet Morphle, watch Morphle as he morphs into Mila, a big red truck, and a big red magical reindeer!'),
(883, N's883', N'MOVIE', N'Storm Boy', NULL, 2019, N'PG', 99, N'MINUTES', N'99 min', N'When Michael Kingley, a successful retired businessman starts to see images from his past that he can''t explain, he''s forced to remember his childhood and how, as a boy, he rescued and raised an extraordinary orphaned pelican, Mr Percival. Based on the classic Australian novel. Earned the coveted DOVE Seal of Approval.'),
(884, N's884', N'TV_SHOW', N'Storage Wars: Texas', NULL, 2012, N'TV-14', 1, N'SEASONS', N'1 Season', N'The stakes are high and the drama intense in the Lone Star State as Storage Wars follows five Dallas storage unit hunters in their quest for auction gold.'),
(885, N's885', N'TV_SHOW', N'Storage Wars: Northern Treasures', NULL, 2014, N'TV-14', 1, N'SEASONS', N'1 Season', N'At storage auctions in Canada, high-stakes buyers convene daily, bidding against one another on repossessed and forgotten storage units. Following four teams of bidders looking to score big, Storage Wars Canada is a modern-day treasure hunt. Armed with a flashlight, an expert eye and a unique instinct, bidders use their combined knowledge, expertise and wit to outbid one another and score big.'),
(886, N's886', N'TV_SHOW', N'Storage Wars New York', NULL, 2013, N'TV-PG', 1, N'SEASONS', N'1 Season', N'Everyone''s favorite modern-day treasure hunters continue on their quest for the extraordinary in an action packed all-new season of dramatic bidding, intense rivalries and high-stakes entertainment.'),
(887, N's887', N'TV_SHOW', N'Storage Wars', NULL, 2011, N'TV-14', 1, N'SEASONS', N'1 Season', N'Packed with dramatic bidding, intense rivalries and quirky personalities, "Storage Wars" follows treasure hunters Darrell, Brandon, Jarrod, and Brandi as they seek to score big.'),
(888, N's888', N'MOVIE', N'Stop Making Sense', NULL, 1984, N'7+', 88, N'MINUTES', N'88 min', N'Stop Making Sense is director Jonathan Demme''s remarkable concert film that captures the enormous energy and joyous highs of the Talking Heads live performance.'),
(889, N's889', N'MOVIE', N'Stitches', NULL, 2012, N'R', 86, N'MINUTES', N'86 min', N'In this deliriously twisted slasher comedy, vile and foul-mouthed hired clown Stitches meets an untimely end thanks to a party prank gone horribly - and hilariously - awry. Years later, he returns from the grave, ready for revenge...'),
(890, N's890', N'MOVIE', N'Still Today', NULL, 2020, NULL, 82, N'MINUTES', N'82 min', N'After being left at the altar, Pete''s groomsman give him a wedding gift he''ll never forget. An escort. Maybe it''s the Lunar Eclipse, maybe it''s fate, but after a magical night in the city maybe this girl is what Pete needed all along.'),
(891, N's891', N'MOVIE', N'Still Mine', NULL, 2013, N'PG-13', 103, N'MINUTES', N'103 min', N'James Cromwell gives a tour de force performance in ''Still Mine,'' a deeply moving love story about a couple in their twilight years. When Craig sets out to build a more suitable house for his ailing wife Irene, he is blindsided by the bureaucratic codes and officials. As Irene becomes increasingly ill, Craig takes a final stance against all odds to finish the house, in a truly inspirational story.'),
(892, N's892', N'MOVIE', N'Sticky Fingers', NULL, 1988, N'PG-13', 85, N'MINUTES', N'85 min', N'This comedic fable is about two broke musicians, Lolly and Hattie on the run from the Chinese Mafia because of a bag of drug money left in their apartment. They start to borrow the money to replace their stolen instruments and pay their rent.'),
(893, N's893', N'MOVIE', N'Stick Man', NULL, 2015, N'ALL', 27, N'MINUTES', N'27 min', N'A half-hour animation based on the much-loved children''s picture book by Julia Donaldson and Axel Scheffler. Stick Man tells the tale of a happy-go-lucky father''s epic adventure across the seasons as he runs from a playful dog, gets thrown in a river, escapes from a swan''s nest and even ends up on top of a fire. Will he get back to his family in time for Christmas?'),
(894, N's894', N'TV_SHOW', N'Steven Seagal Lawman', NULL, 2010, N'TV-14', 2, N'SEASONS', N'2 Seasons', N'Steven Seagal doesn''t come to the rescue in just his movies. "Steven Seagal: Lawman" follows the action star and real-life sheriff''s deputy as he and his team respond to crimes in progress in Jefferson Parish, Louisiana.'),
(895, N's895', N'MOVIE', N'Steve Treviño: My Life In Quarantine', NULL, 2020, N'18+', 72, N'MINUTES', N'72 min', N'Steve Treviño''s new comedy special is about his life in quarantine. On September 12th, Steve Trevino performed this once in a lifetime show outdoors, in-front of a masked, socially distanced audience. Plus stick around after the special for the live taping of Steve''s hit podcast "Steve Treviño & Captain Evil: The Podcast.'),
(896, N's896', N'MOVIE', N'Steve Hofstetter: Ginger Kid', NULL, 2015, N'7+', 65, N'MINUTES', N'65 min', N'Recorded live at the historic Chinese Theatre in Hollywood, Ginger Kid is Steve Hofstetter''s 6th album. A dark and honest look at subjects ranging from growing up with red hair to population control, this hour-long special is Hofstetter''s best yet.'),
(897, N's897', N'MOVIE', N'Steve Byrne: The Byrne Identity', NULL, 2010, N'18+', 73, N'MINUTES', N'73 min', N'Steve Byrne has established himself as one of the premier stand-up comedians of his generation.'),
(898, N's898', N'TV_SHOW', N'Stephen Fry: Gadget Man', NULL, 2012, N'TV-14', 1, N'SEASONS', N'1 Season', N'Writer, comedian and TV icon Stephen Fry demonstrates wonderful new innovations designed to make our lives just a bit easier in this tech-driven reality talk show.'),
(899, N's899', N'MOVIE', N'Stepfather 2', NULL, 1989, N'R', 84, N'MINUTES', N'84 min', N'After escaping the insane asylum in which he was incarcerated, the Stepfather impersonates a marriage counselor and manages to win over a patient and her young son.'),
(900, N's900', N'MOVIE', N'Step On It', NULL, 1935, N'13+', 56, N'MINUTES', N'56 min', N'Motorcycle cop Larry Evans (Richard Talmadge) is fired from the force unfairly after arresting a speeding heiress. He attempts to solve a string of truck hijackings in order to clear his name and return to the force, but faces many obstacles and a great deal of danger.'),
(901, N's901', N'MOVIE', N'Stella Dallas (1937)', NULL, 1937, N'13+', 106, N'MINUTES', N'106 min', N'A working-class woman is willing to do whatever it takes to give her daughter a socially promising future.'),
(902, N's902', N'MOVIE', N'Steep', NULL, 2007, N'13+', 90, N'MINUTES', N'90 min', N'The world''s best skiers go beyond their wildest dreams to conquer the steepest runs ever faced. Fantastically beautiful images, along with devastating avalanches and fatal spills only serve to push them harder - higher – and faster.'),
(903, N's903', N'MOVIE', N'Stealing Paradise', NULL, 2012, NULL, 89, N'MINUTES', N'89 min', N'Amanda, a brilliant engineer, is enraged when her breakthrough design is stolen and patented by her colleague Brendan. When he is found murdered, Amanda is the prime suspect and soon finds she is not only fighting for her design - but for her life - as someone out there is determined to silence her protest for good.'),
(904, N's904', N'TV_SHOW', N'State of Mind', NULL, 2003, N'16+', 1, N'SEASONS', N'1 Season', N'Grace Hazlett, reeling from the brutal discovery of her husband''s adultery, takes their young son Adam to move back to her old family home. Her mother Isabel, now widowed, is a busy GP and set in her own ways.'),
(905, N's905', N'TV_SHOW', N'StarTalk with Neil deGrasse Tyson', NULL, 2019, N'NR', 1, N'SEASONS', N'1 Season', N'Host Neil deGrasse Tyson brings together a rare mix of personalities, including celebrities, comedians and leading scientific experts, to explore a variety of cosmic topics.'),
(906, N's906', N'TV_SHOW', N'Star Trek: Voyager', NULL, 2001, N'TV-PG', 7, N'SEASONS', N'7 Seasons', N'In Season 7, Janeway leads the crew through a fierce fight against the Borg drones; delves into political infighting; wrestles her way out of a void; and, finally, makes her way back home.'),
(907, N's907', N'TV_SHOW', N'Star Trek: The Next Generation', NULL, 1994, N'NR', 7, N'SEASONS', N'7 Seasons', N'The seventh and final season of this beloved sci-fi series begins with Data (Brent Spiner) experiencing negative emotions such as anger, while his lookalike "brother," Lore, leads a dangerous, independent faction of Borg to destroy all organic life.'),
(908, N's908', N'TV_SHOW', N'Star Trek: Enterprise', NULL, 2005, N'TV-PG', 4, N'SEASONS', N'4 Seasons', N'Led by Capt. Jonathan Archer (Scott Bakula), the crew of the USS Enterprise rides high once more, hurtling through time and space in search of its ultimate destiny.'),
(909, N's909', N'TV_SHOW', N'Star Trek: Deep Space Nine', NULL, 1999, N'TV-PG', 7, N'SEASONS', N'7 Seasons', N'The mixed Deep Space Nine crew of Federation and Bajoran officers winds up the seventh and final season of the show with suspenseful episodes that try to pull together all the plot threads (or at least the biggest ones).'),
(910, N's910', N'TV_SHOW', N'Star Trek:  The Original Series', NULL, 1969, N'TV-PG', 3, N'SEASONS', N'3 Seasons', N'The year is 2268. It''s not going to be a good year for Captain James T. Kirk.'),
(911, N's911', N'TV_SHOW', N'Star Trek Original (Remastered)', NULL, 1969, N'TV-PG', 3, N'SEASONS', N'3 Seasons', N'In the final season of this groundbreaking sci-fi series, Kirk tries to track down Spock''s (Leonard Nimoy) stolen brain, reenacts the shootout at the O.K. Corral and gets trapped between dimensions.'),
(912, N's912', N'MOVIE', N'Stallone: Frank, That Is', NULL, 2021, N'7+', 73, N'MINUTES', N'73 min', N'An inside look into the fascinating life, career and survival of the most unknown famous entertainer in Hollywood. Frank Stallone has seen and done it all. But, who is Frank Stallone? You know the name, now discover the Grammy and Golden Globe nominated singer, songwriter, musician and actor who has been entertaining audiences for over fifty years, all the while living in a giant shadow.'),
(913, N's913', N'TV_SHOW', N'Stalker', NULL, 2008, N'16+', 1, N'SEASONS', N'1 Season', N'"Stalker" reconstructs the behavior of dangerous and obsessed stalkers, diving into their psychological profiles using police reports and testimony from victims and their families.'),
(914, N's914', N'MOVIE', N'Stalked By My Doctor', NULL, 2015, NULL, 88, N'MINUTES', N'88 min', N'Sophie has a bright future ahead, but when a terrible accident threatens to derail everything she''s worked for, the renowned Dr. Albert Beck is able to save her life. As Sophie recovers, Dr. Beck develops a strange obsession over Sophie and kidnaps her. With time running out, it is now up to Sophie to escape from the maniacal Dr. Beck.'),
(915, N's915', N'MOVIE', N'Stained Glass Windows', NULL, 2010, N'16+', 88, N'MINUTES', N'88 min', N'After suffering abuse from her boyfriend and bullying at school, goth girl Cherry (Emelie O''Hara) turns to martial arts to create a new life for herself. As she becomes stronger in body and spirit, she finds herself drawn to a new kind of life. Cherry begins to rid herself of her unhealthy relationships and comes to terms with her nascent homosexuality.'),
(916, N's916', N'MOVIE', N'Stained', NULL, 2011, N'16+', 91, N'MINUTES', N'91 min', N'Isabelle struggles to hold her loveless existence, and her sanity together as loneliness continue to mount. When her former lover" James" suddenly appear in her shop, she decides to chance another romantic relationship. As the twists and turns of Isabelle''s present reveal and resurrect her history, paranoia sets in. To whom does Isabelle''s romance pose the greatest threat?'),
(917, N's917', N'MOVIE', N'Stagecoach - The Original John Wayne Classic', NULL, 1939, N'7+', 96, N'MINUTES', N'96 min', N'A stagecoach sets off across the untamed wilderness carrying a mixed assortment of characters whose journey is complicated by an Apache raiding party. Directed by John Ford, the original 1939 Stagecoach has long been recognized as one of the most influential films ever made & transcends the Western genre. Winner of 2 Academy Awards & 5 Nominations, it features John Wayne in his breakthrough role!'),
(918, N's918', N'MOVIE', N'Stage Door Canteen', NULL, 1943, N'13+', 135, N'MINUTES', N'135 min', N'A war time romance bloomes in WWII between canteen hostess Eileen and visiting soldier Dakota at New York''s famous Stage Door Canteen. Their story provides the backdrop for showing the greatest film, stage, comedy, and musical actors of the day performing multiple plays, acts, and musical numbers, or serving drinks and food to U.S. servicemen at this famous non-profit establishment. See the likes of Katherine Hepburn, Helen Hayes, Kenny Baker, Ralph Bellamy, Charlie McCarthy, Ray Bolger, Tallulah Bankhead, Jean Hersholt, Gypsy Rose Lee, Harpo Marx, Johnny Weissmuller, and many more in this star-studded production. At the time, profits for this film were entirely donated to various wartime fundraising efforts.'),
(919, N's919', N'MOVIE', N'Springtime in the Sierras', NULL, 1947, N'PG', 53, N'MINUTES', N'53 min', N'A criminal gang, headed by female ringleader Jean Loring (Bachelor), runs a racket where they slaughter game out of season and sell the meat on the black market. Roy becomes involved when his best friend, a game warden, is murdered by Loring''s main henchman Matt Wilkes (Barcroft). In his investigation, Roy manages to find the freezer where the meat is kept, just as Wilkes finds him. A famous fight between the two ensues in the freezer, with the good camerawork highlighting the cramped spaced used for the fight. Roy of course wins, and manages to bring the members of the gang to justice. There are many songs sung in this picture by Roy Rogers, his sweetheart Jane Frazee, and Andy Devine.'),
(920, N's920', N'MOVIE', N'Spring 1941', NULL, 2007, N'R', 100, N'MINUTES', N'100 min', N'Dr. Artur Planck and his family are seeking shelter from Germans storming Poland. They find a safe house in the farm of Emilia. Amidst the horrors of the war that surround them, an impossible love triangle erupts as Emelia uncontrollably falls in love with Artur. Such a fragile arrangement is sustained by love - or is it just the will to survive?'),
(921, N's921', N'MOVIE', N'Spooks Run Wild', NULL, 1941, N'PG', 71, N'MINUTES', N'71 min', N'The East Side Kids are sent to a mountain camp. Stranded in a small rural town, they hear about a "monster killer" roaming the countryside. At night, they sneak out. Peewee is shot by a grave-digger, and they are forced to seek aid at an old mansion. The owner of the mansion (Lugosi), insists that the boys spend the night. After seeing PeeWee walk around the house in a trance, the boys decide that the man turned him into a zombie. They gang up on him and tie him up. The nurse at the boys camp (Dorothy Short) sets out to find the missing boys with Von Grosch (Dennis Moore), who has come to rid the town of the killer- or has he?'),
(922, N's922', N'TV_SHOW', N'SpongeBob SquarePants', NULL, 2009, N'TV-Y7', 6, N'SEASONS', N'6 Seasons', N'Who lives in a pineapple under the sea? SpongeBob SquarePants! Follow the adventures of this enthusiastic, optimistic sponge whose good intentions inevitably lead him and his friends into trouble.'),
(923, N's923', N'TV_SHOW', N'SpongeBob DocuPants', NULL, 2020, N'TV-PG', 1, N'SEASONS', N'1 Season', N'Imagine classic SpongeBob moments being told through the lens of documentary shows like E! True Hollywood Stories, Dateline, Behind the Music etc. Each episode takes an overly dramatic look into classic SpongeBob storylines.'),
(924, N's924', N'TV_SHOW', N'Spirited', NULL, 2010, N'16+', 2, N'SEASONS', N'2 Seasons', N'A dentist Suzy meets the ghost of an 80s English rock star Henry Mallet'),
(925, N's925', N'MOVIE', N'Spirit Rider', NULL, 1993, N'13+', 96, N'MINUTES', N'96 min', N'Jesse is a sullen, alieniated 16-year-old who has been shuttled from one foster home to another since he was a child. He is eventually repatriated to his family''s reservation and left in the care of his grandfather. Gradually Jesse adjusts to his new life, finding happiness, love and family secrets. Film Advisory Board - Award of Excellence'),
(926, N's926', N'MOVIE', N'Spiral', NULL, 2017, N'13+', 78, N'MINUTES', N'78 min', N'SPIRAL is the story of how a cycle of fear, hatred, and violence has taken hold. In portraying the resurgence of anti-Semitism in France and in the wider world, the film trains its gaze on individuals, witnesses on all sides of the conflicts that have fueled this escalation.'),
(927, N's927', N'TV_SHOW', N'Spies of Warsaw', NULL, 2013, N'TV-14', 1, N'SEASONS', N'1 Season', N'David Tennant and Janet Montgomery star in this adaptation of Alan Furst''s celebrated spy novel set in Poland, Paris and Berlin in the years leading up to the Second World War. At the French embassy in Warsaw, the new military attaché, Colonel Jean-Francois Mercier, is drawn into a world of abduction, betrayal and intrigue in the diplomatic salons and back alleys of the city.'),
(928, N's928', N'TV_SHOW', N'Speed Dreams - The Fastest Place on Earth', NULL, 2013, N'TV-14', 1, N'SEASONS', N'1 Season', N'Follow a group of daredevil amateur drivers as they prepare to enter the legendary land speed record-breaking event on the famous Bonneville Speedway. This documentary shows how, from garden sheds and garages across Britain to the spectacular salt flats of Utah, the seduction of speed is addictive. But what makes them risk life and limb for just one shot at glory?'),
(929, N's929', N'MOVIE', N'Special Forces', NULL, 2013, N'R', 109, N'MINUTES', N'109 min', N'A French journalist in Afghanistan is kidnapped by the Taliban.'),
(930, N's930', N'TV_SHOW', N'Soviet Storm: World War II in the East', NULL, 2011, N'13+', 2, N'SEASONS', N'2 Seasons', N'The project "Soviet Storm: WW2 in the East" depicts the most important events and battles of World War II. The task of the project is to illustrate the history of the war by means of computer graphics, motion-picture images and wartime images.'),
(931, N's931', N'MOVIE', N'Southward Ho!', NULL, 1939, N'13+', 53, N'MINUTES', N'53 min', N'In the first western to team Rogers with sidekick Gabby Hayes, Roy and Gabby play veterans of the Confederate Army who inherit half-ownership of a Texas ranch. Union Colonel Denbigh (Boteler), who owns the other half of the ranch and has a poor past relationship with Roy and Gabby, is appointed military governor of the district. A new police squadron just transferred to the district to help with "The Reconstruction" is discovered to be made up entirely of outlaws masquerading as policemen, who rob the surrounding ranches in disguise. The criminals murder the Colonel, and it is up to Roy and Gabby to restore peace and lawfullness back to the territory. Roy even finds the time to romance the Colonel''s daughter, Ellen (Hart), and sing a couple of songs.'),
(932, N's932', N'MOVIE', N'Soul to Keep', NULL, 2019, N'16+', 94, N'MINUTES', N'94 min', N'Beelzebub, an ancient demon hellbent on consuming and possessing souls, preys on Millennials at a rundown country house. With an agenda that spans thousands of years to bring Hell to Earth, this Prince of Hell has finally arrived.'),
(933, N's933', N'MOVIE', N'Soothing Waterfalls with Music', NULL, 2019, NULL, 60, N'MINUTES', N'60 min', N'Sharecare Windows presents the beauty of the great outdoors inside. Relax with beautiful waterfalls from around the world. This original collection showcases the inspirational beauty of nature accompanied by original music scores created exclusively for Sharecare Windows by Mary Kay Kayaltizer.'),
(934, N's934', N'MOVIE', N'Soothing Surf at Del Norte for Sleep black screen', NULL, 2018, N'ALL', 601, N'MINUTES', N'601 min', N'Black screen reduces the blue-spectrum light waves-known to inhibit REM sleep. Awaken rested and refreshed. Accompanied by the relaxing ocean surf and natural sounds filmed on location in the remote Centerville Beach near the California Redwoods. Great for children, pets and anyone with sleep issues. For best results adjust your monitor or TV to the night or darkest screen setting.'),
(935, N's935', N'MOVIE', N'Soothing Surf at Carmel Beach for Sleep', NULL, 2017, N'ALL', 480, N'MINUTES', N'480 min', N'8 hours for a full night''s sleep. Let the rolling surf of the Pacific lull you to a deep slumber. Recorded on location at Carmel by The Sea, this ultra-dark sleep video helps reduce the blue-spectrum light emitted by your tv screen. This helps enhance deep REM sleep. All Sleepwell programs are included in your Prime membership.'),
(936, N's936', N'MOVIE', N'Soothing Sights and Sounds for Kids', NULL, 2012, N'ALL', 60, N'MINUTES', N'60 min', N'A relaxing and engaging video for children of all ages. Families can relax to sights including the Chinese Ice Festival, desert windmills, lighthouses, butterflies and flowers, Venice gondolas, swimming with fish and other relaxing sights from around the world.'),
(937, N's937', N'MOVIE', N'Sonu Ke Titu Ki Sweety', NULL, 2018, N'13+', 138, N'MINUTES', N'138 min', N'Sonu and Titu are childhood friends. Titu has always been a naive lover, who falls in love easily and Sonu has always had to step in to save him. But Sweety is the perfect bride and Titu is head over heels in love with her. Sonu''s instinct to protect Titu at whatever cost, makes him feel that she''s too good to be true.'),
(938, N's938', N'TV_SHOW', N'Sons of the Soil : Jaipur Pink Panthers', NULL, 2020, N'13+', 1, N'SEASONS', N'1 Season', N'As Kabaddi’s popularity explodes across India with the rise of Pro Kabaddi League, Bollywood actor Abhishek Bachchan who owns the PKL team - Jaipur Pink Panthers is determined to go for the winning title after 6 seasons of not being able to make a mark in the league. He gambles on a talented but young and inexperienced group of players in his quest to win season 7 of Kabaddi''s biggest competition.'),
(939, N's939', N'TV_SHOW', N'Sonic X', NULL, 2005, N'TV-Y7', 3, N'SEASONS', N'3 Seasons', N'Sonic, his friends, and the evil Dr. Eggman are sucked into a warp! They find themselves in the human world where Sonic finds a new friend, a young boy named Chris. Sonic speeds through battles with Eggman, trying to retrieve all of the Chaos Emeralds so that everyone can go back home!'),
(940, N's940', N'MOVIE', N'Song One', NULL, 2015, N'PG-13', 88, N'MINUTES', N'88 min', N'Oscar winner Anne Hathaway stars as Franny in this romance set in Brooklyn''s indie music scene. After her brother is in an accident, Franny returns home only to fall in love with her brother''s musical idol.'),
(941, N's941', N'MOVIE', N'Song of the Cloud Forest', NULL, 1989, NULL, 24, N'MINUTES', N'24 min', N'Jim Henson''s "Song of the Cloud Forest" features a vibrant blend of music, puppetry and animation in a unique celebration of the rain forests.'),
(942, N's942', N'MOVIE', N'Song of Texas', NULL, 1943, N'13+', 53, N'MINUTES', N'53 min', N'Former rodeo star Roy Rogers decides to help his old friend, ex-rodeo champ Sam Bennett (Shannon), when he discovers that Sam bragged to his East Coast daughter Sue (Ryan) that he actually owns Roy''s prosperous and large ranch, wanting to impress her. When Sue arrives, she sees Roy working for an apparently wealthy and prosperous Sam. But trouble brews on the horizon when crooked rodeo owner Jim Calvert (MacLane) learns of the subterfuge, and decides to exploit it to his own gain.'),
(943, N's943', N'MOVIE', N'Song Of Texas', NULL, 1943, N'ALL', 53, N'MINUTES', N'53 min', N'Roy "loans" his ranch to a ranch-hand - a former rodeo champion, now a reformed alcoholic - to help him impress his daughter. However, Roy is stymied when she sells half to a foe. To get back his property, Roy must win a chuck-w'),
(944, N's944', N'MOVIE', N'Song Of Arizona', NULL, 1946, N'PG', 60, N'MINUTES', N'60 min', N'Gabby Whittaker (Hayes) runs an Arizona ranch for homeless and wayward boys that is in financial trouble. One of the boys, Chip Blaine (Cook), is the son of notorious bank robber King Blaine (Talbot). When Chip hears that his father has been killed, he decides to dig up the cache of stolen money his father gave him to hide, wanting to use it to help pay off Gabby''s mortgage. However, his father''s gang wants the money and rides in to take it. The Sons of the Pioneers assist Roy and Gabby to fight the outlaws. Chip learns that using stolen money is never a good thing to do.'),
(945, N's945', N'MOVIE', N'Son of the Navy', NULL, 1940, N'18+', 71, N'MINUTES', N'71 min', N'Steve Moore (Dunn) is trying to get back to his base at San Pedro when he meets orphan boy Tommy (Spellman) and his dog, who is looking for a mother and father to adopt him. Steve decides to pretend that Tommy is his son so that it will be easier to get a ride. However, Tommy likes the idea a little too much and decides Steve will be his permanent father. Steve then decides that Tommy is too troublesome, and tries to get rid of him several times, but eventually comes to care for Tommy, and comes to the decision to legally adopt the boy. Soon they meet a pretty lady (Parker), and both father and son do all they can to woo her and complete their little family.'),
(946, N's946', N'MOVIE', N'Son of Monte Cristo', NULL, 1940, N'13+', 96, N'MINUTES', N'96 min', N'Coming to the rescue of a 19th-century duchess, the son of Edmond Dantes succeeds in overthrowing a dictatorship in this swashbuckling adventure.'),
(947, N's947', N'MOVIE', N'Sometimes Always Never', NULL, 2020, N'PG-13', 91, N'MINUTES', N'91 min', N'After his son Michael left over a game of Scrabble, Alan and his family barely spoke to each other. But when a mysterious online player emerges who might be their prodigal son, Alan must find the right words before he loses everything.'),
(948, N's948', N'MOVIE', N'Something To Sing About', NULL, 1937, N'13+', 88, N'MINUTES', N'88 min', N'A New York bandleader journeys to Hollywood when he is offered a contract with a studio, but he is determined to do things his way and not theirs.'),
(949, N's949', N'MOVIE', N'Something from Nothing: The Art of Rap', NULL, 2012, N'16+', 111, N'MINUTES', N'111 min', N'A documentary on rap music and its rise to global prominence'),
(950, N's950', N'MOVIE', N'Someone Still Loves You Boris Yeltsin', NULL, 2008, N'NR', 42, N'MINUTES', N'42 min', N'Baeble goes bowling with Boris in Asbury Park, NJ.'),
(951, N's951', N'TV_SHOW', N'Some Assembly Required', NULL, 2016, N'ALL', 1, N'SEASONS', N'1 Season', N'A 14 year-old takes ownership of a toy company and hires a group of his friends to help him create amazing new toys.'),
(952, N's952', N'MOVIE', N'Soldier of Night', NULL, 1986, N'R', 90, N'MINUTES', N'90 min', N'Terror ends a romance for a beautiful woman when she discovers the true nature of her boyfriend''s nocturnal excursions. Rejected by the army, the boy carries out his own personal vendetta against a society that sees him unfit to serve.'),
(953, N's953', N'MOVIE', N'Solar Flare', NULL, 2020, N'13+', 101, N'MINUTES', N'101 min', N'12-year-old dreamer Vlad accidentally gets caught in a conflict between two alien forces. Together with an electric transformer box The Bobot, a brave girl and an eccentric scientist he has to save the world from a global catastrophe.'),
(954, N's954', N'MOVIE', N'Sofia', NULL, 1948, N'PG', 83, N'MINUTES', N'83 min', N'In this Cold-War thriller Steve Roark (Gene Raymond) helps nuclear scientists in their desperate attempt to escape the ruthless Russian Communist agents who are chasing after them. Roark is a former OSS man assigned to rescue two atomic scientists from Russia and spirit them away from the Iron Curtin. Steve is shocked to discover that one of the scientists is his former lover Linda Carlsen (Sigrid Gurie). In the meantime, sexy cabaret singer-turned-spy Magda Onescu (Patricia Morison) acts as a double agent for both the Allies and the Communists, hoping to be gain double profits by giving vital information to both sides.'),
(955, N's955', N'MOVIE', N'Social Animals', NULL, 2018, N'R', 83, N'MINUTES', N'83 min', N'This honest, uncompromising comedy chronicles the war stories and sexual misadventures of a tight circle of lovers and friends fighting to get their acts together, for better or worse.'),
(956, N's956', N'MOVIE', N'Soapdish', NULL, 1991, N'PG-13', 96, N'MINUTES', N'96 min', N'The cast and crew of The Sun Also Sets, America''s hottest soap opera have on-screen drama and off-screen craziness with enough dirty laundry to keep everyone in hot water in this unadulterated comedy.'),
(957, N's957', N'MOVIE', N'So Undercover', NULL, 2012, N'PG-13', 94, N'MINUTES', N'94 min', N'A tough, street-smart private eye is hired by the FBI to go undercover in a college sorority.'),
(958, N's958', N'TV_SHOW', N'Snowdonia 1890', NULL, 2010, N'13+', 1, N'SEASONS', N'1 Season', N'Two families travel back in time to live as 1890s smallholders on Mount Snowdonia. For a month, the Braddocks and the Joneses live in neighboring farm cottages and face a battle for survival against a backdrop of barren mountainous terrain.'),
(959, N's959', N'MOVIE', N'Snowden', NULL, 2007, N'NR', 36, N'MINUTES', N'36 min', N'The Atlanta-based quintet, Snowden, visits New York with a batch of Morrisey-influenced songs in tow.'),
(960, N's960', N'MOVIE', N'Snowcat - Truck Tunes for Kids', NULL, 2016, NULL, 4, N'MINUTES', N'4 min', N'Truck Tunes is a series of children''s videos with awesome original songs about awesome trucks, featuring actual footage of the trucks in action. Snowcat! "With his special skills, he goes grooming all the hills. He''s a Snowcat, oh! Working through the night, sculpting, shaping powder right. He''s a Snowcat, oh!"'),
(961, N's961', N'MOVIE', N'Snowbound for Christmas', NULL, 2019, NULL, 84, N'MINUTES', N'84 min', N'Rachel is excited about her new job as a marketing exec at a real estate development firm. Eager to impress Adrian, her boss, Rachel lands a spot on a big project. Before the presentation, a snowstorm traps her and Adrian at a resort where they realize there is more to their relationship than just business.'),
(962, N's962', N'MOVIE', N'Snow Day', NULL, 2000, N'PG', 89, N'MINUTES', N'89 min', N'An unexpected overnight snowfall has made roads impassable. And that means a no-school, no-rules snow day! For fifteen year- old Hal (Mark Webber), it''s a chance to win the heart of popular Claire (Emmanuelle Chriqui) - or totally embarrass himself.'),
(963, N's963', N'TV_SHOW', N'Snog Marry Avoid?', NULL, 2009, N'16+', 2, N'SEASONS', N'2 Seasons', N'Jenny Frost presents the show that strips down over-stylised participants to show what''s underneath the layers of make-up and unflattering clothes. The public are then invited to choose whether they''d snog, marry or avoid the new-look participant.'),
(964, N's964', N'TV_SHOW', N'Snobs', NULL, 2003, N'16+', 1, N'SEASONS', N'1 Season', N'Three unlikely friends - Abby, the daughter of a wealthy, middle class traditional family; Marian, a boy from a group of modern-day nomads knows as Ferals; and Marians almost human dog, Snobs. The series is set in the picture postcard community of Tranquil Waters on Sydneys northern beaches.'),
(965, N's965', N'TV_SHOW', N'SNG: Don''t Come Last', NULL, 2017, N'TV-NR', 1, N'SEASONS', N'1 Season', N'Karan hosts this episode and makes Varun, Aadar and Kautuk go through three rounds of whacked out games. Watch this episode to find out which of these idiots comes last and the shocking punishment that follows!'),
(966, N's966', N'TV_SHOW', N'Sneaky Pete', NULL, 2019, N'18+', 3, N'SEASONS', N'3 Seasons', N'Who is Marius Josipovic? Marius himself would like to know. He''s feeling a pull toward the Bernhardt family. But he''s not part of the family. He''s a con-man. The chance to become more like a normal human being is enticing. It also scares him to death. This season all the members of the Sneaky Pete family explore their identity. It’s a dangerous journey. They could lose themselves or their lives.'),
(967, N's967', N'MOVIE', N'Snapshots', NULL, 2018, NULL, 95, N'MINUTES', N'95 min', N'One weekend at the lake. Three women and three secrets. Rose''s past collides with her granddaughter''s hidden future and her daughter''s angry present. What happens that summer in 1960 when Louise and Zee enter the lives of Rose and Joe Muller? With a found roll of film the story begins.'),
(968, N's968', N'MOVIE', N'Snake Eater 3: His Law', NULL, 1992, N'18+', 92, N'MINUTES', N'92 min', N'Soldier Kelly is hired by a family to bring redemption to their daughter following her brutalization at the hands of a gang of biker thugs. With the police unable to do anything, Soldier works outside the law to bring justice to those who demand it.'),
(969, N's969', N'MOVIE', N'Smile Please', NULL, 2019, N'13+', 132, N'MINUTES', N'132 min', N'Nandini Joshi, once an extremely successful photographer, has fallen prey to dementia. Her already unstable relationship with her daughter Nupur, who stays with Nandini’s ex-husband Shishir, has deteriorated over the years. When Viraj, a young graphic designer arrives on the scene, he is determined to mend the situation and help Nandini rediscover a sense of meaning in her life.'),
(970, N's970', N'MOVIE', N'Smash Up: Story Of A Woman', NULL, 1947, N'PG-13', 104, N'MINUTES', N'104 min', N'A nightclub singer, beset by emotional problems, seeks refuge in alcohol which drives away her husband and child.'),
(971, N's971', N'MOVIE', N'Small Soldiers', NULL, 1998, N'PG-13', 110, N'MINUTES', N'110 min', N'When missile technology is used to enhance toy action figures, the toys soon begin to take their battle programming too seriously.'),
(972, N's972', N'TV_SHOW', N'Small Axe', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'Small Axe is a collection of five original films by Steve McQueen set from the late 1960s to the mid 1980s that tell personal stories from London''s West Indian community, whose lives have been shaped by their own force of will despite rampant racism and discrimination. New film every Friday from Nov 20-Dec18.'),
(973, N's973', N'TV_SHOW', N'Slopestyle TV', NULL, 2014, N'ALL', 2, N'SEASONS', N'2 Seasons', N'Slopestyle TV is the skiing and snowboarding mountain destination travel series featuring some of the world''s finest alpine riders and resorts. Every episode travel to a new mountain destination and push the limits of powder and terrain park riding while exploring the region''s history, local culture and exciting night life.'),
(974, N's974', N'MOVIE', N'Slipstream', NULL, 2005, N'18+', 87, N'MINUTES', N'87 min', N'Sci-fi drama. A scientist who has managed to create a time travelling device accidentally interrupts a bank robbery while experimenting with his invention. Now he must go back in time again to prevent the heist, and his own death.'),
(975, N's975', N'MOVIE', N'Sleepytime Gorilla Museum', NULL, 2011, N'NR', 55, N'MINUTES', N'55 min', N'Experimental rockers Sleepytime Gorilla Museum mix hard rock with performance art at NYC''s the Bowery Ballroom.'),
(976, N's976', N'MOVIE', N'Sleepwalker', NULL, 2017, N'18+', 88, N'MINUTES', N'88 min', N'Troubled by bouts of sleepwalking and nightmares, graduate student Sarah Foster goes to her university''s sleep research center for help. When she wakes up after her first night of being monitored, the world she lives in seems to have changed in subtle, Twilight-Zone-esque ways. With the help of sleep researcher Scott White, she tries to work her way back to the reality she started in.'),
(977, N's977', N'MOVIE', N'Slate, Wyn & Me', NULL, 1987, N'R', 90, N'MINUTES', N'90 min', N'Meandering drama of brothers Burke and Sacks, who rob a bank, kill a cop and kidnap Thornton, a witness to their crime.'),
(978, N's978', N'MOVIE', N'Slappy and the Stinkers', NULL, 1998, N'13+', 78, N'MINUTES', N'78 min', N'Five 2nd-grade kids who don''t follow strict rules by their school principal Brinway are dubbed "Stinkers" by him. On the class visit to an aquarium the Stinkers decide that a sea lion called Slappy doesn''t feel too good there, "free" him, and plant him into Brinway''s hot-tub.'),
(979, N's979', N'MOVIE', N'Sky Racket', NULL, 1937, N'13+', 62, N'MINUTES', N'62 min', N'Several mail planes crash twelve miles outside a small town, but the pilots and the mail sacks have disappeared. FBI agent Eric Lane (Bennett aka Herman Brix) is assigned to the case. He flies to the area with the plan to bail out, but shortly before he jumps, he discovers stowaway society debutante Marion Bronson (Barclay), who is escaping an arranged marriage to Count Barski (Renaldo). The plane motor suddenly dies and Lane is forced to grab Marion and jump out of the plane with their single parachute. When the pair safely lands, they are captured by a gang of criminals and taken to their hideout. The pair must use their wits and brawn to defeat the gang and stop their use of a stolen ray gun, which is used bring down planes carrying valuable cargo.'),
(980, N's980', N'MOVIE', N'Sky Dog', NULL, 2020, N'7+', 109, N'MINUTES', N'109 min', N'When a high school senior working on his pilot''s license rescues a stray dog named Oreo, the two quickly become best friends. But when he finds out his mom is an undercover CIA agent who''s been captured, he''ll need to team up with Oreo and a new friend to find his mother, thwart the plans of those holding her hostage, and uncover the double agents within the CIA itself.'),
(981, N's981', N'TV_SHOW', N'Skulls and Roses', NULL, 2019, N'16+', 1, N'SEASONS', N'1 Season', N'Raghu and Rajiv make their long awaited return in Skulls & Roses, a one-of-a-kind competition where the worlds of romance and adventure collide on Rose Island and Skull Island.  They put 8 boys and 8 girls through the ultimate schizophrenic journey of a lifetime.'),
(982, N's982', N'MOVIE', N'Skin Deep: The Battle Over Morgellons', NULL, 2020, N'16+', 90, N'MINUTES', N'90 min', N'A nurse journeys to discover the truth behind a disease so bizarre, patients who suffer from it are regularly written off as delusional by doctors and loved ones. But who is delusional, the patients who believe or the doctors who deny?'),
(983, N's983', N'MOVIE', N'Skills Like This', NULL, 2007, N'NR', 87, N'MINUTES', N'87 min', N'Winner of the Audience Award at SXSW, this offbeat romantic comedy follows failed writer Max as he discovers something he thinks he''s really good at: stealing.'),
(984, N's984', N'MOVIE', N'Sketchy Behaviour', NULL, 2019, N'PG-13', 64, N'MINUTES', N'64 min', N'Sketchy Behaviour is an absurd sketch comedy show filmed live in Mumbai. Described as hilarious, complex, stupid, irritating(and ‘sardonic’ by one lady in Goa) the show is familiar, bizarre and hysterically funny. Featuring six very silly live sketches, stitched together by a much sillier story and bookended by an extremely silly opening and closing, Sketchy Behaviour is truly a work of something.'),
(985, N's985', N'TV_SHOW', N'Six Dreams', NULL, 2018, N'16+', 1, N'SEASONS', N'1 Season', N'Six Dreams is an exclusive and unprecedented insight into the Spanish first division of football. Follow six people during league season 2017-18: Three players, one coach, one sports director and a club president. Their stories offer an inside look at the daily difficulties, victories and challenges of professional football at the highest level.'),
(986, N's986', N'MOVIE', N'Sitting on the Moon', NULL, 1936, N'13+', 53, N'MINUTES', N'53 min', N'Songwriter Danny (Pryor) believes that the only way to jump-start fading movie star Polly''s (Bradley) career is to end his partnership with lyricist Mike (Newell). Polly''s friend Mattie (Kelton) manages to comfort Mike in teh interim. Then, Mike concocts a plan to separate Danny from Polly: he sends blonde seductress Blossom (Compton) to pretend to be Mike''s girlfriend. But all ill feeligns and misunderstandings are resolved by the climactic musical finale.'),
(987, N's987', N'MOVIE', N'Sitting Bull: A Stone in My Heart', NULL, 2008, N'7+', 83, N'MINUTES', N'83 min', N'Sitting Bull''s own words, over six-hundred photographs and a compelling original music score bring to life this great American Indian''s struggle to save his people''s way of life against an ever-expanding westward movement of white settlers. This is powerful cinematic journey into the life and spirit of a legendary figure. No other film captures him with such depth of character and personality.'),
(988, N's988', N'MOVIE', N'Sita', NULL, 2019, N'13+', 157, N'MINUTES', N'157 min', N'Sita is a materialistic woman who only cares about materialistic gains and nothing else. MLA Basava Raju lusts for her and wants her to give him what she promised him for helping her. The villain of their tale is Ram, a man who’s way too innocent for his own good. How does Ram help Sita out of the fix she’s in forms the crux of the story.'),
(989, N's989', N'TV_SHOW', N'Sister, Sister', NULL, 1999, N'TV-PG', 6, N'SEASONS', N'6 Seasons', N'Tia and Tamera are twins who were separated at birth, with each being adopted by a different parent. One day, the teens have a chance encounter while shopping at a clothing store in the mall. After the families meet, Tamera''s adoptive father reluctantly allows Tia and her mother to move into his home so the girls can be together.'),
(990, N's990', N'MOVIE', N'Sir Chris Hoy - From Velodrome to Le Mans', NULL, 2016, NULL, 52, N'MINUTES', N'52 min', N'Retired track cyclist Sir Chris Hoy swaps two wheels for four to pursue his boyhood dream of competing in the world''s toughest endurance motor race, the Le Mans 24 Hours.'),
(991, N's991', N'MOVIE', N'Sing, Dance and Learn with Little Baby Bum', NULL, 2019, N'ALL', 30, N'MINUTES', N'30 min', N'Enjoy this 30-minute compilation by Little Baby Bum. Sing along to some of the most popular nursery rhymes and kids songs songs to date! This compilation includes titles such as ''Tweedledum and Tweedledee'', ''Billy Boy'', and many more!'),
(992, N's992', N'TV_SHOW', N'Sing-Along-Songs For Kids', NULL, 2013, N'ALL', 1, N'SEASONS', N'1 Season', N'This colorful and engaging children''s program features songs, music, animations and sing-along to entertain and educate your kids. SING-ALONG-SONGS FOR KIDS includes timeless English nursery rhymes as well as modern-day classics and educational sing-alongs.'),
(993, N's993', N'MOVIE', N'Sing with Gecko', NULL, 2019, N'ALL', 33, N'MINUTES', N'33 min', N'Sing some of the most popular and classic nursery rhyme songs with Gecko and friends! Songs like Wheels on the bus, If you''re happy and you know it, and more!'),
(994, N's994', N'MOVIE', N'Sing Sing Nights', NULL, 1934, N'18+', 60, N'MINUTES', N'60 min', N'A mystery emerges when a respected international war correspondant is found murdered with three bullet wounds. Upon investigation, it is discovered that each bullet came from a different gun. Three different men are arrested of the murder, and each of them confess to the crime. All three are convicted of the murder and are sentenced to death. However, only one man can truly be the real killer. A criminologist desides to use a new kind of lie detector in his investigation into the identify of the real murderer, but he must act quickly before all three men are put to death.'),
(995, N's995', N'MOVIE', N'Sing and Learn with Gecko''s Garage', NULL, 2019, N'ALL', 59, N'MINUTES', N'59 min', N'Come and join Gecko at his Garage as he sings some of the most popular and classic nursery rhyme songs that we all love like Wheels on the Bus and more!'),
(996, N's996', N'MOVIE', N'Sing and Dance with Little Baby Bum!', NULL, 2019, N'ALL', 45, N'MINUTES', N'45 min', N'More wonderful videos starting with famous nursery rhymes such as ''Peekaboo Song'' and ''1, 2 What Shall We Do?'' from the world''s number one educational channel, Little Baby Bum!'),
(997, N's997', N'MOVIE', N'Sing and Dance with KiiYii', NULL, 2019, N'ALL', 47, N'MINUTES', N'47 min', N'In this compilation, your children will love to sing and dance to some of the most popular nursery rhymes and kids songs with KiiYii! Brought to you by the same creators as Little Baby Bum, this compilation contains some classic songs such as ''Rain Rain Go Away'', ''Wheels On The Bus'', and many more!'),
(998, N's998', N'MOVIE', N'Sing Along with Little Baby Bum', NULL, 2019, N'ALL', 35, N'MINUTES', N'35 min', N'Sing along to this 30-minute long compilation with some of LittleBabyBum''s most classic, well-loved and educational nursery rhymes!'),
(999, N's999', N'MOVIE', N'Sinful Davey', NULL, 1969, N'13+', 95, N'MINUTES', N'95 min', N'In 1821 a young Scotsman decides to be a criminal like his father, but falls in love first.'),
(1000, N's1000', N'MOVIE', N'Sinbad: Make Me Wanna Holla', NULL, 2014, N'16+', 90, N'MINUTES', N'90 min', N'Watch the all-out stand-up special featuring a riotous original performance by the king of comedy, Sinbad, recorded live in Detroit in his home state of Michigan. It covers everything, from the life advice his parents gave him, to why he is tired of people with no talent having clothing lines. Don''t miss the chance to experience the "hit''em in the face" style from the king of comedy himself.');

Copyright: TV TOKYO'),
(1007, N's1007', N'TV_SHOW', N'Silk', NULL, 2014, N'TV-14', 3, N'SEASONS', N'3 Seasons', N'Defense barrister Martha Costello is now a QC and busier than ever, while Clive Reader, also a QC, is specializing in prosecution. The criminal bar is a small world and they are pitted against each other increasingly often. Harriet wants to modernize Shoe Lane, but the changes are resented by Billy. Martha, Clive and Caroline are up for head of chambers and it means radical changes at Shoe Lane.'),
(1008, N's1008', N'TV_SHOW', N'Silent Witness', NULL, 2018, N'TV-MA', 21, N'SEASONS', N'21 Seasons', N'The award-winning crime drama returns with five fascinating forensic adventures. Join pathologist Dr Nikki Alexander and her dedicated team as they help the police solve a slew of mystifying murders.'),
(1009, N's1009', N'MOVIE', N'Silent Wings - The American Glider Pilots of WWII', NULL, 2007, N'7+', 115, N'MINUTES', N'115 min', N'From the early race to build gliders to the D-Day invasion at Normandy and Nazi Germany''s final surrender, this acclaimed feature documentary, narrated by Hal Holbrook, reveals the critical role gliders played in World War II offensives. Through rare archival footage and photographs, the film places the audience right at the center of the action in the dangerous world of American glider pilot.'),
(1010, N's1010', N'MOVIE', N'Silence Patton', NULL, 2018, N'13+', 85, N'MINUTES', N'85 min', N'Silence Patton asks the question: Why was General Patton silenced during his service in World War II? Was he a threat to Eisenhower, Montgomery, Churchill, and Bradley? Or was Patton not only dismissed by his peers, but the victim of an assassin''s bullet? Was his personal silence necessary?'),
(1011, N's1011', N'MOVIE', N'Silence (Tamil) (4K UHD)', NULL, 2020, N'16+', 126, N'MINUTES', N'126 min', N'A murder-mystery thriller. A world-famous cello player is murdered and crucified in a Seattle Villa that has a reputation for being haunted. His friends and family try to figure out if he was really killed by a supernatural being or if he was assassinated by someone he knows. His dumb and deaf wife and a police detective are pinned against each other as they discover the victim''s dark past.'),
(1012, N's1012', N'MOVIE', N'Silence (Malayalam) (4K UHD)', NULL, 2020, N'16+', 126, N'MINUTES', N'126 min', N'A murder-mystery thriller. A world-famous cello player is murdered and crucified in a Seattle Villa that has a reputation for being haunted. His friends and family try to figure out if he was really killed by a supernatural being or if he was assassinated by someone he knows. His dumb and deaf wife and a police detective are pinned against each other as they discover the victim''s dark past.'),
(1013, N's1013', N'TV_SHOW', N'Sigmund and the Sea Monsters', NULL, 2017, N'7+', 1, N'SEASONS', N'1 Season', N'Brothers Johnny and Scotty find Sigmund, a sea monster, on the beach and bring him home to their clubhouse. They become fast friends, but when a monster hunter, Capt. Barnabas (David Arquette), finds out, the kids have to scramble to keep Sigmund hidden. Worse still, Sigmund''s brothers Blurp and Slurp don''t like humans. Against all odds, can they still have an endless summer of fun?'),
(1014, N's1014', N'TV_SHOW', N'Sid the Science Kid', NULL, 2008, N'ALL', 1, N'SEASONS', N'1 Season', N'Season 1 Volume 1. Sid the Science Kid is an award-winning educational animated television series that uses comedy and music to promote exploration, discovery and science readiness among pre-schoolers.'),
(1015, N's1015', N'MOVIE', N'Sick Song & More Nursery Rhymes For Kids - KiiYii', NULL, 2020, N'ALL', 29, N'MINUTES', N'29 min', N'A new collection of colorful and wonderfully engaging nursery rhymes and children''s songs that will thrill your child while educating them in their numbers, ABCs and general learning! From the creators of LittleBabyBum, KiiYii allows the child''s imagination to go further!'),
(1016, N's1016', N'MOVIE', N'Siberia (2018)', NULL, 2018, N'R', 105, N'MINUTES', N'105 min', N'When a business deal in Russia goes south, a U.S. diamond merchant (Keanu Reeves) and his lover are caught in a lethal crossfire between the buyer and local federal agents.'),
(1017, N's1017', N'MOVIE', N'Shoutoutoutout', NULL, 2011, N'NR', 35, N'MINUTES', N'35 min', N'Drums, vocoder, samplers, synths, bass, guitar – the key elements of Shout Out Out Out Out''s dance music.'),
(1018, N's1018', N'MOVIE', N'Shottas', NULL, 2002, N'R', 99, N'MINUTES', N'99 min', N'In the tradition of Scarface and The Harder They Come, Shottas is an unapologetic raw urban drama about two young men, Wayne and Biggs, who grow up together on the tough and dangerous streets of Kingston, Jamaica. Eventually moving to the U.S., they begin a ruthless climb to the top of a criminal enterprise in a Miami as they aggressively take control of the Jamaican underworld.'),
(1019, N's1019', N'MOVIE', N'Shor Se Shuruaat', NULL, 2016, N'18+', 123, N'MINUTES', N'123 min', N'Shor se Shuruaat is an omnibus feature of mentored short films, around the central theme of ''Shor''- noise. 7 films, from 7 different directors conveying 7 different stories on the same theme. The short films have been mentored by stalwarts like Mira Nair, Shyam Benegal, Imtiaz Ali, Zoya Akhtar, Nagesh Kukunoor, Sriram Raghavan and Homi Adajania'),
(1020, N's1020', N'TV_SHOW', N'Shock and Awe: The Story of Electricity', NULL, 2011, N'ALL', 1, N'SEASONS', N'1 Season', N'Until recently, electricity was seen as a magical power. It could slay the living, revive the dead, and even bend the laws of nature. It is now the lifeblood of the modern world, fueling our lives and underpinning every aspect of technological advancement. Without it, we would be lost. Professor Jim Al-Khalili tells the electrifying story of our quest to master nature''s most mysterious force.'),
(1021, N's1021', N'TV_SHOW', N'SHK HeroForce', NULL, 2018, N'TV-PG', 1, N'SEASONS', N'1 Season', N'While Noah, Hope, and Eden are moving out of their old house, they discover a hidden virtual reality gaming console in the attic that acts as a portal between the game HeroForce and Real Life. The kids must find and protect the power rings from the hands of the evil bosses that have crossed into Real Life in search of the rings.'),
(1022, N's1022', N'MOVIE', N'Shivaay', NULL, 2015, N'13+', 154, N'MINUTES', N'154 min', N'Shivaay, the father of a young girl who went missing from the streets of Bulgaria, defies all odds and exposes the child trafficking mafia. But will his efforts help him find his own daughter who is being forced into the horrific trade? How will a mountaineer from the foothills of the Himalayas fight against the powerful Russian mafia, in the quest to rescue his beloved daughter?'),
(1023, N's1023', N'TV_SHOW', N'Shipping Wars', NULL, 2015, N'TV-14', 4, N'SEASONS', N'4 Seasons', N'With "Shipping Wars," dive into the cutthroat world of heavy-duty movers as they battle for the chance to transport the unshippable the items that traditional carriers won''t touch.'),
(1024, N's1024', N'MOVIE', N'Shinrin-Yoku (forest bathing)', NULL, 2019, NULL, 60, N'MINUTES', N'60 min', N'Relaxing visits to a forest for health benefits originated in Japan where it is called Shinrin-Yoku. Proven to benefit physical and mental health, Shinrin-Yoku helps to lower heart rate and blood pressure, and reduce stress hormone production to improve overall feelings of wellbeing. "Shinrin-Yoku" has been screened at over 82 International Film Festivals and won19 prestigious awards.'),
(1025, N's1025', N'TV_SHOW', N'Shin chan Spin-off vol.1  Aliens vs. Shinnosuke', NULL, 2016, N'TV-NR', 1, N'SEASONS', N'1 Season', N'On the 25th anniversary of the start of the animated series, Shin chan will be presented in a new style! "What if Shinnosuke encountered aliens in a drifting spaceship?"'),
(1026, N's1026', N'MOVIE', N'Sherlock Holmes: The Hound of the Baskervilles', NULL, 1983, N'13+', 100, N'MINUTES', N'100 min', N'Sherlock Holmes comes to the aid of his friend Henry Baskerville, who is under a family curse and menaced by a demonic dog that prowls the bogs near his estate and murders people.'),
(1027, N's1027', N'MOVIE', N'Sherlock Holmes & The Woman In Green', NULL, 1945, N'13+', 69, N'MINUTES', N'69 min', N'Based on Conan Doyle''s The Adventure of the Empty House, this "Sherlock Holmes" entry finds Holmes and Dr. Watson trying to solve the case of the "Finger Murders". Several beautiful women have been found murdered, all with their right forefingers severed from their hands.'),
(1028, N's1028', N'MOVIE', N'Sherlock Holmes & The Secret Weapon', NULL, 1943, N'13+', 71, N'MINUTES', N'71 min', N'Imaginative story pitting Holmes against Moriarty. Starting in Switzerland, Sherlock Holmes rescues the inventor of a bomb-sight which the allies want to keep from the Nazis. Back in London it sems that the inventor is not all that he seemed. Holmes wears various disguises as he thwarts Moriarty''s efforts to deliver vital information to Gestapo.'),
(1029, N's1029', N'TV_SHOW', N'Shepherd', NULL, 2021, N'13+', 1, N'SEASONS', N'1 Season', N'Veteran actor Lance Nichols (Into the Badlands, House of Cards) heads this New Orleans-based cast as Father Joseph, a Catholic priest with a violent past who wages war with a dangerous drug lord after an attack at his church on Christmas Eve. Kelvin Harrison Jr. (Luce, Waves) co-stars as Will, a former altar boy turned drug dealer who gets caught up in Father Joseph''s pursuit for justice.'),
(1030, N's1030', N'MOVIE', N'She''s Not Our Sister', NULL, 2011, N'13+', 88, N'MINUTES', N'88 min', N'What happens when three sisters find out they stand to inherit a multimillion-dollar fortune, and in the process discover a half-sister their estranged father never told them about?'),
(1031, N's1031', N'MOVIE', N'Shawn Pelofsky: Stretch It Out', NULL, 2018, N'18+', 61, N'MINUTES', N'61 min', N'Comedienne, Shawn Pelofsky, stirs things up with her tales of growing up Jewish in Oklahoma, traveling to war zones and sailing on gay male cruises.'),
(1032, N's1032', N'TV_SHOW', N'Shaun the Sheep - The Farmer''s Llamas', NULL, 2015, N'ALL', 1, N'SEASONS', N'1 Season', N'When the Farmer and Bitzer go to a Country Fair, Shaun steals away with them intent on causing mischief. Shaun spies an auction where he sees three exotic and very crafty Llamas going under the hammer. Instantly besotted by their fantastic pranks Shaun cleverly gets the unwitting Farmer to Buy them.'),
(1033, N's1033', N'TV_SHOW', N'Shaun the Sheep', NULL, 2012, N'TV-G', 6, N'SEASONS', N'6 Seasons', N'It''s sport''s day with Shaun the Sheep!'),
(1034, N's1034', N'MOVIE', N'Sharknado 5: Global Swarming', NULL, 2017, N'13+', 86, N'MINUTES', N'86 min', N'With much of North America lying in ruins, the rest of the world braces for the inevitable: a global sharknado. From London to Asia, South Africa to Mexico, Fin and his family must put a stop to the sharknados once and for all.'),
(1035, N's1035', N'MOVIE', N'Sharknado 4: The 4th Awakens', NULL, 2016, N'13+', 85, N'MINUTES', N'85 min', N'Five years after the wave of sharknados that wracked the east coast, our heroes are living a quiet life in the middle of the country – as far away from sharks as possible. But when a freak sand sharknado hits Vegas, Fin is thrown back into action, fighting sharknados on a cross-country race to save his family and the world – as all mankind should know by now, there is no escaping...'),
(1036, N's1036', N'MOVIE', N'Shark Story: Evolution of a Master Predator', NULL, 2013, N'7+', 54, N'MINUTES', N'54 min', N'This is the story of the evolution of one of the most successful animal species ever to have lived. What capabilities turned the shark into one of the ocean''s dominant predators, allowed them to survive mass extinctions and to thrive for over 300 million years. Despite its historic success, the highly evolved shark is now faced with extinction due to overfishing, climate change and declining prey.'),
(1037, N's1037', N'MOVIE', N'Shapes Song & More Learning Songs For Kids - KiiYii', NULL, 2020, N'ALL', 33, N'MINUTES', N'33 min', N'A new collection of colorful and wonderfully engaging nursery rhymes and children''s songs that will thrill your child while educating them in their numbers, ABCs and general learning! From the creators of LittleBabyBum, KiiYii allows the child''s imagination to go further!'),
(1038, N's1038', N'MOVIE', N'Shao Lin Temple', NULL, 1982, N'13+', 100, N'MINUTES', N'100 min', N'Nominated and won: Hong Kong Film Award. Best Action Choreography. A young man, hounded by a psychopathic general, learns martial arts at the Shaolin temple to avenge his father''s death. To achieve this he forgoes a budding romance with his kung fu master''s daughter, a shepherdess.'),
(1039, N's1039', N'MOVIE', N'Shane Mauss: Mating Season', NULL, 2013, N'18+', 65, N'MINUTES', N'65 min', N'Shane Mauss, an honorary evolutionary psychologist, brings countless years of watching Animal Planet to aid in discussions of Snoop Dog, crouton factories, and other important things.'),
(1040, N's1040', N'MOVIE', N'Shakuntala Devi', NULL, 2020, N'13+', 127, N'MINUTES', N'127 min', N'The extraordinary story of Shakuntala Devi, the world-renowned mathematician who lived her life on her own terms. While the film pays tribute to her genius as a mathematician, it also humanizes her as a woman and mother, in trying to capture her indomitable spirit. Told through the lens of her relationship with her daughter Anu, the film highlights their very different struggles and aspirations.'),
(1041, N's1041', N'TV_SHOW', N'Shakespeare Uncovered', NULL, 2018, N'TV-14', 1, N'SEASONS', N'1 Season', N'Includes six films: Much Ado About Nothing (Helen Hunt); The Merchant of Venice (F. Murray Abraham); Measure for Measure (Romola Garai); Julius Caesar (Brian Cox); The Winter''s Tale (Simon Russell Beale); Richard III (Antony Sher).'),
(1042, N's1042', N'TV_SHOW', N'Shaitaan Haveli', NULL, 2018, N'TV-NR', 1, N'SEASONS', N'1 Season', N'B-Grade filmmaker Hariman shows up to shoot his horror film at an old haveli. Freak occurrences make the crew realise that they''re not just shooting a horror film but are soon going to be living one.'),
(1043, N's1043', N'MOVIE', N'Shadow Puppets', NULL, 2007, N'16+', 103, N'MINUTES', N'103 min', N'Eight strangers with no memories find themselves trapped in an abandoned facility. As they desperately try to find answers and escape, their own Shadows attempt to consume them from the darkness.'),
(1044, N's1044', N'TV_SHOW', N'Shadow Force', NULL, 2008, N'TV-PG', 1, N'SEASONS', N'1 Season', N'Shadow Force offers an unparalleled look inside the operations of military specialists as they take on missions around the world.'),
(1045, N's1045', N'MOVIE', N'Shadow Company', NULL, 2007, N'13+', 44, N'MINUTES', N'44 min', N'Twenty thousand private soldiers operate in Iraq. Who are these people? What do they do and why do they do it? This documentary is a groundbreaking investigation into the secretive world of modern mercenaries. It follows one British contractor on his tour of duty, contrasting his experiences in Iraq with previous operations. This is the definitive film on the changing face of modern war.'),
(1046, N's1046', N'MOVIE', N'Shadaa', NULL, 2019, N'ALL', 128, N'MINUTES', N'128 min', N'Amidst pressures from his parents to hurry up and wed, a young man seeks his perfect match. After many failed attempts with matchmakers, his parents are delighted when their son finally meets the woman of his dreams but things do not go as planned.'),
(1047, N's1047', N'MOVIE', N'Shaadi Mubarak', NULL, 2021, N'ALL', 133, N'MINUTES', N'133 min', N'Madhav, an introverted software employee who gets compelled to meet 3 brides of alliances arranged by a marriage bureau run by Jayamma. Bhanumati, daughter of Jayamma, a happy, go-lucky girl had to accompany Madhav in meeting his set alliances. In the journey, they find love in each other, yet, they don''t express it. The story takes new turns with each alliance they meet.'),
(1048, N's1048', N'MOVIE', N'Sex Ed', NULL, 2014, N'18+', 92, N'MINUTES', N'92 min', N'First time teacher Eddie Cole turns his detention class into Sex Ed., but he might not be the best teacher since his students seem to have more experience than him.'),
(1049, N's1049', N'MOVIE', N'Seventeen (Siebzhen)', NULL, 2019, N'13+', 106, N'MINUTES', N'106 min', N'Somewhere in Austria, seventeen-year-old boarding school pupil Paula, is secretly in love with her friend Charlotte. But Charlotte''s with Michael. Lovelorn, Paula decides to get involved with schoolmate Tim, whose feelings for her are genuine. And then there''s Lilli, who is just dying for someone to fancy her. Paula must decide if she wants to follow her own feelings or yield to other people''s.'),
(1050, N's1050', N'TV_SHOW', N'Seven Senses of the Re’Union', NULL, 2018, N'TV-NR', 1, N'SEASONS', N'1 Season', N'Asahi’s life in reality ended simultaneously, when she died playing “Union”, a world-renowned online RPG. The members of “Subaru” went separate ways when "Union" shut down due to Asahi''s death. Six years later, Haruto logs onto a renewed version of "Re''Union" and reunites with Asahi who had died. Is she an electronic ghost? The "promise" the childhood friends made will unfold within the game.'),
(1051, N's1051', N'TV_SHOW', N'Series_Project_UN_Test_UHD', NULL, 2020, N'TV-G', 1, N'SEASONS', N'1 Season', N'Season1_Project_UN_Test_UHD short description'),
(1052, N's1052', N'TV_SHOW', N'Serial Swindlers', NULL, 2018, N'7+', 1, N'SEASONS', N'1 Season', N'Exposing the world''s most conniving, creative, and criminally adept con men, Serial Swindlers goes inside their minds. While their crimes and exploits are a ready-made Hollywood script, their escapades have left a trail of heartache, poverty and destruction. Ordinary criminal minds they are not.'),
(1053, N's1053', N'TV_SHOW', N'Serbia: Old and New', NULL, 2019, N'16+', 1, N'SEASONS', N'1 Season', N'Join Laura Alexandra as she travels Serbia for the first time in this 6 part series. Serbia has connected West with East for centuries - a land in which civilisations, cultures, faiths, climates and landscapes meet and mingle. Experience beautiful mountains, national parks, stunning medieval churches and a whole host of amazing things on offer in Serbia, from the very old to the very new.'),
(1054, N's1054', N'MOVIE', N'Separate Ways', NULL, 1981, N'R', 93, N'MINUTES', N'93 min', N'Karen Black stars as Val, a neglected wife who must leave her husband and find herself before attempting to reconstruct her marriage. With new-found dignity and a fresh perspective, Val and her husband vow to try again.'),
(1055, N's1055', N'TV_SHOW', N'SENTOSHA: Battle Wheels', NULL, 2018, N'13+', 1, N'SEASONS', N'1 Season', N'Renowned entertainers and car lovers grasp the wheel and compete with their battle cars in a variety of never before seen challenges! They face off in life-threatening duels designed to test their speed, courage, and above all, their grit! Put the pedal to the metal! Burn! Destroy! Crash into! This is a new show of the “Dangertainment variety (danger + entertainment)”. (C) 2017 YD Creation (C)'),
(1056, N's1056', N'MOVIE', N'Sensitivity Training', NULL, 2018, N'13+', 86, N'MINUTES', N'86 min', N'A misanthropic scientist is forced into sensitivity training at work and forms an unlikely friendship with the bubbly woman assigned to be her coach.'),
(1057, N's1057', N'MOVIE', N'Selfie Dad', NULL, 2020, N'PG', 97, N'MINUTES', N'97 min', N'Parenting is no joke! In this a light-hearted family film, one dad shakes off a mid-life crisis and reconnects with his family . . . with his Bible in one hand and his phone in the other. Featuring Michael Jr. and Chonda Pierce.'),
(1058, N's1058', N'TV_SHOW', N'Selena''s Secret', NULL, 2018, N'TV-NR', 1, N'SEASONS', N'1 Season', N'The series begins with the death of the singer, then goes back in time to explain the relationship that existed between her and her murderer, showing only what was disclosed by the media.'),
(1059, N's1059', N'MOVIE', N'Selah and the Spades', NULL, 2020, N'R', 98, N'MINUTES', N'98 min', N'Five factions run the underground life of the prestigious Haldwell boarding school. At the head of the most powerful faction – THE SPADES – sits Selah Summers. Both charming and callous, Selah walks the fine line between being feared and loved, often cutting loose whomever she deems a threat to her power.'),
(1060, N's1060', N'MOVIE', N'Seeing, Searching, Being - William Segal', NULL, 2010, NULL, 74, N'MINUTES', N'74 min', N'William Segal, was a philosopher, publisher, writer and painter who searched relentlessly and compassionately for meaning in the 20th century. Segal helped bring Eastern and Western spiritual traditions together, always stressing what connected humanity rather than what differentiated it.'),
(1061, N's1061', N'TV_SHOW', N'Seeing Canada', NULL, 2019, N'13+', 2, N'SEASONS', N'2 Seasons', N'Brandy Yanchyk returns with the second season of her travel documentary series, Seeing Canada. Through Brandy''s eyes, enjoy Canada''s iconic nature, thrilling adventures, and unique, and varied culture. Visit vibrant cities, savour culinary delights, enjoy world-class attractions and meet unique characters and Canada''s natural wonders in this excellent and exciting six-part series.'),
(1062, N's1062', N'MOVIE', N'Seed of Innocence', NULL, 1980, N'R', 92, N'MINUTES', N'92 min', N'Poignant love story of two teenagers who have a baby and decide to keep it in spite of their parents'' objections. They flee their gossipy small town and try to make it in New York.'),
(1063, N's1063', N'MOVIE', N'Section 375', NULL, 2019, N'18+', 123, N'MINUTES', N'123 min', N'A celebrated Bollywood director Rohan Khurana stands accused by a female member of his crew, Anjali Dangle of having raped her at his residence.'),
(1064, N's1064', N'TV_SHOW', N'Secrets Of The Universe', NULL, 2015, N'ALL', 1, N'SEASONS', N'1 Season', N'This visually dynamic series follows a trail of energy into the power centers of the universe: black holes, exploding stars, active galaxies. Based on the findings of current science, including state of the art supercomputer simulations, the series dives into the heart of a supermassive black hole, flies down onto toxic alien planets and rides on the roiling surface of stars about to go supernova.'),
(1065, N's1065', N'TV_SHOW', N'Secrets of the Dead: The Nero Files', NULL, 2019, N'TV-PG', 1, N'SEASONS', N'1 Season', N'The Roman emperor Nero is considered one of history''s greatest criminals - a cruel, insane, and brutal ruler. Secrets of the Dead: The Nero Files investigates Nero''s reign with the help of criminal psychologist Thomas Müller.'),
(1066, N's1066', N'MOVIE', N'Secrets of the Dead: The Lost Gardens of Babylon', NULL, 2014, NULL, 55, N'MINUTES', N'55 min', N'A world wonder so elusive; it must be mythical...The Lost Gardens of Babylon follows Dr. Stephanie Dalley as she hunts for the gardens using ancient texts and spy satellite images to uncover evidence to support her theory that the gardens were built 100 years before commonly believed.'),
(1067, N's1067', N'TV_SHOW', N'Secrets of the Castle', NULL, 2014, N'13+', 1, N'SEASONS', N'1 Season', N'Historian Ruth Goodman and archaeologists Peter Ginn and Tom Pinfold go back in time a few hundred years - figuratively, at least - as they learn how to build a medieval castle using only tools, techniques and materials that were available in the 13th century. It is an extensive project, which is part of a large archaeological experiment expected to take 25 years to complete'),
(1068, N's1068', N'MOVIE', N'Secret Valley', NULL, 1937, N'ALL', 57, N'MINUTES', N'57 min', N'Nevada rancher Lee Rogers (Arlen) decides to allow Jean Carlo (Grey) to hide out on his ranch. She wants a divorce from gangster husband Collins (Wilis), who has secretly followed her. Jean accidentally causes a stampede of Lee''s cattle that almost causes him to lose the ranch. Jean uses some of her fortune to pay off Lee''s debt, and convinces Lee''s friend Russel Parker (Mulhall) to lie and say that he had obtained a loan from the bank. Collins and his henchmen capture Jean, and threatens to harm Lee if she does not come with them, to which she agrees. But Lee won''t give up Jean without a fight, and together with a group of Federal lawmen who want to arrest Collins, rides off to rescue Jean and bring Collins to justice.'),
(1069, N's1069', N'TV_SHOW', N'Secret State', NULL, 2012, N'TV-14', 1, N'SEASONS', N'1 Season', N'This is a proper political thriller, where democracy and its relationship with industry is laid bare. Starring Gabriel Byrne Charles Dance and Gina McKee.'),
(1070, N's1070', N'TV_SHOW', N'Secret Life of the Hospital Bed', NULL, 2017, N'16+', 1, N'SEASONS', N'1 Season', N'This documentary series takes an unprecedented look inside Britain''s emergency medical system, using fixed-rig cameras to tell the stories of patients during their stays in A&E, Maternity, Day Surgery, and Paediatrics at hospitals across the country. While the circumstances, ailment, treatment, and length of the stay differ with each individual patient, the one constant is the bed.'),
(1071, N's1071', N'MOVIE', N'Secret Diary of the Holocaust', NULL, 2009, N'16+', 50, N'MINUTES', N'50 min', N'Documentary telling the tale of a 14-year-old Polish girl, Rutka Laskier, who was murdered at Auschwitz in 1943, whose diary was found under the floorboards of her home in 2005.'),
(1072, N's1072', N'TV_SHOW', N'Secret Diary of a Call Girl', NULL, 2011, N'18+', 3, N'SEASONS', N'3 Seasons', N'The real-life anonymous blog and book of a high-class London call girl known to the world only as "Belle de Jour" becomes this original series starring Billie Piper as Hannah, an ambitious young woman leading an exciting but dangerous double life as an expensive escort named "Belle" that not even her best friend suspects. Cherie Lunghi and Iddo Goldberg costar in this hit British series.'),
(1073, N's1073', N'MOVIE', N'Secondhand Hearts', NULL, 2020, NULL, 95, N'MINUTES', N'95 min', N'Ben, a photographer traveling in Japan meets another American, Emily. They travel the country together and fall quickly in love. Returning home to the US, Ben meets his girlfriend''s family and discovers that Emily is his girlfriend''s older sister.'),
(1074, N's1074', N'TV_SHOW', N'Second  War Diary - The War Day by Day', NULL, 2014, N'TV-NR', 1, N'SEASONS', N'1 Season', N'The greatest conflict the world has known to date lasted from 1 September 1939 to 2 September 1945 when Japan signed the surrender. Six years, 2,190 days, in which the world lived through a terrible war which completely changed the system of alliances of the different countries and the way of life of millions of their inhabitants.'),
(1075, N's1075', N'MOVIE', N'Seated Yoga Level I 13 minutes', NULL, 2016, N'ALL', 14, N'MINUTES', N'14 min', N'This program helps reduce the effects of deep vein thrombosis and for those unable to stand, lie down or walk. Blood moves slowly around the body and the oxygen in the blood will not reach the heart or the brain efficiently causing medical problems such as deep vein thrombosis. Curated by Anne-Marie Newland the founder of Sun-Power-Yoga.'),
(1076, N's1076', N'TV_SHOW', N'Seatbelt Psychic', NULL, 2018, N'TV-PG', 1, N'SEASONS', N'1 Season', N'Seatbelt Psychic surprises unsuspecting ride-share passengers with readings featuring world-renowned medium Thomas John.'),
(1077, N's1077', N'MOVIE', N'Searching for Bobby Fischer', NULL, 1993, N'PG', 110, N'MINUTES', N'110 min', N'Josh is a typical seven-year-old who happens to be a chess prodigy. Josh''s Father is determined to see his son become a champion. During their journey of discovery they learn the one thing neither can afford to lose: their love for each other.'),
(1078, N's1078', N'MOVIE', N'Searching for Augusta: The Forgotten Angel of Bastogne', NULL, 2016, N'13+', 74, N'MINUTES', N'74 min', N'This true story begins with two nurses, Renee LeMaire and Augusta Chiwy, as they treat patients in the Bastogne aid station. Renee was killed on Christmas Eve and became famous as "The Angel of Bastogne." Augusta''s story was lost to history for sixty-five years. Augusta Chiwy''s story is one of great courage and heroism in the face of racial discrimination.'),
(1079, N's1079', N'MOVIE', N'Sean Bones: Live in Concert', NULL, 2011, N'NR', 29, N'MINUTES', N'29 min', N'Sean Bones snaps the punch and kick, reggae pop stylings of his debut album Rings into place in this live performance at NYC''s Piano''s.'),
(1080, N's1080', N'TV_SHOW', N'Sea Power', NULL, 2005, N'7+', 1, N'SEASONS', N'1 Season', N'A chronicle of naval vessels from yesteryear, through to modern day – an extraordinary view from above the water and below. Discover how Liberty Ships were constructed, the development of Aircraft Carriers and how the invention of Sonar affected submarine warfare. It''s all here in Sea Power.'),
(1081, N's1081', N'MOVIE', N'Sea Gypsies', NULL, 2016, N'13+', 78, N'MINUTES', N'78 min', N'The vessel is Infinity, a 120 ft hand-built gypsy boat, crewed by a band of miscreants. The journey, an 8,000 mile pacific crossing, from New Zealand to Patagonia, with a stop in Antarctica. Unlike all the other boats heading to Antarctica though, Infinity is no well-financed, ice-reinforced super yacht, crewed by well-paid professional sailors, with carefully thought out agendas.'),
(1082, N's1082', N'TV_SHOW', N'Scrubs', NULL, 2010, N'TV-14', 9, N'SEASONS', N'9 Seasons', N'The doctors are ready to see you now. And this season, there are old favorites and new blood. J.D. returns, but this time to teach med school, along with Turk, Drs. Cox and Kelso and Intern Denise. Can J.D. and Turk show them how to handle life and death situations without taking life too seriously? Get ready to examine one of the funniest and most unique shows on television.'),
(1083, N's1083', N'TV_SHOW', N'Scrapyard Supercar', NULL, 2019, N'7+', 1, N'SEASONS', N'1 Season', N'Petrolhead Shane Lynch is setting two teams of amateur mechanics a task of epic proportions; they have just four days to build monster machines that can out-perform a ''top-trump'' attribute of a supercar.'),
(1084, N's1084', N'TV_SHOW', N'Scott & Bailey', NULL, 2016, N'TV-14', 5, N'SEASONS', N'5 Seasons', N'This season Janet and Rachel investigate the sinister world of the Darknet, a place that offers complete anonymity to its users. A ruthless game is being played - one man challenges another to murder, leaving a chalk mark at the scene as proof. As more chalk marks are left, identifying more victims, will Janet and Rachel be able to stop these vicious killers before it''s too late?'),
(1085, N's1085', N'MOVIE', N'Scorpio Men on Prozac', NULL, 2020, N'16+', 107, N'MINUTES', N'107 min', N'Satirical comedy follows the trials and tribulations of a group of guys (all, by chance, Scorpios), who connect in group therapy and all of whom are popping "zac," soon will be or should be.'),
(1086, N's1086', N'TV_SHOW', N'SciGirls', NULL, 2010, N'NR', 1, N'SEASONS', N'1 Season', N'From PBS - In the first season of SciGirls, the girls, with the help of scientist mentors, design their own inquiry-based investigations on a huge variety of topics, from the environment to technology and from engineering to nutrition.'),
(1087, N's1087', N'MOVIE', N'School Spirits', NULL, 2020, N'13+', 89, N'MINUTES', N'89 min', N'A girl relocates to a small town only to find it inhabited by ghosts. A struggle against a bad spirit ensues to keep the town''s children safe.'),
(1088, N's1088', N'TV_SHOW', N'Scenic Walks Around the World', NULL, 2008, N'ALL', 1, N'SEASONS', N'1 Season', N'Reader''s Digest takes you to the world''s most unique places of natural beauty best captured on foot. This exhilarating collection ventures off the beaten path to witness sights tourists seldom see, sights you will never forget, and will want to revisit again and again!'),
(1089, N's1089', N'TV_SHOW', N'Scenery Channel', NULL, 2017, N'ALL', 1, N'SEASONS', N'1 Season', N'Fire and Ice and all things In between. Sharecare Windows'' International Award-Winning videographers travel to exotic and everyday locations, capturing the extreme as well as everyday life. Join us for the ultimate vicarious travel experience in Season One as we explore destinations including Iceland, Portugal, Spain, Croatia, Montenegro, and Istanbul.'),
(1090, N's1090', N'TV_SHOW', N'Scaredy Squirrel', N'2021-03-30', 2012, N'TV-G', 4, N'SEASONS', N'4 Seasons', N'Based on a series of children''s books written by Mélanie Watt, this animated series features Scaredy, a creative, offbeat squirrel who is learning to be comfortable in his own fur. Scaredy tackles every challenge that is thrown at him with his trademark dorkiness, but he has a self-confidence that makes him cool.'),
(1091, N's1091', N'MOVIE', N'Say Yes', NULL, 2019, N'18+', 95, N'MINUTES', N'95 min', N'When Lily is diagnosed with cancer, her beloved twin brother, Caden, moves in to help and ends up forming a strong bond with Lily''s husband, Beau. Lily makes the two men in her life promise to find happiness as a couple after she''s gone. But can a straight guy really fall in love with another man?'),
(1092, N's1092', N'MOVIE', N'Sawan Ko Aane Do', NULL, 1979, N'ALL', 153, N'MINUTES', N'153 min', N'Sawan Ko Aane Do is a 1979 Rajshri Productions Hindi movie produced by Tarachand Barjatya and directed by Kanak Mishra. It''s a story about Birju, a poor villager who wants to marry the headman''s daughter, her father gets furious and sends her to the city. Years later, Birju becomes a successful singer and returns to seek his approval.'),
(1093, N's1093', N'MOVIE', N'Savyasachi', NULL, 2018, N'13+', 148, N'MINUTES', N'148 min', N'Savyasachi (meaning Ambidextrous) is based on a twin brother who is absorbed by Naga''s character in the womb and controls his left hand. Unscientifically called the Vanishing Twin Syndrome.'),
(1094, N's1094', N'MOVIE', N'Savoir Adore', NULL, 2006, N'NR', 34, N'MINUTES', N'34 min', N'A funny moment that unfortunately we can only reference as it was trimmed from our latest concert release. Deidra Muro, whose melodious vocals compliment musical cohort Paul Hammer''s boy next door pairing at the helm of indie pop outfit Savoir Adore, does an impression...of Ben Gibbard...singing "Take Me Out To The Ballgame". She of course did not volunteer such an impression, but was egged on to do so by one of her band mates. And, it wasn''t too bad. In this performance at Brooklyn Bowl, the promising New York upstarts reveal an affection for bands like Death Cab For Cutie that might go a little deeper than cute impressions. Here, the band twist lovelorn lyrics and head clenching instrumental/vocal melodies, providing the kind of affecting twine that may as well replace the heart strings for tugging on. Plus, the band''s crisp and tidy pop tunes suggest they place a premium on their craft. In short, Savoir Adore are a band to keep an eye on. Perhaps you should start with this set captured during last summer''s edition of The Northside Festival.'),
(1095, N's1095', N'MOVIE', N'Saving Zoë', NULL, 2019, N'R', 95, N'MINUTES', N'95 min', N'After the murder of her sister Zoë, Echo is determined to uncover the truth. With Zoë''s diary as her guide, Echo finds herself sucked into the darkness of her sister''s world and uncovers how one small decision can lead to tragic consequences.'),
(1096, N's1096', N'MOVIE', N'Saved By Grace', NULL, 2015, N'13+', 85, N'MINUTES', N'85 min', N'Rick (Joey Lawrence), a retired police officer, is despondent over a personal loss and contemplates a dramatic decision of which will change his life forever. At a critical time in his life he meets a mysterious woman Grace (Catalina Rodriguez) who, through her personal stories, gives him a reason to re-examine what is most important to him, Family.'),
(1097, N's1097', N'MOVIE', N'Sasheer Zamata: Pizza Mind', NULL, 2017, N'18+', 73, N'MINUTES', N'73 min', N'Sasheer Zamata''s "Pizza Mind" will give viewers food for thought. In this all-new stand-up special, Sasheer covers a spectrum of topics, from drugs to relationships, racism to politics - nothing is off limits. This multi-talented comedian incorporates different performance elements to express her opinions and dive into her personal life, truly giving you a piece of her mind.'),
(1098, N's1098', N'TV_SHOW', N'SAS Rogue Warriors', NULL, 2018, N'TV-PG', 1, N'SEASONS', N'1 Season', N'The Special Air Service is the most famous combat unit, but the story of how it came into existence has been a guarded secret. The SAS opens up its archive to reveal the true story of their formation during the darkest days of World War II.'),
(1099, N's1099', N'MOVIE', N'Sarah Colonna: I Can''t Feel My Legs', NULL, 2015, NULL, 67, N'MINUTES', N'67 min', N'New York Times Best Seller and "Chelsea Lately" regular, Sarah Colonna, has some stories to tell and she doesn''t care what you think. From how to get out of jury duty to online dating, Sarah does not disappoint in this new special. Filmed live in Los Angeles, CA.'),
(1100, N's1100', N'MOVIE', N'SANDPAPER', NULL, 2019, N'16+', 72, N'MINUTES', N'72 min', N'Eager to add value to her property before selling it, newly-divorced Kate hires an amiable but eccentric local carpenter named Howard to build her a new deck. It soon becomes clear that Howard''s eccentricities mask a complex and devious personality that threatens to upturn Kates whole life, locking the pair in a battle of wills that may cost both of them their sanity. Inspired by a true story.'),
(1101, N's1101', N'MOVIE', N'Sand Castles', NULL, 2014, N'18+', 94, N'MINUTES', N'94 min', N'In rural Indiana, the Daly family wrestles with the mysterious return of Lauren, a daughter kidnapped over a decade ago while her brother Noah was supposed to be watching her. Their uncle, Tommy, then a sheriff''s deputy, was unable to find her, and her case remained unresolved..'),
(1102, N's1102', N'MOVIE', N'San Fernando Valley', NULL, 1944, N'13+', 53, N'MINUTES', N'53 min', N'Cyclone Kenyon (Tombes) decides to make the unusual move of replacing many of the cowboys with cowgirls on his large cattle ranch. However, Roy Rogers is secretly brought in to rid the valley of the lawless element, including the task of capturing the bank robbers who have stolen his life''s savings. Roy poses as the ranch''s new cook in order to complete his second assignment: tame and woo Cyclone''s wild, volatile daughter Dale Kenyon (Evans). Roy gets his first screen kiss here from Betty Lou Kenyon (Porter), Dale''s bratty kid sister, who almost steals the show.'),
(1103, N's1103', N'MOVIE', N'Same Kind of Different as Me', NULL, 2017, N'PG-13', 119, N'MINUTES', N'119 min', N'From The NY Times bestseller comes an inspirational true story about two men from drastically different backgrounds, who develop a surprising bond that will lead them on the most remarkable journey of their lives and forge an everlasting friendship.'),
(1104, N's1104', N'TV_SHOW', N'Salvage: Code Red', NULL, 2009, N'13+', 1, N'SEASONS', N'1 Season', N'This action series documents the dangerous job of responding to the hundreds of shipwrecks reported each year in the wake of storms, head-on collisions, explosions and fire. Salvage workers are a special breed: brave, determined, have great technical skill and be committed to saving crew and cargo from meeting a premature and watery end. This series tells their dramatic and often perilous stories.'),
(1105, N's1105', N'MOVIE', N'Salome Where She Danced', NULL, 1945, N'PG-13', 92, N'MINUTES', N'92 min', N'The camp classic drama that catapolted De Carlo into stardom. During the Austrian-Prussian war, Anna Marie (De Carlo) is a dancer who is forced to flee her country after she is accused of being a spy. She ends up in a lawless western town in Arizona, where she uses her charms and dancing skills to transform herself into "Salome" during her dance routines. She makes such an impact on the town, eventually taming it, that they re-name the town "Salome, Where She Danced." Later on, she moves to San Francisco, where she meets a wealthy Russian man, seduces him, and has him build her her own opera house to perform in. Anna Marie spends her life manipulating one man after another to get what she wants, and they fall fall for her.'),
(1106, N's1106', N'MOVIE', N'Saleslady', NULL, 1938, N'13+', 63, N'MINUTES', N'63 min', N'Millionaire heiress Mary Dakin (Nagel) is tired of gold digging men constantly wanting to marry her for her money, so she decides to take a job at a department store to see if a man will love her for herself. While there, she meets fellow employee Bob Spencer (Heyburn), and the two fall in love and marry whithout Bob ever knowing about Mary''s fortune. Mary is happy even though they are poor, but things go from bad to worse when Bob loses his job and Mary is forced to contact her grandfather for financial help. bob is angry at her deception, refuses her grandfather''s money, and goes to work for a mattress company in dirct competition with her grandfather''s. Eventually, the two companies decide to merge, and with Mary newly pregnant, all ends well for the couple.'),
(1107, N's1107', N'MOVIE', N'Sakka Podu Podu Raja', NULL, 2017, N'13+', 124, N'MINUTES', N'124 min', N'A happy-go-lucky-guy falls in love with the sister of a ruthless gangster. How does the former convince his lover''s brother is the rest of the movie.'),
(1108, N's1108', N'MOVIE', N'Saints and Soldiers: Airborne Creed', NULL, 2012, N'PG-13', 95, N'MINUTES', N'95 min', N'On August 15th, 1944, an invasion in Provence, France was organized by the Americans to support and protect the allied troops marching to Berlin who had already landed in Normandy on June 6, 1944. After jumping over Provence during the night, three paratroopers who have to regroup with their fellow soldiers in the village of Les Arcs, help the local resistance to free some of their members.'),
(1109, N's1109', N'MOVIE', N'Sahil Shah’s: Childish Behaviour', NULL, 2018, N'18+', 72, N'MINUTES', N'72 min', N'Sahil Shah is 27 but mentally considers himself as a 3 year old. He’s one of India’s top comedians and his first ever stand up special Childish Behaviour is a look at his immature life, the silliness and pointlessness of things around him and his innate ability of making stupid faces and silly sounds to make anyone laugh.'),
(1110, N's1110', N'TV_SHOW', N'Sagrada Reset', NULL, 2017, N'TV-14', 2, N'SEASONS', N'2 Seasons', N'Misora has the power to reset time backwards by up to three days, and Kei has as photographic memory that allows him to remember everything, despite the reset. Together, they try to correct the mistakes of the past.'),
(1111, N's1111', N'MOVIE', N'Saaho (Telugu)', NULL, 2019, N'13+', 170, N'MINUTES', N'170 min', N'After many innocents become scapegoats in a mind boggling robbery, an undercover super cop is summoned to the city. While the investigation progresses, dark secrets about one of the biggest mafias of the world surfaces but with a bundle of mysteries attached.'),
(1112, N's1112', N'MOVIE', N'Saaho (Tamil)', NULL, 2019, N'13+', 170, N'MINUTES', N'170 min', N'After many innocents become scapegoats in a mind boggling robbery, an undercover super cop is summoned to the city. While the investigation progresses, dark secrets about one of the biggest mafias of the world surfaces but with a bundle of mysteries attached.'),
(1113, N's1113', N'MOVIE', N'Saaho (Malayalam)', NULL, 2019, N'13+', 170, N'MINUTES', N'170 min', N'After many innocents become scapegoats in a mind boggling robbery, an undercover super cop is summoned to the city. While the investigation progresses, dark secrets about one of the biggest mafias of the world surfaces but with a bundle of mysteries attached.'),
(1114, N's1114', N'MOVIE', N'Saaho (Kannada)', NULL, 2019, N'13+', 169, N'MINUTES', N'169 min', N'After many innocents become scapegoats in a mind boggling robbery, an undercover super cop is summoned to the city. While the investigation progresses, dark secrets about one of the biggest mafias of the world surfaces but with a bundle of mysteries attached.'),
(1115, N's1115', N'MOVIE', N'Ryan Shaw', NULL, 2004, N'NR', 26, N'MINUTES', N'26 min', N'Ryan Shaw works his way through a soulful, sunset performance on the spectacular shores of the Long Island Sound.'),
(1116, N's1116', N'MOVIE', N'Ryan Bingham Live', NULL, 2016, N'PG-13', 110, N'MINUTES', N'110 min', N'GRAMMY and Oscar award-winning Americana singer-songwriter Ryan Bingham brings his dynamic live show direct to fans. Filmed at the Whitewater Amphitheater on August 6, 2016.'),
(1117, N's1117', N'MOVIE', N'RX100', NULL, 2018, N'18+', 148, N'MINUTES', N'148 min', N'Shiva (Kartikeya) is a village youth who falls for a city bred girl Indu (Payal). As a passionate romance brews, Shiva falls madly in love with her, but things don''t turn out as expected. Indu got married to someone else and departs to USA ,but Shiva waits 3 years for her in mad hope of uniting with her. She returns to their village one day, but does Shiva get her back?'),
(1118, N's1118', N'TV_SHOW', N'Ruyi''s Royal Love in The Palace', NULL, 2018, N'13+', 1, N'SEASONS', N'1 Season', N'The show tells a story of the most distinguished empress of the Qing Dynasty of China:With the family''s disgrace, Ruyi learns the politics of the harem and finally becomes the Empress. But after surviving a series of conspiracies, her relationship with her husband, the Emperor has become irreparable. Finally, Ruyi got depressed by the cruel reality of life in the Palace...To be continued'),
(1119, N's1119', N'MOVIE', N'Rustum', NULL, 2019, N'NR', 127, N'MINUTES', N'127 min', N'The story revolves around a super cop who is sincere, brave and deadly. He is on a mission to end nexus of the organ trading mafia across the country and to take revenge for the brutal murder of his close friend.'),
(1120, N's1120', N'TV_SHOW', N'Russell Peters: Deported', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'Russell Peters takes his culturally comedic roadshow to the land of his ancestors, Mumbai, India for an evening that’s as informative as it is entertaining. Reflecting on his own immigrant lineage Peters proves why he’s more than one in 1.3 billion.'),
(1121, N's1121', N'MOVIE', N'Rupture', NULL, 2017, N'18+', 101, N'MINUTES', N'101 min', N'A single mom tries to break free from a mysterious organization that has abducted her.'),
(1122, N's1122', N'MOVIE', N'Running for Grace', NULL, 2018, NULL, 111, N'MINUTES', N'111 min', N'An orphan boy of mixed race finds family with the newly arrived white village doctor in Hawaii. The boy can run like the wind, and begins bringing Doc''s medicine to coffee pickers throughout the mountainous region. On an errand, the medicine runner meets the daughter of the plantation owner and a forbidden, young love blossoms like the white "Kona Snow" of the surrounding coffee trees.'),
(1123, N's1123', N'MOVIE', N'Runnin'' From My Roots', NULL, 2018, NULL, 92, N'MINUTES', N'92 min', N'Following a devastating breakup with her fiancé, Grammy Award-winning Nashville Country star Faith Winters escapes to her rural Smithville hometown, where she rediscovers feelings for her high school sweetheart turned local Pastor, and must balance these unexpected emotions with the career she left behind in Nashville, and the disruption her return brings to her small town.'),
(1124, N's1124', N'TV_SHOW', N'Runaway Squad', NULL, 2010, N'TV-14', 1, N'SEASONS', N'1 Season', N'Former NYPD detective Joe Mazzilli leads a team of private investigators – real-life superheroes, some call them – who track runaways with the hope of reuniting them with their families.'),
(1125, N's1125', N'MOVIE', N'Rumble: The Indians Who Rocked the World', NULL, 2017, N'13+', 102, N'MINUTES', N'102 min', N'This revelatory documentary brings to light the profound and overlooked influence of Indigenous people on popular music in North America. The films focuses on music icons like Link Wray, Jimi Hendrix, Buffy Sainte-Marie, Taboo (The Black Eyed Peas), Charley Patton, Mildred Bailey, Jesse Ed Davis, Robbie Robertson, and Randy Castillo.'),
(1126, N's1126', N'MOVIE', N'Rudy Ruettiger: The Walk On', NULL, 2018, N'7+', 78, N'MINUTES', N'78 min', N'Most people know the story of Rudy, the small kid from Illinois who was determined to play football for Notre Dame despite having neither a strong academic nor athletic background. But not many know the full story. Hear in his own words how Rudy Ruettiger succeeded in getting into, and playing for Notre Dame, despite dozens of rejections. And hear how Rudy got his story out to the world.'),
(1127, N's1127', N'TV_SHOW', N'Rubbadubbers', NULL, 2005, N'TV-Y', 4, N'SEASONS', N'4 Seasons', N'Arr! Arr! Arr! The Rubbadubbers are having a splashing good time making wishes, hunting monsters, playing sports, meeting ghosts, and painting the sky.'),
(1128, N's1128', N'MOVIE', N'Rotters', NULL, 2015, N'13+', 22, N'MINUTES', N'22 min', N'''Oceans 11'' meets ''Dumb and Dumber'' in this action-packed slapstick riot of a show starring comedian Frank Skinner. Rotters follows a blundering gang of buffoons who attempt to rob an auction house owned by an antiques dealer (Skinner). Staring Phil Burgers, John Kearns, Sam Simmons, Lolly Adefope and Daniel Simonsen.'),
(1129, N's1129', N'TV_SHOW', N'Ross Kemp: Middle East', NULL, 2010, N'16+', 1, N'SEASONS', N'1 Season', N'In these two hard-hitting, emotional and revealing programmes, Ross Kemp offers a fascinating insight into life on both sides of the divided Middle East.'),
(1130, N's1130', N'TV_SHOW', N'Rose and Maloney', NULL, 2005, N'13+', 3, N'SEASONS', N'3 Seasons', N'Rose Linden and Maloney investigate old criminal cases, seeking to rectify miscarriages of justice. Starring British television icons Sarah Lancashire and Phil Davis.'),
(1131, N's1131', N'MOVIE', N'Root of the Problem', NULL, 2020, N'7+', 95, N'MINUTES', N'95 min', N'When a suburban family inherits a real-life money tree, the dad thinks he has a one-way ticket to easy street. But he loses sight of the things that matter most in life and becomes more distant and secretive with his wife and children. Now, the family will be tested and must search within their hearts to find the answers and discover that it is better to give than receive.'),
(1132, N's1132', N'TV_SHOW', N'Room at the Top', NULL, 2012, N'18+', 1, N'SEASONS', N'1 Season', N'Set in post-war Britain and based on John Brain''s classic novel, this drama follows a young man''s struggle to rise above the world of his childhood and in the end, Joe must choose between the true love he feels for one woman and the success and stability offered by a union with another.'),
(1133, N's1133', N'MOVIE', N'Room 6', NULL, 2006, N'R', 94, N'MINUTES', N'94 min', N'Amy''s boyfriend is injured in a car crash and taken to a hospital that no longer exists. There, Amy and a concerned stranger enter a nightmare where demons walk among us, hallucinations run rampant, and sultry nurses engage in lesbian blood rites.'),
(1134, N's1134', N'TV_SHOW', N'Ronja, the Robber''s Daughter', NULL, 2017, N'7+', 1, N'SEASONS', N'1 Season', N'Presented by Studio Ghibli. The daughter of a professional robber, Ronja realizes the complicated nature of her father''s profession when she befriends Birk, the child of a rival tribe. She struggles to balance this friendship with her family relationship but comes to understand, differences can be overcome with the help of love and understanding.'),
(1135, N's1135', N'MOVIE', N'Romola', NULL, 1924, N'NR', 118, N'MINUTES', N'118 min', N'In Renaissance Florence, Tito, a no-good young man pretending to be a scholar, wins the admiration of a blind man who has long looked for someone to finish his scholarly work.'),
(1136, N's1136', N'TV_SHOW', N'Rome - Empire Without Limit', NULL, 2016, N'16+', 1, N'SEASONS', N'1 Season', N'Traveling from Spain to Israel, Algeria to Britain, Germany to Turkey, historian Mary Beard answers the big questions that have fascinated people for centuries. How did a small city, Rome, acquire an empire? And why did it fall? Mary examines its creation, successes, failures and the legacy, not just in its technology and buildings, its roads and laws, but also in the worlds that came after it.'),
(1137, N's1137', N'MOVIE', N'Romance On The Range', NULL, 1942, N'13+', 53, N'MINUTES', N'53 min', N'Roy Rogers, the owner of a western ranch, suspects his highly secretive foreman Banning (Pawley) of the looting his fur traps. He goes undercover as a ranchhand on his own ranch. He begins a romance with trading post proprietress Joan Stuart (Hayes), who has no idea of Roy''s real identity. Through his investigation, he discovers that Banning is the head of a gang who has been stealing fur from all the local ranchers and fencing it at the Trading Post. Joan convinces Roy she had nothing to do with the gang. Roy and Joan then work together to capture Banning and his gang of outlaws.'),
(1138, N's1138', N'MOVIE', N'Roman Holiday', NULL, 1953, N'7+', 118, N'MINUTES', N'118 min', N'Audrey Hepburn captured an Oscar for her portrayal of a modern-day princess, rebelling against the royal obligations, who explores Rome on her own. She meets Gregory Peck, an American newspaperman who, seeking an exclusive story, pretends ignorance of her true identity. But his plan falters as they fall in love.'),
(1139, N's1139', N'MOVIE', N'Rolling Home', NULL, 1946, N'ALL', 68, N'MINUTES', N'68 min', N'Former old-time rodeo performer Pop Miller (Hatton) and his grandson (Henry) arrive in a small town with their injured horse. The local minister David Owens (Hayden) welcomes the two to their community and nurses the horse back to health. But the church is in serious debt, and the local wealthy young town widow Frances Crawford (Parker) not only selfishly refuses to help, but looks down her nose at the new town residents. Pop Miller decides to repay the minister''s kindness by entering the horse in a surrey race, which he wins, earning enough money to save the small church and earning the respect of the Widow Crawford.'),
(1140, N's1140', N'TV_SHOW', N'Rolie Polie Olie', NULL, 1998, N'TV-Y', 1, N'SEASONS', N'1 Season', N'This amazing CG-animated series depicts the hilarious childhood of Olie, a young robot who lives in a magical, futuristic, all-robot world of blue skies and happy, helpful machines - where virtually everything from baby carriages to spaceships comes to life.'),
(1141, N's1141', N'TV_SHOW', N'Rodeo Girls', NULL, 2014, N'TV-14', 1, N'SEASONS', N'1 Season', N'Follow a group of veterans and rookies fueled by their motivation to win as they travel around the country with their horses and colorful attitudes. The ladies of the rodeo work hard, ride fast and play rough. Their tumultuous relationships, fierce competition and plenty of cowboys leave plenty of drama to go around.'),
(1142, N's1142', N'MOVIE', N'Rodeo & Juliet', NULL, 2015, N'7+', 88, N'MINUTES', N'88 min', N'Instead of spending her holiday break in the big city, Juliet is taken by her mother to the country for Christmas, where she develops a bond with her late grandfather''s horse and catches the eye of a local cowboy.'),
(1143, N's1143', N'TV_SHOW', N'Rocky and Bullwinkle', NULL, 2019, N'7+', 2, N'SEASONS', N'2 Seasons', N'The world-famous talking moose and flying squirrel are back in The Adventures of Rocky and Bullwinkle, a comedy about two goofball friends who end up in harrowing situations but end up saving the day time and again. As their silly ambitions dovetail with Fearless Leader''s sinister plans to take over the world, they are set on a collision course with his notorious super spies Boris and Natasha.'),
(1144, N's1144', N'MOVIE', N'Robin Hood (Silent)', NULL, 1922, N'13+', 121, N'MINUTES', N'121 min', N'Amid big-budget medieval pageantry, King Richard goes on the Crusades leaving his brother Prince John as regent, who promptly emerges as a cruel, grasping, treacherous tyrant.'),
(1145, N's1145', N'MOVIE', N'Robert', NULL, 2015, N'13+', 94, N'MINUTES', N'94 min', N'In this chilling story based on real life events a family experience terrifying supernatural occurrences when their son acquires a vintage doll called Robert.'),
(1146, N's1146', N'MOVIE', N'Rob Schneider: Soy Sauce and the Holocaust', NULL, 2013, N'18+', 60, N'MINUTES', N'60 min', N'Rob Schneider takes on the biggest role of his life: a stand-up comedian, as he learns lessons about love and other cultures. He tells the side-splitting stories of the three hoods: childhood, adulthood, and parenthood. From closet farts to his sex life, Rob isn''t holding back any of the dirty details.'),
(1147, N's1147', N'TV_SHOW', N'Rob Delaney: Jackie', NULL, 2020, N'18+', 1, N'SEASONS', N'1 Season', N'Critically acclaimed American comic, and co-creator & star of ‘Catastrophe’, Rob Delaney unpacks the horror and the joys of his life in London: swimming in tea, getting scammed, being a father and a husband, the monarchy, the rise of the sexbots, and the disappearance of his friend Jackie.'),
(1148, N's1148', N'MOVIE', N'Road Dogz', NULL, 2002, N'R', 96, N'MINUTES', N'96 min', N'Carefree days come to an end when three Latino friends face personal crises in Los Angeles.'),
(1149, N's1149', N'MOVIE', N'Rivers and Roads: The Head And The Heart - Live from Pike Place Market', NULL, 2020, N'13+', 74, N'MINUTES', N'74 min', N'The Head and the Heart return to their Seattle roots to play a rooftop concert at the city''s infamous Pike Place Market in front of the market''s iconic clock and sign. Watch as the band performs a high energy concert in front of 30,000 hometown fans, two stories from where they originally started busking for tips ten years ago.'),
(1150, N's1150', N'TV_SHOW', N'Ritual', NULL, 2017, N'TV-NR', 1, N'SEASONS', N'1 Season', N'RITUAL. Everyone has one. The pregame prep. The meticulous steps. NFL players, coaches, fans. You. This is the story about two teams (and their fans) playing for Thursday Night Football bragging rights. But before anyone takes the field or the stands, surprisingly intertwined game day rituals unfold.'),
(1151, N's1151', N'MOVIE', N'Rise of the Great White Shark', NULL, 2017, N'ALL', 49, N'MINUTES', N'49 min', N'This film traces the rise of the Great White Shark 11 million years ago in the wake of dramatic changes in Earth''s oceans and climate. At the end of an age dominated by giant ocean predators, white sharks evolved in tandem with seals and other pinnipeds in response to cooling conditions. This film is the result of a decade of filming white sharks by renowned "Shark Week" cameraman Andy Casagrande.'),
(1152, N's1152', N'MOVIE', N'Right At Your Door', NULL, 2007, N'R', 91, N'MINUTES', N'91 min', N'With Los Angeles under sieges by toxic bombs, Brad and Lexi struggle to survive with little supply, limited time and no information.'),
(1153, N's1153', N'MOVIE', N'Riders of the Whistling Pines', NULL, 1949, N'NR', 70, N'MINUTES', N'70 min', N'Badguys Henry, Bill and Pete head a gang of outlaws who are destroying the timberland. When Gene butts in they frame him on a cattle-poisoning charge and set him up for murder.'),
(1154, N's1154', N'MOVIE', N'Riders of the Rockies', NULL, 1937, N'ALL', 59, N'MINUTES', N'59 min', N'Tex Rand (Ritter) and his two friends Pee Wee (Pollard) and Doc (Murphy) decide to join the Arizona Rangers together, and soon after rescue pretty stagecoach passenger Louise Rogers (Stanley) from a gang of rustlers. The Rangers soon join up with the Mexican Rurales to fight the rustlers, but Pee Wee and Doc are falsely accused of stealing, and thrown in jail. Tex decides to infiltrate the criminal gang by pretending to desert the Rangers, making quick friends with the leader Jeffries (Dwire). Louise, in reality a secret agent, poses as a saloon singer and together she and Rex manage to take down the gang of rustlers, along with freeing Tex''s friends.'),
(1155, N's1155', N'MOVIE', N'Ride', NULL, 2015, N'R', 93, N'MINUTES', N'93 min', N'When her son (Brenton Thwaites) drops out of school in New York, a mother (Helen Hunt) drops everything to follow him to California. There, with help from an expert surfer (Luke Wilson), she finds a fresh start of her own in this hilarious and touching film about a mother, her son, and so much more.'),
(1156, N's1156', N'MOVIE', N'Rickover: The Birth of Nuclear Power', NULL, 2014, NULL, 115, N'MINUTES', N'115 min', N'Admiral Hyman G. Rickover was a flamboyant maverick and a unique American hero. When few thought it possible, then-Captain Rickover harnessed the power of the atom, ultimately transforming the Navy and changing the course of America''s technological development.'),
(1157, N's1157', N'TV_SHOW', N'Rick Steves'' Europe', NULL, 2018, N'TV-G', 4, N'SEASONS', N'4 Seasons', N'Rick Steves'' Europe is public television''s most-watched, longest-running travel series. Written and hosted by best-selling guidebook author Rick Steves, each half-hour show takes viewers to Europe''s most interesting places, from great cities to off-the-beaten-path discoveries.'),
(1158, N's1158', N'TV_SHOW', N'Rick Stein''s Mediterranean Escapes', NULL, 2007, N'TV-PG', 1, N'SEASONS', N'1 Season', N'Inspired by ''good food that stays in the memory for a long time, sometimes forever'', Rick Stein journeys across the Mediterranean, visiting islands and places which radiate a vibrant sense of individuality through their spirit, history and food. Join Rick as he travels from Corsica to Crete, straight through the very cradle of cooking in the western world.'),
(1159, N's1159', N'TV_SHOW', N'Rick Stein''s Long Weekends', NULL, 2016, N'TV-PG', 1, N'SEASONS', N'1 Season', N'Rick Stein embarks on a series of culinary long weekends in search of food excellence and brilliant recipes, heading to markets, restaurants, wineries, cafes and bars. From fabulous local markets and great restaurants to wineries, cafes and bars, Rick showcases food excellence and brilliant recipes that people will love to cook at home.'),
(1160, N's1160', N'TV_SHOW', N'Rick Stein''s India', NULL, 2013, N'13+', 1, N'SEASONS', N'1 Season', N'Intrepid chef Rick Stein embarks on a spectacular culinary journey through the Indian sub-continent in his quest to find the perfect curry and discover the origins of dishes, ingredients and spices that are celebrated the world over.'),
(1161, N's1161', N'TV_SHOW', N'Rick Stein''s Far Eastern Odyssey', NULL, 2009, N'13+', 1, N'SEASONS', N'1 Season', N'Chef Rick Stein sets off on an epic culinary journey to explore the Far East''s most diverse food cultures, which have soared to the heights of popularity the world over. Along the way, Rick visits traditional family-run restaurants, street vendors, night markets, fishing villages, and local farmers to learn about the authentic food of the area, and to sample the delicious spectrum of flavors.'),
(1162, N's1162', N'MOVIE', N'Rick Stein and the Japanese Ambassador', NULL, 2006, NULL, 59, N'MINUTES', N'59 min', N'Challenged by the UK''s Japanese Ambassador to cook a Japanese banquet for his distinguished guests, Rick spends one week visiting Japan''s vibrant fish markets and island restaurants, aiming to master the art of cooking fish - Japanese-style. Japan is arguably the ultimate destination for serious lovers of fish. Will Rick being be able to learn enough to impress all at the banquet?'),
(1163, N's1163', N'TV_SHOW', N'Richard Simmons'' Dream Maker', NULL, 2017, N'ALL', 1, N'SEASONS', N'1 Season', N'The wildly inspiring and quirky talk show starring the famed exercise guru, actor, and comedian, Richard Simmons, is back. With the help of his celebrity friends, Richard Simmons brings joy to a live audience as he fulfills the dreams of everyday people. Features a vast array of celebrity guests including Rosie O'' Donnell, Jay Leno, Maury Povich, Rick Springfield, and Kenan Thompson.'),
(1164, N's1164', N'MOVIE', N'Richard Pryor: Icon', NULL, 2014, N'13+', 55, N'MINUTES', N'55 min', N'Survey the profound and enduring influence of one of the greatest American comics of all time.'),
(1165, N's1165', N'MOVIE', N'Richard Lewis: Magical Misery Tour', NULL, 1997, N'18+', 57, N'MINUTES', N'57 min', N'Lewis'' 1997 HBO stand-up special was filmed at New York''s historic Bottom Line. Hailed by the Los Angeles Times as his "best show ever", Magical Misery Tour was Lewis'' proof to himself that he could do a high pressured gig sober.'),
(1166, N's1166', N'TV_SHOW', N'Richard Hammond''s Crash Course', NULL, 2012, N'13+', 2, N'SEASONS', N'2 Seasons', N'In this second season, Richard takes his Crash Course to a new level. He immerses himself in uniquely American and often terrifying vocations - tasked with quickly acquiring skills that are not only outside his range of expertise, but pull at the strings of some of his greatest fears.'),
(1167, N's1167', N'MOVIE', N'Richard Hammond Meets Evel Knievel', NULL, 2007, NULL, 59, N'MINUTES', N'59 min', N'Top Gear star Richard Hammond travels to Butte, Montana, to interview his childhood hero, 70s stuntman Evel Knievel. But will the sick and aging icon warm to his fan?'),
(1168, N's1168', N'TV_SHOW', N'Rich Africans', NULL, 2018, N'13+', 1, N'SEASONS', N'1 Season', N'Two Rich Africans try to find their way in America.'),
(1169, N's1169', N'TV_SHOW', N'Rhythms of Faith', NULL, 2020, N'13+', 1, N'SEASONS', N'1 Season', N'Three university students are "Rhythms of Faith", a performing arts club, who share a unique bond of friendship and love for artistic expression; but their bond and artistic hopes are challenged when one member expresses interest in Islam.'),
(1170, N's1170', N'MOVIE', N'Rhythm In the Clouds', NULL, 1937, N'PG', 53, N'MINUTES', N'53 min', N'Struggling songwriter Judy Walker talks her way into the apartment of a famous composer, and finds that he''s on vacation. Homeless and without any money, she decides to stay at his place until his return, making use of all his belongings, and spreading the word that she is the composer''s collaborator. She writes a song, wtih the composer listed as the co-writer, which becomes a big radio hit. The famous composer returns, and screwball comedy ensues.'),
(1171, N's1171', N'MOVIE', N'Rhymes for Kids and Babies - Spooky Halloween Songs - Mother Goose Club', NULL, 2015, N'ALL', 18, N'MINUTES', N'18 min', N'Join the Mother Goose Club in their favorite Halloween nursery rhymes and songs for kids and babies! Explore "A Haunted House on Halloween Night," meet the "Monster Finger Family," play the "Halloween Mystery Box" challenge and more! Rhyme, dance and learn, but look out for the spooky ghosts and scary monsters!'),
(1172, N's1172', N'TV_SHOW', N'Rex the Runt', NULL, 2001, N'TV-PG', 2, N'SEASONS', N'2 Seasons', N'Discover the Joy of Rex. Join REX THE RUNT and his chums – the pert-bum-loving Wendy, Chuffy-chomping Bad Bob and our own little Hoover-hankering Vince – for bizarre Telly adventures with Easter Island stone-head aliens, singing sausages, a Sinister Secret Laboratory, the Go-Back-In-Time-A-Tron? and more! REX THE RUNT, the cult hit that originally aired on the BBC (from the company that brought you Wallace and Gromit and Chicken Run), is an amazingly stupid and stupendously amusing romp that''ll challenge everything you thought you knew about plasticene dogs.'),
(1173, N's1173', N'MOVIE', N'Rex the Devil Horse (Silent)', NULL, 1926, N'NR', 53, N'MINUTES', N'53 min', N'It''s 1874 and young Dave Carson and his colt Rex are part of a wagon train. When Indians attack and wipe out the train, the two escape going separate ways. Six years later Dave is a scout for the Army and Rex is the Devil Horse.'),
(1174, N's1174', N'MOVIE', N'Review: Pac-Man App Review', NULL, 2017, N'ALL', 4, N'MINUTES', N'4 min', N'Total Toys TV reviews the Pac-Man app highlighting it''s features, functions, controls and more.'),
(1175, N's1175', N'MOVIE', N'Revenge for Jolly', NULL, 2012, N'R', 84, N'MINUTES', N'84 min', N'A man recruits his cousin to find out who is behind his dog''s suspicious death.'),
(1176, N's1176', N'TV_SHOW', N'Rev & Roll', NULL, 2019, N'TV-Y', 1, N'SEASONS', N'1 Season', N'Join 8-year-old Rev and his best friend, Rumble-a rambunctious, powerful truck with a puppy personality! Whether they''re helping around town or roaring through the wilderness, Rev, Rumble and their friends are always ready to rev and roll!'),
(1177, N's1177', N'TV_SHOW', N'Return to the Mackenzie - Expedition Overland', NULL, 2016, N'TV-PG', 1, N'SEASONS', N'1 Season', N'Old crews join with the new as Expedition Overland returns to the MacKenzie Trail that defeated the team in episode 12 of the Alaska/Yukon Season (2013). Their goal is to map and finish the fading historical trail of Alexander MacKenzie, originally founded in 1793. River crossings, off-roading, low fuel, and teamwork are all in this full, three-part series to inspire you to explore your world!'),
(1178, N's1178', N'MOVIE', N'Return of the Tiger', NULL, 2007, N'18+', 93, N'MINUTES', N'93 min', N'The most brutal action packed martial arts battle of the decade, Bruce Li, The Roaring Kung Tiger, faces his deadliest enemy.. the vicious and sadistic torturer from The Midnight Express. The Hoover Night Club in Bangkok is used to coverup the operations of the international narcotics group headed by an American, George Cross.'),
(1179, N's1179', N'MOVIE', N'Restoring the Shack', NULL, 2020, N'13+', 101, N'MINUTES', N'101 min', N'Join author William Paul Young on an adventure into the world of the best-selling phenomenon, The Shack. Stunningly filmed this inside look at how Paul''s own life journey shaped his writing explores questions of faith, grief, wonder and relationship with the Father, Son and Holy Spirit.'),
(1180, N's1180', N'TV_SHOW', N'Rescue Special Ops', NULL, 2010, N'16+', 3, N'SEASONS', N'3 Seasons', N'Dean Gallagher and Chase are brothers. Competitive alpha males, they argue over everything, agree on nothing, but defend each other from outsiders no matter what. They''re also members of the elite Rescue Special Operations Unit.'),
(1181, N's1181', N'TV_SHOW', N'Requiem From the Darkness (English Dub)', NULL, 2003, N'18+', 1, N'SEASONS', N'1 Season', N'Momosuke meets a strange group of outlaws, Mataichi, Ogin and Miminaga on one stormy night. Darkness hidden inside human minds, and the people who battle the wickedness inside human nature. With amazing skills of illusion and art, Mataichi Group sheds light to the darkness in human minds to liberate the spirit from evil.'),
(1182, N's1182', N'MOVIE', N'Renfrew Of The Royal Mounted', NULL, 1937, N'13+', 56, N'MINUTES', N'56 min', N'Royal Canadian Mountie Renfrew is assigned to bust a counterfeiting ring operating on the Canadian-USA border, with the aid of his dog "Lightning". Renfrew chases the crooks on horseback and airplane to no avail. Ring leader George Poulis has forced engraver James Bronson, a former convict, into working with his gang through threats. Bronson''s daughter Virginia convinces him to escape but they are caught by George''s thugs. The pair are thrown into the lodge''s refrigerated meat locker, making it a race against time for Renfrew to rescue the pair and capture the bad guys at the same time.'),
(1183, N's1183', N'MOVIE', N'Remembering Leonard Nimoy', NULL, 2017, NULL, 57, N'MINUTES', N'57 min', N'Remembering Leonard Nimoy is a loving and very personal tribute to the life and career of Leonard Nimoy, the prolific actor and director who is best known for playing Spock in Star Trek. In addition to stories from his childhood and anecdotes from his early career in Hollywood, the film shows how he helped raise awareness for the lung disease that eventually took his life, COPD.'),
(1184, N's1184', N'MOVIE', N'Relentless', NULL, 2020, N'16+', 63, N'MINUTES', N'63 min', N'Diamond Dallas Page''s journey to save his wrestling career transforms into a lifelong passion for helping others achieve their true potential.'),
(1185, N's1185', N'MOVIE', N'Relaxing Water', NULL, 2012, N'ALL', 60, N'MINUTES', N'60 min', N'A soothing video postcard with no narration-simply the natural sounds and video in HD. DeSoto Falls, Iao Valley Maui, Grand Bahama Island, Punta Mita Golf Course Mexico, Sipalay Boats, Caceres Reef and Glassfish, Philippines, Aruba beach, Del Norte Coast CA, Yellowstone Nat''l Park, Tumalo Falls OR, Colorado River Texas, Oregon Cattle Ranch, Rocky Coastline Chile, Schroon River and more.'),
(1186, N's1186', N'MOVIE', N'Relaxing Rocky Beaches', NULL, 2012, N'ALL', 60, N'MINUTES', N'60 min', N'A soothing video postcard with no narration or music-simply the natural sounds and video in HD. Asilomar Beach Monterey, Vidigal Beach Rio de Janeiro Brazil, Del Norte Coast California, Nakalele Blowhole Maui, Tide Pools Sea of Cortez Mexico, Surf Seagulls Northern California, East Cape San Jose del Cabo Sur Mexico, Old Tree On Beach Hawaii, Rocky Beach Cabo San Lucas Mexico.'),
(1187, N's1187', N'MOVIE', N'Relaxing Beaches with music', NULL, 2019, NULL, 60, N'MINUTES', N'60 min', N'Sharecare Windows presents the beauty of the great outdoors inside. Relax with beautiful beaches from around the world. This original collection showcases the inspirational beauty of nature accompanied by original music scores created exclusively for Sharecare Windows. Each original program creates an engaging and relaxing escape into nature.'),
(1188, N's1188', N'TV_SHOW', N'Regular Heroes', NULL, 2020, N'13+', 1, N'SEASONS', N'1 Season', N'The COVID pandemic has drastically changed our lives. Regular Heroes highlights the selfless acts of essential workers, who risk it all to keep their communities afloat. From grocery clerks to hospital workers and teachers, these individuals remind us there is still hope when we work together to make a difference. The series will include special guest appearances by Alicia Keys and more.'),
(1189, N's1189', N'MOVIE', N'Reg''lar Fellers', NULL, 1941, N'13+', 70, N'MINUTES', N'70 min', N'A group of local kids calling themselves the "Reg''lar Fellers", led by Switzer and Lee, invent a machine that they believe can run on land as well as in the water. The gang gets mixed up with gangsters who have framed local woman Hetty Carter''s son and have come to town to rob her. Hetty happens to be a wealthy dowager who hates all kids due to her son''s situation. With her son in jail on the false charge, Hetty takes out all her anger on her daugther-in-law Caroline and her young grandson. The "Reg''lar Fellers" foil the plans of con artists Ferrell and Lubec to swindle Hetty out of her fortune. In gratitude, Hetty builds a new clubhouse for the Reg''lar Fellers, throws them a huge party, and gives a home to Caroline and her grandson.'),
(1190, N's1190', N'MOVIE', N'Redwood Highway', NULL, 2013, N'PG-13', 90, N'MINUTES', N'90 min', N'Living in a retirement community, estranged from her family, Marie decides to journey 80 miles on foot to attend her granddaughter''s wedding. Along the way, she discovers that you''re never too old to learn something about life & yourself.'),
(1191, N's1191', N'MOVIE', N'Redeemer', NULL, 2015, N'18+', 90, N'MINUTES', N'90 min', N'Martial arts master Marko Zaror stars as an ex-hitman who offers thugs a chance to plead forgiveness for their crimes or pay the ultimate price. After years in exile, he returns to the streets to right the wrongs of his past. Spanish and English language film with English subtitles.'),
(1192, N's1192', N'TV_SHOW', N'Redakai: Lokar''s Shadow', NULL, 2013, N'TV-Y7', 1, N'SEASONS', N'1 Season', N'Ky, a 15-year old student of ancient martial arts, embarks on an epic quest to find the Kairu, a primordial alien energy source. Aided by his friends Maya and Boomer, Ky travels the world searching for the Kairu while attempting to make sure that his extraterrestrial teenage alien adversaries don''t find it first.'),
(1193, N's1193', N'TV_SHOW', N'Red Rock', NULL, 2018, N'18+', 3, N'SEASONS', N'3 Seasons', N'Sharon goes to extreme measures to keep Robbie safe from Laser, but could her good deed be about to go terribly wrong? It’s Angela’s first day as acting Detective Sergeant. Despite husband Tommy’s reservations, she has gladly taken Superintendent Dunne up on his offer to move up the ranks.'),
(1194, N's1194', N'MOVIE', N'Red Nights', NULL, 1988, N'R', 90, N'MINUTES', N'90 min', N'The Story of a Idealistic Young man who goes to Los Angeles to become an actor, but is disillusioned and jaded when the cold and realistic violent world of Hollywood shatters then explodes all around him.'),
(1195, N's1195', N'MOVIE', N'RED GARTERS', NULL, 1954, N'7+', 91, N'MINUTES', N'91 min', N'Rosemary Clooney heads up the high-kicking, red-gartered girls of the Red Dog Saloon. They can-can, but she won''t-won''t unless Jason (Jack Carson) asks her to get hitched.'),
(1196, N's1196', N'MOVIE', N'Recoil', NULL, 2011, N'18+', 94, N'MINUTES', N'94 min', N'After the murder of his family, former cop John Varrett goes vigilante in order find the criminals that have slipped through the system and exercise his own brand of ruthless justice.'),
(1197, N's1197', N'MOVIE', N'Rebel: Loreta Velazquez, Secret Soldier of the American Civil War', NULL, 2013, NULL, 54, N'MINUTES', N'54 min', N'At the outset of the American Civil War, Loreta Janeta Velazquez, an educated Cuban born teenager, fought as an officer in the battle of First Bull Run, was wounded at Shiloh, and served as a secret agent for the Confederacy. By 1863, Velazquez was spying for the Union.'),
(1198, N's1198', N'TV_SHOW', N'Real Love Stories from Around the World: United States - Love Stories TV', NULL, 2018, N'ALL', 1, N'SEASONS', N'1 Season', N'Watch real wedding videos to find wedding venues, wedding videographers, and vendors for your wedding! Enjoy this series of weddings around the United States.'),
(1199, N's1199', N'TV_SHOW', N'Real Crime Chronicles', NULL, 2016, N'16+', 1, N'SEASONS', N'1 Season', N'This long running crime series delves into the heart of highly-publicised disappearances, the most meticulous crimes, unresolved multiple murders, kidnapping, illegal confinement and stories of passion that met shocking and tragic endings.'),
(1200, N's1200', N'MOVIE', N'Real American Hero', NULL, 1978, NULL, 90, N'MINUTES', N'90 min', N'Brian Dennehey plays real-life Tennessee Sheriff Buford Pusser. One day he stops a car driving erratically, and is disgusted when he discovers that two of the teenage occupants are dead and two are permanently blinded because all four of them had drank locally-made moonshine. Buford decides to go on a one-man destructive rampage against the disco-owner and the moonshiner responsible for the teen''s misfortunes. Buford also protects aging former prostitute Carrie Todd (North), who just wants to live a normal life in the small town after just being released from prison for murdering her pimp.');



©TV TOKYO'),
(1725, N's1725', N'MOVIE', N'Maserati: A Hundred Years Against All Odds', NULL, 2020, N'7+', 89, N'MINUTES', N'89 min', N'Celebrate the long and storied history of one of the world''s most recognizable icons, Maserati. From humble beginnings into a small Italian garage to the coveted and luxurious automobile we know today, witness the evolution of the business, the brand, and the cars themselves over 100 years. Featuring interviews with the Maserati family, world-famous racers, collectors, and more.'),
(1726, N's1726', N'MOVIE', N'Mary Higgins Clark''s: Pretend You Don''t See Her', NULL, 2002, N'PG-13', 94, N'MINUTES', N'94 min', N'As she lay dying, a woman gives the only witness to her murder her daughter''s journal, implying that her attacker may also be responsible for her child''s death. Before giving the journal to the police, the witness makes a copy for herself - an act she will live to regret.'),
(1727, N's1727', N'MOVIE', N'Mary Higgins Clark''s: He Sees You When You''re Sleeping', NULL, 2002, N'PG', 95, N'MINUTES', N'95 min', N'Sterling Brooks, a self-absorbed stock broker, is killed in a freak golfing accident. In order to secure a heavenly future, Sterling is given the opportunity to help a needy young girl reunite with her family in time for Christmas. An unusual Christmas mystery with a heartwarming finale.'),
(1728, N's1728', N'TV_SHOW', N'Martha Speaks', NULL, 2010, N'TV-G', 1, N'SEASONS', N'1 Season', N'Learn new words with Martha and her friends!'),
(1729, N's1729', N'MOVIE', N'Marshall''s Miracle', NULL, 2015, NULL, 90, N'MINUTES', N'90 min', N'When Finn first finds Marshall, he is held in deplorable conditions by an animal hoarder on an isolated ranch. The boy sees something of himself in Marshall: Both are bullied, but both are brave. Finn takes the dog home, but when Marshall spooks and runs away, it takes Finn, his family, and a bully-turned-friend to find him before it''s too late.'),
(1730, N's1730', N'MOVIE', N'Married by Christmas', NULL, 2016, N'13+', 86, N'MINUTES', N'86 min', N'A high level executive must find herself a husband before Christmas in order to inherit a fortune. Stars Jes Macallan, April Bowlby and Coby Ryan McLaughlin.'),
(1731, N's1731', N'TV_SHOW', N'Married at First Sight', NULL, 2016, N'TV-14', 3, N'SEASONS', N'3 Seasons', N'The daring social experiment, Married at First Sight, returns for Season 3 where six singles from the Atlanta, Georgia area will marry a complete stranger.'),
(1732, N's1732', N'TV_SHOW', N'Married At First Sight', NULL, 2014, N'TV-14', 1, N'SEASONS', N'1 Season', N'Who can forget falling in love, especially the first time and then losing touch? From the high school sweetheart who moved away, to the holiday romance that fizzled because of lost phone numbers, the emotional treasure hunts produce conclusions both heart-warming and heart-wrenching.'),
(1733, N's1733', N'MOVIE', N'Marriage Counseling Films', NULL, 2018, N'13+', 113, N'MINUTES', N'113 min', N'A collection of historical films documenting the issues of the problems in marriage.'),
(1734, N's1734', N'MOVIE', N'Maritime', NULL, 2007, N'NR', 33, N'MINUTES', N'33 min', N'The Promise Ring + the Dismemberment Plan = Pop music from the indie supergroup, Maritime.'),
(1735, N's1735', N'MOVIE', N'Mario And Fafa''s Wacky Lessons', NULL, 2019, N'ALL', 18, N'MINUTES', N'18 min', N'Glove and Boots is a puppet-based video blog. The two main characters are a red, bearded humanoid named Mario , and an anthropomorphic groundhog named Fafa. In this compilation of Glove and Boots, enjoy a Mario and Fafa''s interesting and comical sketches about beards, grandmas, and many more!'),
(1736, N's1736', N'MOVIE', N'Mario', NULL, 2018, N'18+', 124, N'MINUTES', N'124 min', N'There''s a ripple of disquiet in the locker-room when Leon, a new striker, joins the soccer team. Sharing a flat with keen rival Mario sets the scene for an unexpected love affair, but the path of gay love in this macho world is not an easy one. Mario is unwilling or unable to acknowledge the implications of what is happening. But pretend girlfriends don''t fool everyone.'),
(1737, N's1737', N'TV_SHOW', N'Marine Recon', NULL, 2005, N'13+', 1, N'SEASONS', N'1 Season', N'This is the real war in Iraq with real soldiers and real terrorists. And real footage so intense you''ll forget you''re not really there. Experience the fears, frustrations and raw emotions of real soldiers in this 4-part documentary.'),
(1738, N's1738', N'MOVIE', N'Marilyn Hotchkiss'' Ballroom Dancing & Charm School', NULL, 2006, N'PG-13', 104, N'MINUTES', N'104 min', N'Frank, a baker by trade, has been consumed by grief over his wife''s death. But everything changes when he pulls his bread truck over on a rural highway to help a dying stranger entangled in a car wreck. A heartfelt, nostalgic and gently humorous story about a chance encounter in which one man''s dreams become another man''s destiny.'),
(1739, N's1739', N'MOVIE', N'Maria Bamford: Weakness is the Brand', NULL, 2020, N'18+', 75, N'MINUTES', N'75 min', N'Maria Bamford is back and subjectively better than ever! Weakness is her brand, so get ready to feel much better about yourself. This Lady Dynamite explodes onstage (after 2 (two) naps with her husband Scott and 2 old, pillowy dogs). Let her be the poor example from which your greatness can be determined.'),
(1740, N's1740', N'MOVIE', N'Maria Bamford: The Special Special Special', NULL, 2014, N'18+', 50, N'MINUTES', N'50 min', N'Maria Bamford: The Special Special Special'),
(1741, N's1741', N'MOVIE', N'Margaret Cho: Psycho', NULL, 2015, N'18+', 82, N'MINUTES', N'82 min', N'Comedian Margaret Cho performs in front of a live audience in this provocative and hilarious comedy special event, tackling off-limits issues from Boko Haram to female empowerment with her razor sharp insight and wit.'),
(1742, N's1742', N'TV_SHOW', N'Marcia Clark Investigates The First 48', NULL, 2018, N'TV-14', 1, N'SEASONS', N'1 Season', N'Marcia Clark Investigates The First 48 delves into some of America''s most shocking crimes as prosecutor and defense attorney Marcia Clark sifts through evidence presented in the case files.'),
(1743, N's1743', N'MOVIE', N'Mao''s Last Dancer', NULL, 2010, N'PG', 118, N'MINUTES', N'118 min', N'"Mao''s Last Dancer" is the inspiring true story of Li Cunxin and his extraordinary journey from a poor upbringing in rural China to international stardom as a world-class ballet dancer. It compellingly captures the struggles, sacrifices and triumphs, as well as the intoxicating effects of first love and celebrity amid the pain of exile.'),
(1744, N's1744', N'TV_SHOW', N'Manson Speaks: Inside the Mind of a Madman', NULL, 2017, N'TV-14', 1, N'SEASONS', N'1 Season', N'Detective Cliff Shepard isn''t convinced that the Manson case is truly closed as over the years, other murders have surfaced that bear a striking resemblance to the Manson Family''s methods and targets.'),
(1745, N's1745', N'TV_SHOW', N'Mankind The Story of All of Us', NULL, 2016, N'13+', 1, N'SEASONS', N'1 Season', N'Inside all of us, there is a story to be discovered, simmering age-old questions to be answered - who we are, how did we get here and what came before. From the black hole to the creation of our planet billions of years ago to the emergence of humans, Mankind The Story of All of Us dives through the surface of our universe reaching the core of our existence textbooks never dare reveal.'),
(1746, N's1746', N'MOVIE', N'Manhattan Undying', NULL, 2017, N'16+', 88, N'MINUTES', N'88 min', N'A vampire seeks out an artist to paint her a portrait so that she can see her image for the first time.'),
(1747, N's1747', N'MOVIE', N'Mane Number 13', NULL, 2020, N'16+', 106, N'MINUTES', N'106 min', N'5 IT professionals staying together vacate their house due to a situation. They move into a new house were they start facing horrific incidents at night. It terrifies them to death. When they are about to find out what''s happening, they are getting killed one after another. Now they have to find out if it''s really haunted or someone planning the terror.'),
(1748, N's1748', N'MOVIE', N'Mandingo', NULL, 1975, N'R', 127, N'MINUTES', N'127 min', N'Based on the novel by Kyle Onstott, Mandingo takes the audience beyond the sentimentalized South of other films with uncompromising honesty and realism to show the true brutalizing nature of slavery, which made victims of both owner and slave.'),
(1749, N's1749', N'TV_SHOW', N'Man''s World', NULL, 2015, N'16+', 1, N'SEASONS', N'1 Season', N'What if women treated men, the way men treat women? It is a story about walking a mile in their shoes, in that world. Kiran, the protagonist, believes the world is really unfair to men. Fed up, he prays for the world to flip and for men and women to interchange places. As they say, be careful what you wish for.'),
(1750, N's1750', N'MOVIE', N'Man With The Golden Arm', NULL, 1955, N'PG-13', 120, N'MINUTES', N'120 min', N'A powerful story of a drug addict who''s trying to leave his poker-dealing past behind after he returns home from prison.'),
(1751, N's1751', N'MOVIE', N'Man Vs.', NULL, 2017, N'13+', 85, N'MINUTES', N'85 min', N'When TV host Doug Woods is dropped off in the Canadian wilderness, he''s confident he has all the skills necessary to survive the week alone. But when strange things start happening in the forest, Doug realizes he''s not the only one out there.'),
(1752, N's1752', N'MOVIE', N'Man In The Attic', NULL, 1954, N'PG-13', 82, N'MINUTES', N'82 min', N'In 1888 the people of London are terrified by a series of murders on the fog-shrouded streets, with the only connection being that all the victims were women and showgirls. Around this time, mild-mannered and secretive pathologist Mr. Slade (Palance) rents an attic apartment in the heart of London. Mr. Slade falls in love with dancer Lily Bonnery (Smith), who does not return his affections. As the police search frantically for "Jack the Ripper," Mr. Slade comes under suspicion for the murders.'),
(1753, N's1753', N'MOVIE', N'Man From Texas (1948)', NULL, 1948, N'PG', 70, N'MINUTES', N'70 min', N'James Craig is torn between his criminal career as the masked bandit named the "El Paso Kid," and the life of a law-abiding citizen with his long-suffering wife Zoe (Bari). Throughout the film, he tells his worried wife "just one more time," but is unable to stop, angering Zoe greatly. However, he does have brief moments of heroics when eh helps the Widoe Weeks *Merkel) save her farm. This was Eagle-Lion Studios first "big budget" film.'),
(1754, N's1754', N'MOVIE', N'Man From Elysian Fields', NULL, 2001, N'R', 106, N'MINUTES', N'106 min', N'After Byron Tiller (Andy Garcia) fails as a novelist, Luther Fox (Mick Jagger) offers him to join his escort agency named Elysian Fields, which caters to rich women looking for intelligent companionship. Desperate for any kind of income source, Byron takes the job while keeping the whole thing a secret from his loving wife (Julianna Margulies).'),
(1755, N's1755', N'MOVIE', N'Mambo Italiano', NULL, 2003, N'R', 89, N'MINUTES', N'89 min', N'Angelo Barberini is the oddball son of Italian immigrants Gino and Maria, who inadvertently ended up in Canada rather than the United States. Angelo shocks his parents - and his sister, Anna - by moving out on his own without getting married, and, shortly after that, shocks them further still when he reveals he is gay.'),
(1756, N's1756', N'TV_SHOW', N'Making Their Mark', NULL, 2021, N'16+', 1, N'SEASONS', N'1 Season', N'Making Their Mark is an unprecedented journey into the inner sanctum of Australia''s greatest sport in the most challenging year in its history. Players, coaches, and executives across six teams in the Australian Football League navigate a year like no other in an exhilarating portrait of elite sport.'),
(1757, N's1757', N'MOVIE', N'Making of Michael Jordan''s Playground', NULL, 1997, N'7+', 24, N'MINUTES', N'24 min', N'A behind-the-scenes look at the making of the NBA production, Michael Jordan''s Playground.'),
(1758, N's1758', N'MOVIE', N'Making a Killing', NULL, 2018, N'13+', 107, N'MINUTES', N'107 min', N'Three morticians get caught in a web of greed and deceit, involving buried treasure and a tangled love affair, in this modern day crime mystery that is based on a true story.'),
(1759, N's1759', N'MOVIE', N'Make Us Dream', NULL, 2020, N'16+', 104, N'MINUTES', N'104 min', N'Steven Gerrard became perhaps the greatest player in the history of Liverpool FC, but did so when success and trophies were declining. It became his personal mission to lift the famous club back to the top. That loyalty raised him to God-like status with Liverpool fans, but was an unbearable burden, bringing with it a profound sense of responsibility to live up to their and his own expectations.'),
(1760, N's1760', N'MOVIE', N'Make Believe', NULL, 2011, N'NR', 36, N'MINUTES', N'36 min', N'Make Believe, the musicians behind Joan of Arc, challenge their audience with rhythmic, off-kilter rock.'),
(1761, N's1761', N'MOVIE', N'Make A Wish', NULL, 1937, N'PG', 82, N'MINUTES', N'82 min', N'Chip Winters (Breen) and his buddy Pee Wee (Lee) are at a summer boys camp in Main. Chip befriends famous composer Johnny Selden (Rathboth), who is suffering from writers block. He becomes inspired by Chip''s single mother Irene (Claire), who is an accomplished retired singer. Johnny soon invites Irene to perform his newest masterpiece. However, Irene''s controlling fiancee Walter (Forbes), will not allow it. It''s up to Chip, Pee Wee, and a bevy of funny friends to play matchmaker, getting Walter out of the picture for good, and Johnny and Irene together. Singing child actors Bobby Breen and Billy Lee raise the movie up to an unusally heart-warming and low budget musical. Nominated in 1938 for an Academy Award for Best Music and Score.'),
(1762, N's1762', N'MOVIE', N'Majili', NULL, 2019, N'13+', 151, N'MINUTES', N'151 min', N'A former cricket player nursing his wounds of a failed relationship takes up the task of training his ex-lover''s daughter and in the process discovers his feelings towards his wife and her unrequited love for him.'),
(1763, N's1763', N'MOVIE', N'Maidentrip', NULL, 2014, N'ALL', 81, N'MINUTES', N'81 min', N'This riveting documentary chronicles the life and adventures of 14-year-old Laura Dekker, who set out on a two-year voyage in pursuit of her dream to be the youngest person ever to sail around the world alone. In the wake of a yearlong battle with Dutch authorities that sparked a global storm of media scrutiny, Laura explores the world in search of freedom and adventure.'),
(1764, N's1764', N'MOVIE', N'Mahanati (Telugu)', NULL, 2018, N'7+', 171, N'MINUTES', N'171 min', N'Mahanati is a film about the rise of the first female south Indian superstar - Savitri. Her story one of the most heart wrenching romantic tragedies of our times.This film tells a story of the Mahanati; her life, her journey to fame, and the dramatic downfall. Keerthy Suresh, elegantly brought Savitri to life, and Gemini Ganesan, played by Dulquer Salman, makes this film a true pleasure to watch.'),
(1765, N's1765', N'MOVIE', N'Magical Playtime with Mila and Morphle', NULL, 2019, N'ALL', 49, N'MINUTES', N'49 min', N'Come join Mila and her magic pet Morphle as they go on an Easter egg hunt, play with their friends, and look for the missing animals from the zoo!'),
(1766, N's1766', N'TV_SHOW', N'MAGICAL GIRL SITE', NULL, 2018, N'NR', 1, N'SEASONS', N'1 Season', N'It seems only the unfortunate can stumble across this site.That is why they were chosen.Without any place to call her own, Aya only thinks about dying.Bullied at school and abused by her own brother at home.'),
(1767, N's1767', N'TV_SHOW', N'MAGI  The Tensho Boys’ Embassy (4K UHD) (Japanese Ver)', NULL, 2019, N'TV-NR', 1, N'SEASONS', N'1 Season', N'In the 1500s, the Tensho Boys’ Embassy was the first to cross from Japan to Europe and meet with the Pope. A historical tale by one of Japan’s top screenwriters, Toshio Kamata, and famed director, Shunichi Nagasaki, MAGI depicts the lives of these boys as they make their perilous journey, cross paths with historical figures, enter manhood, and, finally, become buried in the sands of time.'),
(1768, N's1768', N'TV_SHOW', N'MAGI  The Tensho Boys’ Embassy (4K UHD)', NULL, 2019, N'TV-NR', 1, N'SEASONS', N'1 Season', N'In the 1500s, the Tensho Boys’ Embassy was the first to cross from Japan to Europe and meet with the Pope. A historical tale by one of Japan’s top screenwriters, Toshio Kamata, and famed director, Shunichi Nagasaki, MAGI depicts the lives of these boys as they make their perilous journey, cross paths with historical figures, enter manhood, and, finally, become buried in the sands of time.'),
(1769, N's1769', N'TV_SHOW', N'MAGI  The Tensho Boys’ Embassy  (Japanese Ver)', NULL, 2019, N'TV-NR', 1, N'SEASONS', N'1 Season', N'In the 1500s, the Tensho Boys’ Embassy was the first to cross from Japan to Europe and meet with the Pope. A historical tale by one of Japan’s top screenwriters, Toshio Kamata, and famed director, Shunichi Nagasaki, MAGI depicts the lives of these boys as they make their perilous journey, cross paths with historical figures, enter manhood, and, finally, become buried in the sands of time.'),
(1770, N's1770', N'TV_SHOW', N'MAGI  The Tensho Boys’ Embassy', NULL, 2019, N'TV-NR', 1, N'SEASONS', N'1 Season', N'In the 1500s, the Tensho Boys’ Embassy was the first to cross from Japan to Europe and meet with the Pope. A historical tale by one of Japan’s top screenwriters, Toshio Kamata, and famed director, Shunichi Nagasaki, MAGI depicts the lives of these boys as they make their perilous journey, cross paths with historical figures, enter manhood, and, finally, become buried in the sands of time.'),
(1771, N's1771', N'MOVIE', N'Maggie''s War', NULL, 2013, N'13+', 57, N'MINUTES', N'57 min', N'James Megellas, affectionately known as "Maggie," led H-Company of the 504th Parachute Infantry Regiment through some of the most horrific battles and deadliest missions of World War II. MAGGIE''S WAR chronicles the evolution of a citizen into a fearless platoon leader, and the transformation of a young man into the most highly decorated officer in the history of the famed 82nd Airborne Division.'),
(1772, N's1772', N'TV_SHOW', N'Maggie Binkley Fitness SERIES 10.0 (15-Minute Workouts)', NULL, 2020, N'ALL', 1, N'SEASONS', N'1 Season', N'Maggie created 15-minute workouts to be sure you have no-excuses, do-anywhere workouts at your fingertips that will leave you feeling awesome! Series 10.0 includes the use of weights, and a weekly workout schedule that promises to challenge & leave you feeling accomplished – in just 15 minutes!'),
(1773, N's1773', N'MOVIE', N'Mafia: Chapter 1', NULL, 2020, N'13+', 111, N'MINUTES', N'111 min', N'Aryan is a narcotics bureau officer entitled with making the city a drug free zone. Inspite of huge number of drug busts & capturing of peddlers, Aryan & his team are not able to completely eradicate the alarming problem. One dreadful day, people very close to Aryan get murdered one by one.He feels that this might be the work of the mastermind who is behind the entire distribution network.'),
(1774, N's1774', N'MOVIE', N'Made in Mexico (Spanish Language, No Subtitles)', NULL, 2011, N'NR', 21, N'MINUTES', N'21 min', N'Made in Mexico is experimental hard rock from some punky, well-dressed co-eds.'),
(1775, N's1775', N'TV_SHOW', N'Made In Heaven', NULL, 2019, N'16+', 1, N'SEASONS', N'1 Season', N'Made In Heaven chronicles the lives of Tara and Karan, two wedding planners in Delhi. India is a potent blend of old and new. Tradition jostles with modern aspirations against the backdrop of big fat Indian weddings revealing many secrets and many lies. The supposedly liberal fabric of the upper crust unravels as the duo navigate through arranged marriages, dowry transactions and virginity tests.'),
(1776, N's1776', N'TV_SHOW', N'MADE IN ABYSS', NULL, 2017, N'TV-14', 1, N'SEASONS', N'1 Season', N'Within the depths of the Abyss, a girl named Riko stumbles upon a robot who looks like a young boy. Riko and her new friend descend into uncharted territory to unlock its mysteries, but what lies in wait for them in the darkness?'),
(1777, N's1777', N'MOVIE', N'Madame Behave', NULL, 1925, N'NR', 55, N'MINUTES', N'55 min', N'To help a friend in a lawsuit, Jack Mitchell disguises himself as the "Madame Brown," a missing witness important to the case of the plaintiff. He attracts the romantic attention of two old roues and one hot Broadway showgirl.'),
(1778, N's1778', N'MOVIE', N'Madame', NULL, 2018, NULL, 92, N'MINUTES', N'92 min', N'Anne and Bob, a well-to-do American couple, have just moved to a beautiful manor house in romantic Paris. To impress their sophisticated friends, they decide to host a lavish dinner party, but must disguise their maid as a noblewoman to even out the number of guests. When the maid runs off with a wealthy guest, Anne must chase her around Paris to thwart the joyous and unexpected love affair'),
(1779, N's1779', N'MOVIE', N'Mad To The Max: Hoon Nation', NULL, 2018, N'NR', 87, N'MINUTES', N'87 min', N'With a blend of ''reality Mad Max'' and the seamy underbelly of suburbia, Hoon Capital is a definitive study of Hoons and takes you on a journey into a subculture vilified by the popular media.'),
(1780, N's1780', N'MOVIE', N'Mad to be Normal', NULL, 2017, N'16+', 105, N'MINUTES', N'105 min', N'During the 1960s, a renegade Scottish psychiatrist (David Tennant) courts controversy within his profession for his approach to the field, and for the unique community he creates for his patients to inhabit.'),
(1781, N's1781', N'TV_SHOW', N'Mad Dogs', NULL, 2016, N'18+', 1, N'SEASONS', N'1 Season', N'When a group of underachieving 40-something friends gather in Belize to celebrate the early retirement of an old friend, a series of wild events unfold, exposing dark secrets, deception and even murder.'),
(1782, N's1782', N'TV_SHOW', N'Mad About You', NULL, 2019, N'TV-PG', 1, N'SEASONS', N'1 Season', N'A revival of the 1990s sitcom, Mad About You centers on the trials and tribulations of a married couple living in New York.'),
(1783, N's1783', N'MOVIE', N'Maayavan', NULL, 2017, N'13+', 126, N'MINUTES', N'126 min', N'Sundeep Kishan plays a police officer, who is severely injured while trapping a murderer. Couple of months after recovery, he resumes his job and during the process of investigating the murder of an actress (Akshara Gowda) comes across similarities in pattern of this murder with the previous ones. This takes him through few more characters, who are in some way connected with these murders.'),
(1784, N's1784', N'MOVIE', N'Luv Ka The End', NULL, 2011, N'18+', 107, N'MINUTES', N'107 min', N'This is a young anti rom com kind of movie focussing on, Rhea Dialdas and Luv Nanda. On the eve of her 18th birthday, they plan to take their relationship to the ''next level'', but she accidentally finds out that Luv is not really the nice guy she thought he was. Humiliated and hurt, she decides to teach him a few kick-ass lessons he will never forget and sets out to do so with her friends.'),
(1785, N's1785', N'MOVIE', N'Lusitania', NULL, 2007, N'16+', 91, N'MINUTES', N'91 min', N'The sinking of the Lusitania, one of the world''s great ocean liners, was a shocking event, which reverberated around the world. It provoked outrage on an unprecedented scale. This single act seemed, in one brutal, unforgettable moment, to change the face of war forever.'),
(1786, N's1786', N'MOVIE', N'Luke and Lucy and the Texas Ranger', NULL, 2011, N'ALL', 93, N'MINUTES', N'93 min', N'Saddle up your horses and join sibling duo, Luke and Lucy as they unravel the mysterious shrinking of the world''s population. With the help of their family and friends these unlikely heroes ride off to the Wild West on an adventure of a lifetime to save the world.'),
(1787, N's1787', N'TV_SHOW', N'Luis, el sabio del éxito', NULL, 2018, N'TV-NR', 1, N'SEASONS', N'1 Season', N'"Luis, el sabio del éxito" reviews, with unpublished footage, the triumph of Spain in the UEFA Euro 2008, with Luis Aragonés as key protagonist.'),
(1788, N's1788', N'MOVIE', N'Lucy and Desi: A Home Movie', NULL, 1993, N'13+', 109, N'MINUTES', N'109 min', N'Desi Arnaz and Lucille Ball''s daughter, Lucie Arnaz, directed and produced this emotional yet honest glimpse at the extraordinary lives of her world-famous parents, highlighted by never-before-seen color family movies along with insightful interviews from family members, business associates and celebrity friends such as Bob Hope. Winner of the Emmy Award for Outstanding Informational Special.'),
(1789, N's1789', N'MOVIE', N'Lucky Texan', NULL, 1934, N'13+', 56, N'MINUTES', N'56 min', N'Two miners discover a streak of gold, but bad guys attempt to murder one and pin the crime on the other - the victim recovers and sets up a surprise.'),
(1790, N's1790', N'MOVIE', N'Lucifer (Telugu)', NULL, 2019, N'13+', 172, N'MINUTES', N'172 min', N'A political Godfather, who ruled the God''s Own Country, dies and a lot of thieves dressed up as politicians took over the rule. When question arises on the replacement of the ''God'', just one name emerges; ''Stephen Nedumbally''.'),
(1791, N's1791', N'MOVIE', N'Lucifer (Tamil)', NULL, 2019, N'13+', 173, N'MINUTES', N'173 min', N'A political Godfather, who ruled the God''s Own Country, dies and a lot of thieves dressed up as politicians took over the rule. When question arises on the replacement of the ''God'', just one name emerges; ''Stephen Nedumbally''.'),
(1792, N's1792', N'MOVIE', N'Lucifer (Malayalam)', NULL, 2019, N'13+', 172, N'MINUTES', N'172 min', N'A political Godfather, who ruled the God''s Own Country, dies and a lot of thieves dressed up as politicians took over the rule. When question arises on the replacement of the ''God'', just one name emerges; ''Stephen Nedumbally''.'),
(1793, N's1793', N'MOVIE', N'Loyalty And Respect', NULL, 2006, N'18+', 83, N'MINUTES', N'83 min', N'Supreme (C.E.O.) is a drug dealer whose life couldn''t be better. He has it all. The streets of Cashville have given him everything a he could ask for. Driven by jealousy, his best friend Notorius (Quanie Cash) decides to go after his empire. In doing so, Notorius launches an all out street war. No one is to be trusted because in this city LOYALTY & RESPECT is lost over cash.'),
(1794, N's1794', N'MOVIE', N'Low Tide (4K UHD)', NULL, 2019, N'R', 86, N'MINUTES', N'86 min', N'After Alan & his younger brother find a bag of gold in a dead man''s home, an envious friend is willing to do anything to get the money.'),
(1795, N's1795', N'MOVIE', N'Loveyatri - The Journey of Love', NULL, 2018, N'13+', 133, N'MINUTES', N'133 min', N'Loveyatri is a contemporary love story of Sushrut and Michelle, which revolves around the festival of Navratri. Sushrut and Michelle’s blossoming relationship hits a deadlock and she travels back to UK. Sushrut travels to the UK, to win back his love. it is a musical roller coaster ride of friendship, family, love and relationships culminating with a lot of colour, lights and festivities.'),
(1796, N's1796', N'MOVIE', N'Love''s Kitchen', NULL, 2020, N'PG-13', 90, N'MINUTES', N'90 min', N'After a poor review from a critic and a chat from chef Gordon Ramsay, a talented but grief stricken London chef turns a country pub into a gourmet eatery. His dessert trifle catches the eye - and taste - of Kate, and they soon discover that the recipe for true happiness is a pinch of teamwork and a whole lot of love.'),
(1797, N's1797', N'MOVIE', N'Love, Kennedy', NULL, 2017, N'PG', 92, N'MINUTES', N'92 min', N'Kennedy Hansen is a 15 year old girl with three goals, drive a car, date boys and be a cheerleader. Even though she contracts a terrible disease, Kennedy is able to triump over her obstacles and make her dreams come true.'),
(1798, N's1798', N'MOVIE', N'Love, Hope & Autism', NULL, 2018, NULL, 44, N'MINUTES', N'44 min', N'LOVE, HOPE & AUTISM takes viewers behind the startling statistics on the rise of autism in North America, and deep into the heart and history of a family raising a son with Autism Spectrum Disorder (ASD). 21 years of home movie footage chronicles the powerful effects of ASD, from the strain on the marriage to the inevitable shift in family dynamics.'),
(1799, N's1799', N'MOVIE', N'Love The One You''re With', NULL, 2021, N'18+', 61, N'MINUTES', N'61 min', N'A dramatic comedy that follows a couple, Miles and Avery as they navigate the possible ending of a long term relationship, and a story that explores the issues that black queer men face in modern dating and relationships.'),
(1800, N's1800', N'MOVIE', N'Love Simple', NULL, 2011, N'16+', 86, N'MINUTES', N'86 min', N'Adam and Seta fall madly in love after meeting in a Brooklyn laundromat. She suffers from Lupus. He''s stuck at home caring for his chronically ill father. Both lie through their teeth to avoid having to reveal they are anything but perfect.');


What are the impacts of social networking? Have we evolved to live in this connected-yet-closed world? Or has it set us back?
We''re living in an entangled world.
A world centered around girls.
Invisible TOKYO.'),
(2090, N's2090', N'MOVIE', N'Invisible Life', NULL, 2019, N'R', 140, N'MINUTES', N'140 min', N'Set in 1950s Rio de Janeiro, the film revolves around two sisters, living restricted lives with their conservative parents. However, each nourishes a passionate dream: Eurídice of becoming a renowned pianist; Guida of finding love. In a dramatic turn of events, they are separated and forced to live apart. They take control of their destinies, while never giving up hope of finding one another.'),
(2091, N's2091', N'TV_SHOW', N'Invincible', NULL, 2021, N'TV-MA', 1, N'SEASONS', N'1 Season', N'INVINCIBLE is an adult animated superhero series that revolves around 17-year-old Mark Grayson, who’s just like every other guy his age – except his father is the most powerful superhero on the planet, Omni-Man. But as Mark develops powers of his own, he discovers his father’s legacy may not be as heroic as it seems.'),
(2092, N's2092', N'TV_SHOW', N'Inventions that Shook the World', NULL, 2012, N'ALL', 1, N'SEASONS', N'1 Season', N'Go on a decade-by-decade voyage of discovery through life-changing inventions, like the radio that made the world smaller, the machine gun that made it more dangerous, or the parking meter that made it more expensive. Witness the discovery and creation of billion-dollar inventions and financial disasters - all players in the most innovative century the world has ever known.'),
(2093, N's2093', N'MOVIE', N'Invasion of the Body Snatchers', NULL, 1956, N'PG', 80, N'MINUTES', N'80 min', N'A small-town doctor learns that the population of his community is being replaced by emotionless alien duplicates.'),
(2094, N's2094', N'MOVIE', N'Intersexion: Finding a Place in a Two-Gender World', NULL, 2012, N'13+', 53, N'MINUTES', N'53 min', N'The first question any new parent asks: "Is it a boy or a girl?" What if it''s neither? One in 2,000 babies is born with genitalia so ambiguous that the doctors cannot easily answer this question. In this groundbreaking documentary, intersex individuals reveal the secrets of their unconventional lives. How do they cope with relationships, with popular perceptions, and the inevitable discrimination?'),
(2095, N's2095', N'MOVIE', N'Interpreters', NULL, 2020, N'16+', 120, N'MINUTES', N'120 min', N'An unusual perpetrator using advanced technology murders the inhabitants of Sullen Community. When a former black operator and CID Agent investigates with the local police force they uncover a darker and more dangerous threat than anyone anticipated.'),
(2096, N's2096', N'MOVIE', N'Instant Death', NULL, 2017, N'18+', 84, N'MINUTES', N'84 min', N'A gang war for drug dominance draws in a disturbed Special Forces veteran John Bradley. The underworld''s retribution on his last connection to humanity, a daughter and grandchild leads to a descent of fury and violence.'),
(2097, N's2097', N'TV_SHOW', N'Inspector Manara (English Subtitled)', N'2021-03-30', 2011, N'TV-NR', 2, N'SEASONS', N'2 Seasons', N'In Italian with English subtitles. In season 2, Inspector Manara learns to work without his colleague Lara, who is sent off for intelligence training. She''s replaced by Inspector Marta Rivera, who hides a mystery Manara can''t get a handle on.'),
(2098, N's2098', N'MOVIE', N'Inside the Law', NULL, 1950, N'PG', 61, N'MINUTES', N'61 min', N'In this crime comedy, a small gang of old crooks, led by the elderly Pop (McKee) and Mom Cobb (Pulmmer), find an appointment as a cashier in the Walnut Park bank in a drunk''s wallet. They decide to place one of their members in the cashier''s position, with the intention of escaping with the bank''s receipts at the end of the week. While staying in town, the remaining gang members must establish themselves as respectable people, ending up attending church services, where they all decide to go straight. But gang members decides to go through with the theft, and it is up to the reformed gang members to catch him and return the money, becoming the town''s heroes. They all happily decide they want to stay in the town permanently.'),
(2099, N's2099', N'TV_SHOW', N'Inside Men', NULL, 2012, N'TV-14', 1, N'SEASONS', N'1 Season', N'John Coniston is the scrupulous manager of a cash counting house. When he confronts two employees over missing money, they expect John to call the police, but John is about to offer them another option. Together these disillusioned men plan the perfect heist. But these are no seasoned criminals, just four ordinary men. Can they cope with the pressures of a big-time job?'),
(2100, N's2100', N'MOVIE', N'Inside Llewyn Davis', NULL, 2013, N'R', 105, N'MINUTES', N'105 min', N'An aspiring singer-songwriter navigates the 1960s folk-music scene in New York City''s Greenwich Village.'),
(2101, N's2101', N'TV_SHOW', N'Inside Jokes', NULL, 2018, N'16+', 1, N'SEASONS', N'1 Season', N'“Inside Jokes” follows unknown stand-up comics vying to make it into the world-famous Just for Laughs comedy festival in Montreal. Will their performances launch their careers into superstardom, just like New Faces alumni Pete Holmes and Colin Jost, or will they choke under pressure? For this group of comics, who have sacrificed much in pursuit of a dream, there is no bigger moment.'),
(2102, N's2102', N'MOVIE', N'Inside Italy''s COVID War', NULL, 2020, NULL, 53, N'MINUTES', N'53 min', N'Inside a hospital battling COVID-19 in Northern Italy, as doctors make life and death decisions.The intimate, exclusive story of one besieged ER doctor, her staff and patients, from the darkest days to the signs of hope.'),
(2103, N's2103', N'TV_SHOW', N'Inside Edge', NULL, 2019, N'18+', 2, N'SEASONS', N'2 Seasons', N'In the next edition of the PPL, a volatile Vayu Raghavan leads the Mumbai Mavericks to face their biggest adversary yet, the Arvind Vashisht-led Haryana Hurricanes. But they must also counter colossal scandals that’ll rock the world of cricket. In the sport’s upper echelons, Zarina Malik allies with Bhaisaab, but those in the shadows threaten to destroy the very game they seek to control.'),
(2104, N's2104', N'TV_SHOW', N'Inside Borussia Dortmund', NULL, 2019, N'TV-PG', 1, N'SEASONS', N'1 Season', N'[New episode weekly] You have never been this close to Borussia Dortmund. In this 4-part docu-series, go behind-the-scenes with one of the Bundesliga’s biggest clubs and re-live the thrilling 2018/19 football season from the team’s point of view. Discover their training facilities, experience the locker room drama first-hand, and become acquainted with the players’ personal lives.'),
(2105, N's2105', N'TV_SHOW', N'Insectibles', NULL, 2016, N'TV-Y', 1, N'SEASONS', N'1 Season', N'Insectibles follows the adventures of a young boy named Zak, his inventor Grandfather and 3 mechanically enhanced insects as they embark on an epic search to find pieces of the broken Shrinkinator while evading their enemies!'),
(2106, N's2106', N'MOVIE', N'Insane', NULL, 2016, N'18+', 13, N'MINUTES', N'13 min', N'Every fact has consequences. Consequences generate new facts, and in this inflexible chain, is where we are. The consequences of violence become uncontrollable.'),
(2107, N's2107', N'TV_SHOW', N'Injustice', NULL, 2011, N'TV-14', 1, N'SEASONS', N'1 Season', N'James Purefoy stars in this thrilling miniseries about a defense barrister who is called upon to defend an old friend in a homicide case that may be more than it seems.'),
(2108, N's2108', N'TV_SHOW', N'Informer', NULL, 2019, N'18+', 1, N'SEASONS', N'1 Season', N'Informer is a thriller about Raza, a young second-generation British-Pakistani man from London who is coerced by Gabe, a Counter-Terrorism officer into informing.'),
(2109, N's2109', N'MOVIE', N'Infinity Chamber', NULL, 2017, N'13+', 103, N'MINUTES', N'103 min', N'A man trapped in an automated prison must outsmart a computer in order to escape and try and find his way back to the outside world that may already be destroyed.'),
(2110, N's2110', N'MOVIE', N'INFIDELITY', NULL, 2020, N'18+', 107, N'MINUTES', N'107 min', N'Two sisters with a dark past who grew up hating each other on the low get entangled in a web a lies, adultery and murder. With Tracy, the older sister of Lena being traumatized by her childhood decides to take her feelings out on her little sister Lena which causes them both to go at each other in a way to make you look at ANY sister sideways. Some Things You Just Don''t Do!'),
(2111, N's2111', N'MOVIE', N'Indian Title', NULL, 2019, N'ALL', 10, N'MINUTES', N'10 min', N'This is the synopsis for my Indian title. It describes what will happen in the movie and entices the viewer to watch the show.'),
(2112, N's2112', N'MOVIE', N'Indian Comedy Tour', NULL, 2010, N'18+', 63, N'MINUTES', N'63 min', N'A hilarious night of comedy with five of the funniest Indian stand-up comedians! Blowing aside political correctness, these talented Indian comics break down stereotypes as they cover politics, racism, dating, childhood and pop-culture.'),
(2113, N's2113', N'MOVIE', N'Inconceivable', NULL, 2017, N'R', 106, N'MINUTES', N'106 min', N'Starring Nicolas Cage, Gina Gershon, Nicky Whelan, and Faye Dunaway, this dark thriller depicts a wealthy couple that shelters a young runaway mother, dangerously unaware of the woman''s dark past.'),
(2114, N's2114', N'MOVIE', N'Incident At Oglala: The Leonard Peltier Story', NULL, 1992, N'PG', 91, N'MINUTES', N'91 min', N'This acclaimed documentary examines Native American activist Leonard Peltier''s questionable conviction for murder.'),
(2115, N's2115', N'MOVIE', N'In The Name Of Ben-Hur', NULL, 2016, N'13+', 89, N'MINUTES', N'89 min', N'A young gladiator enslaved in the Roman arena in 171 A.D. escapes by chariot towards the freedom of Hadrian''s Wall. Fighting centurions and mercenaries along the way, he becomes a folk hero for all those struggling to fight Roman oppression.'),
(2116, N's2116', N'MOVIE', N'In the Money (1933)', NULL, 1933, N'13+', 65, N'MINUTES', N'65 min', N'A zany family of ner-do-wells are faced with financial ruin after purchasing worthless stock in this screwball comedy. They are saved by the skills of a goofy boxer who has been punched in the head one too many times. Very entertaining screwball comedy.'),
(2117, N's2117', N'MOVIE', N'In Search of Mozart', NULL, 2016, N'7+', 129, N'MINUTES', N'129 min', N'From an incredibly young age, Wolfgang Amadeus Mozart was able to compose and perform the most complex and marvelous pieces in history. This is his story of love and hardship, and his unique, unparalleled genius.'),
(2118, N's2118', N'MOVIE', N'In Search of Fellini', NULL, 2017, N'R', 104, N'MINUTES', N'104 min', N'Based on a true adventure by Nancy Cartwright, ''In Search of Fellini'' follows Lucy, a young girl from Ohio, who discovers the delightfully odd films of Federico Fellini and sets off on a journey across Italy to find him.'),
(2119, N's2119', N'TV_SHOW', N'In Search of Aliens', NULL, 2014, N'TV-PG', 1, N'SEASONS', N'1 Season', N'Follows Ancient Astronaut Theorist Giorgio A. Tsoukalos as he explores the most recent discoveries related to the centuries old story of Atlantis. By investigating a series of clues, Tsoukalos endeavors to narrow down the possible location of Atlantis.'),
(2120, N's2120', N'MOVIE', N'In My Dreams', NULL, 2020, N'13+', 11, N'MINUTES', N'11 min', N'''In My Dreams'' is a romantic comedy with a twist of mystery. Tim, a shy young man often has dreams of Mia, a beautiful girl he has fallen for. Strangely, his dreams always start with a stunning vision of Mia, only to end in a surreal and agonizing silence.'),
(2121, N's2121', N'MOVIE', N'In Enemy Hands', NULL, 2004, N'R', 98, N'MINUTES', N'98 min', N'As Hitler''s grip of fear continues to tighten during World War II, the capture of the U.S.S. Swordfish by a German U-boat leads to a brutal struggle for survival between axis and allies deep beneath the ocean surface.'),
(2122, N's2122', N'MOVIE', N'In Dreams', NULL, 1999, N'R', 100, N'MINUTES', N'100 min', N'Claire Cooper''s (Annette Bening) peaceful family life takes a chilling turn when a mysterious serial killer (Robert Downey Jr.) invades her seemingly idylic New England town... and haunts her dreams with dark clues to his next deadly moves.'),
(2123, N's2123', N'MOVIE', N'IN and Classic - curation testing', NULL, 2020, N'ALL', 1, N'MINUTES', N'1 min', N'test'),
(2124, N's2124', N'MOVIE', N'In a Lonely Place', NULL, 1950, N'13+', 93, N'MINUTES', N'93 min', N'A potentially violent screenwriter (Humphrey Bogart) is a murder suspect until his lovely neighbor clears him. However, she soon starts to have her doubts.'),
(2125, N's2125', N'MOVIE', N'Imaginary Friend', NULL, 2012, NULL, 90, N'MINUTES', N'90 min', N'A talented artist is haunted by the presence of a childhood imaginary friend, and her psychiatrist husband wants to have her committed to a mental institution.'),
(2126, N's2126', N'MOVIE', N'Iliza Shlesinger: War Paint', NULL, 2013, N'18+', 75, N'MINUTES', N'75 min', N'Her innocent good looks are just a cover for Last Comic Standing winner Iliza Shlesinger''s acerbic, stream-of-conscious comedy that she unleashes on an unsuspecting audience in her hometown of Dallas in her stand-up special, War Paint.'),
(2127, N's2127', N'MOVIE', N'Iliza Shlesinger: Over & Over', NULL, 2019, N'18+', 60, N'MINUTES', N'60 min', N'A documentary following Iliza Shlesinger behind-the-scenes as she prepares for her fourth special: Elder Millennial.'),
(2128, N's2128', N'TV_SHOW', N'Ilana Glazer: The Planet Is Burning', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'Ilana Glazer‘s debut standup special is trés lol, and turns out - she one funny b. Check out Ilana’s thoughts on partnership, being a successful stoner adult, Nazis, Diva Cups, and more. Hold on to your nuts cuz this hour proves how useless the patriarchy is. For Christ’s sake, The Planet Is Burning, and it’s time a short, queer, hairy New York Jew screams it in your face!'),
(2129, N's2129', N'TV_SHOW', N'Idiot TV', NULL, 2018, N'13+', 1, N'SEASONS', N'1 Season', N'The sister show to Car Crash TV, Idiot TV is here to show you how not to live, with hundreds of hilarious clips showcasing the world''s biggest fools.'),
(2130, N's2130', N'MOVIE', N'Iddari Lokam Okate', NULL, 2019, N'13+', 126, N'MINUTES', N'126 min', N'Iddari Lokam Okate is the story of Krishna & Satya, born on the same day, who come across each other several times during the course of their childhood & youth. They grow separately in different towns but each of their confluence causes drastic changes in their life. By taking 70s, 80s, 90s and 2000s the story builds on culture, music, lifestyles of the places & characters.'),
(2131, N's2131', N'MOVIE', N'Icy Demons', NULL, 2008, N'NR', 38, N'MINUTES', N'38 min', N'Icy Demons navigate more sonic terrain than Lewis and Clark over the course of their performance at New York''s Knitting Factory.'),
(2132, N's2132', N'MOVIE', N'ICEolation', NULL, 2019, N'ALL', 28, N'MINUTES', N'28 min', N'This is the story of two paddlers with adventurous spirits, whom when presented with a unique opportunity to undertake a self-supported sea kayak expedition in Antarctica, took it. Took it as an opportunity to go beyond adrenalin-based desires and the pleasing of engorged ego''s and instead explore as much within themselves as explore the magical, ice-littered waterways of the Antarctic Peninsula'),
(2133, N's2133', N'MOVIE', N'Ice Spiders', NULL, 2007, N'R', 86, N'MINUTES', N'86 min', N'A top-secret government facility in the mountains of Utah is creating genetically modified spiders under the direction of Dr. April Sommers. When the monstrous arachnids escape, they threaten to eat up the entire tourist population at the nearby ski resorts. Dr. Sommers must enlist the help of Army Captain Baker and retired Olympic skier Dan Dashiell to stop the disaster.'),
(2134, N's2134', N'MOVIE', N'Ice Princess Lily', NULL, 2019, N'PG', 89, N'MINUTES', N'89 min', N'Lily, a fearless Ice Princess teams up with a young dragon named Tabaluga. Together they must stop an evil snowman and an army of polar bears from freezing over the entire world. Lily must inspire Tabaluga to unlock his potential and discover the fire that has always been within him'),
(2135, N's2135', N'MOVIE', N'Ice Guardians', NULL, 2016, N'16+', 108, N'MINUTES', N'108 min', N'Exploring one of the most controversial and provocative positions in the history of sport, Ice Guardians journeys into the lives of those who perform what is undoubtedly the toughest job within the National Hockey League today: the enforcer.'),
(2136, N's2136', N'MOVIE', N'Ice Blues: A Donald Strachey Mystery', NULL, 2008, N'18+', 84, N'MINUTES', N'84 min', N'Gay detective Donald Strachey is asked by his partner Tim to investigate a mysterious donation to a youth center. Donald gets caught up in a whirlwind of deceit and danger.'),
(2137, N's2137', N'MOVIE', N'Ice', NULL, 2000, N'16+', 90, N'MINUTES', N'90 min', N'After the whole North of the Equator freezes below zero, a group of people in Los Angeles risk their lives while trying to "escape" from the city''s hostile conditions, in order to take a ship to a hotter place on Earth.'),
(2138, N's2138', N'MOVIE', N'Ian Harvie: May The Best Man Win', NULL, 2016, N'18+', 57, N'MINUTES', N'57 min', N'Ian Harvie is redefining what it means to be a dude through a fresh perspective on sex/sexuality. Unafraid to quip about subjects no other comedian has touched, Ian challenges the traditional macho, sex-obsessed world of stand up, proving that laughter cuts across all identities and ultimately unites us all. Ian is the first trans man comedian with a comedy special.'),
(2139, N's2139', N'MOVIE', N'Ian Bagg: Conversations', NULL, 2018, N'18+', 54, N'MINUTES', N'54 min', N'The native Canadian comedian, Ian Bagg, brings his sharp, biting wit to The Improv in Irvine, CA to explore such topics as immigration, transgender bathrooms and women''s obsession with yoga pants.'),
(2140, N's2140', N'TV_SHOW', N'I''ve Got A Secret', NULL, 1962, N'TV-G', 1, N'SEASONS', N'1 Season', N'Four celebrity panelists try to guess the secret of a contestant by asking questions of that person that result in "yes" or "no" answers.'),
(2141, N's2141', N'MOVIE', N'I''d Give My Life', NULL, 1936, N'13+', 74, N'MINUTES', N'74 min', N'Gangster Buck Gordon hopes his son Nick will follow in his criminal footsteps, but his efforts are foiled by his ex-wife, who has married Governor Bancroft (Standing). Furious, Buck blackmails his ex-wife, threatening to expose her shady past to her new husband. Nick comes to his mother''s aid by shooting and killing his father, but refuses to give a motive, even when he is sentenced to hang for the crime. Based on the play, "The Noose."'),
(2142, N's2142', N'TV_SHOW', N'I, Caesar: The Rise and Fall of the Roman Empire', NULL, 1997, N'18+', 1, N'SEASONS', N'1 Season', N'This classic series explores the public and private lives of six rulers of ancient Rome: Julius Caesar, Augustus, Nero, Hadrian, Constantine and Justinian. Their careers were defined by bloody battles, far-reaching innovations and profound corruption. Together, they paint a picture of the sophisticated highs and brutal lows of the Roman Empire, its sensational birth, heyday and final decline.'),
(2143, N's2143', N'TV_SHOW', N'I Was Possessed', NULL, 2015, N'TV-14', 1, N'SEASONS', N'1 Season', N'I Was Possessed chronicles present day demonic possession and exorcism firsthand. Through first person accounts and recreations, you''ll hear from the possessed and from family and friends who witnessed and experienced their strange and disturbing changes.'),
(2144, N's2144', N'MOVIE', N'I Was Not Ready Da', NULL, 2020, N'16+', 77, N'MINUTES', N'77 min', N'Imagine 2 flowers pollinating onscreen for an hour, that''s ''SA''s- I Was Not Ready Da,'' a show for the whole family; to watch separate separately! From his teenage love for white people and chatrooms and socialist strip club visits in the U.S., to shocking Sanskrit tutors and provoking news anchors in their own shows, SA narrates hilarious tales.'),
(2145, N's2145', N'TV_SHOW', N'I Survived . . .', NULL, 2008, N'TV-14', 1, N'SEASONS', N'1 Season', N'I Survived incorporates interviews with stylized recreations to tell the stories of people who overcame unbelievable circumstances that changed their lives forever.'),
(2146, N's2146', N'TV_SHOW', N'I Shouldn''t Be Alive', NULL, 2010, N'13+', 3, N'SEASONS', N'3 Seasons', N'Re-enactments of real-life tales of human survival against the savage elements, dangerous climates and physical hazards.'),
(2147, N's2147', N'MOVIE', N'I Need You To Kill', NULL, 2017, NULL, 98, N'MINUTES', N'98 min', N'I Need You to Kill follows three American comics - Chad Daniels, Pete Lee, and Tom Segura on a six show tour through three of the world''s newest stand-up comedy scenes: Hong Kong, Singapore, and Macau. The film explores the anxieties and surprises of taking your act halfway around the world as well as giving a ground-floor glimpse into Asia''s newest growth industry - stand-up comedy."'),
(2148, N's2148', N'MOVIE', N'I Love Toy Trains - Ticket to Ride', NULL, 2013, N'ALL', 51, N'MINUTES', N'51 min', N'One of the best-selling kid series in the country. Parents'' Choice award winner. Rave reviews in the national media. See real and toy trains in action - a large outdoor G-gauge exhibit, "oh no" bloopers and the toe-tapping music of James Coffey.'),
(2149, N's2149', N'MOVIE', N'I Love Toy Trains - All Aboard', NULL, 2011, N'ALL', 38, N'MINUTES', N'38 min', N'Steamers, diesels zipping around curves, through tunnels, and over bridges. Fave candies being loaded and unloaded by Lionel accessories. Toe-tapping music of James Coffey and a fun spirit that will thrill and delight young and old alike.'),
(2150, N's2150', N'TV_SHOW', N'I Love Dick', NULL, 2017, N'18+', 1, N'SEASONS', N'1 Season', N'Adapted from the lauded feminist novel, I LOVE DICK is set in a colorful academic community in Marfa, Texas. It tells the story of a struggling married couple, Chris and Sylvere, and their obsession with a charismatic professor named Dick. Told in Rashomon-style shifts of POV, I LOVE DICK charts the unraveling of a marriage, the awakening of an artist and the deification of a reluctant messiah.'),
(2151, N's2151', N'MOVIE', N'I Had a Bloody Good Time at House Harker', NULL, 2017, N'16+', 80, N'MINUTES', N'80 min', N'It''s been generations since the Harkers'' great-great grandfather killed the one-and-only Count Dracula. Now the Harker brothers and their best friend Ned are a town joke-until a real vampire turns up!'),
(2152, N's2152', N'MOVIE', N'I Cover the Waterfront', NULL, 1933, N'PG-13', 61, N'MINUTES', N'61 min', N'An investigative reporter romances a suspected smuggler''s daughter.'),
(2153, N's2153', N'MOVIE', N'I Capture The Castle', NULL, 2003, N'R', 113, N'MINUTES', N'113 min', N'A love story set in 1930s England that follows 17-year-old Cassandra Mortmain, and the fortunes of her eccentric family, struggling to survive in a decaying English castle.'),
(2154, N's2154', N'MOVIE', N'I Can''t Believe I''m Telling You This', NULL, 2009, N'13+', 61, N'MINUTES', N'61 min', N'We live in a world where prostate cancer grips two thirds of men before the age of 80. Yet a culture of silence surrounds this uncomfortable disease. I Can''t Believe I''m Telling You This charts a year in the life of three very different men dealing with prostate cancer, who have found strength and each other, online.'),
(2155, N's2155', N'MOVIE', N'I Bury the Living', NULL, 1958, N'PG-13', 77, N'MINUTES', N'77 min', N'A bone-chilling story of cemetary manager Robert Craft (Boone), a disturbed man who comes to believe that he is actually God. Robert discovers that when he sticks a black pin into a wall-sized map of the cemetary, he can cause the owner of that plot to die. After several such untimely deaths, Robert believes he has the power of life and death. But will Robert still believe this once he discovers the true secret behind these deaths?'),
(2156, N's2156', N'MOVIE', N'I am the Flash', NULL, 2015, N'7+', 8, N'MINUTES', N'8 min', N'Barry is given a "Flash" T-shirt from his girlfriend that awakens a repressed delusion of super-speed that proves to be more than they both bargained for.'),
(2157, N's2157', N'MOVIE', N'I Am Road Comic', NULL, 2014, N'18+', 68, N'MINUTES', N'68 min', N'People are fascinated more than ever about what drives comedians to do what they do and, more importantly, how they pull it off. Director and comedian, Jordan Brady, explore these questions and more in this documentary film.'),
(2158, N's2158', N'TV_SHOW', N'Hyperdrive', NULL, 2007, N'TV-PG', 2, N'SEASONS', N'2 Seasons', N'The crew of the HMS Camden Lock return for another season of the critically acclaimed and international award winning sci-fi comedy. It''s 2152 and Commander Henderson and his team are powering their way through the galaxy once again, still promoting the tourist wonders and business opportunities of the UK.'),
(2159, N's2159', N'MOVIE', N'Hyena Road', NULL, 2016, N'R', 120, N'MINUTES', N'120 min', N'Three men, three different paths, caught in conflict but brought together to save lives: a highly skilled sniper who can''t think of his targets as human, an intelligence officer who has never killed while on duty, and a legendary Afghan warrior who left war behind but gets pulled back to battle.'),
(2160, N's2160', N'TV_SHOW', N'Hustle', NULL, 2012, N'16+', 8, N'SEASONS', N'8 Seasons', N'An action-packed blend of humour and intrigue, following the fortunes of a gang of expert cons on the loose in London. They are specialists in the way of the grifter and all are keen to liberate cash from the amoral and undeserving. From faking film sets and expensive paintings to double-crossing the duplicitous head of a bank''s security system. The con is on.'),
(2161, N's2161', N'MOVIE', N'Hurricane At Pilgrim Hill', NULL, 1950, N'PG', 73, N'MINUTES', N'73 min', N'Sam "Bigmouth" Smedley travels to Pilgrim Hill, Massachusets, to "help" his unhappy daughter Janet. Sam soon learns that the cause is Janet''s lawyer husband Tom''s troublesome biggest client, Jonathan Smith, who owns and controls most of Pilgrim Hill. The controlling Smith even refuses to allow his daughter, Sally, to marry her poor, but kind, sweetheart Steve. Sam kidnaps Smith and brings him to a small deserted island off the coast. He then performs an old indian rain dance to create a storm to make Smith disappear. The dance works too well, a hurricane springs up, and Smith disappears in the storm. The local sheriff charges Sam with his murder. But is Smith really dead? A goofy, fun farce with a rare starring role for character actor Clem Bevans.'),
(2162, N's2162', N'TV_SHOW', N'Hunting ISIS', NULL, 2018, N'TV-MA', 1, N'SEASONS', N'1 Season', N'Completely unpaid and unsupported by their governments, western volunteers have travelled to the Middle East to rejoin the fight against ISIS.'),
(2163, N's2163', N'TV_SHOW', N'Hunting Hitler', NULL, 2018, N'TV-PG', 3, N'SEASONS', N'3 Seasons', N'In "Hunting Hitler," an FBI cold case that has laid dormant for 70 years leads a group of world-renown investigators on the ultimate manhunt to finally answer the question: Did Adolf Hitler survive World War II?'),
(2164, N's2164', N'TV_SHOW', N'Hunters', NULL, 2020, N'18+', 1, N'SEASONS', N'1 Season', N'Inspired by true events, HUNTERS follows a diverse band of Nazi Hunters in 1977 New York City who discover that hundreds of escaped Nazis are living in America. And so, they do what any bad-ass vigilante squad would do: they set out on a bloody quest for revenge and justice. But they soon discover a far-reaching conspiracy and must race against time to thwart the Nazis’ new genocidal plans.'),
(2165, N's2165', N'TV_SHOW', N'Hunted', NULL, 2019, N'13+', 4, N'SEASONS', N'4 Seasons', N'The opening scene of Hunted Series 4 sees the crack squad of Hunters launch a helicopter to track a boat off the northwest coast of the UK. The vessel is heading at speed towards Liverpool docks carrying six teams of fugitives determined to evade capture for the next 25 days.'),
(2166, N's2166', N'TV_SHOW', N'Hunderby', NULL, 2015, N'TV-MA', 2, N'SEASONS', N'2 Seasons', N'Set in an isolated rural parish in the early 1800s, Hunderby is a twisted Austen world of doomed romance, closet homosexuality and accidental incest. It''s period drama deconstructed by the dark and absurd humor that has become Julia Davis'' trademark.'),
(2167, N's2167', N'MOVIE', N'Hunan: The Other World of Avatar', NULL, 2017, N'7+', 52, N'MINUTES', N'52 min', N'Zhangjiajie National Park, in Hunan, China, is one of the most beautiful parks in the world. The mountains stand like swords, the peaks like small levitating territories that emerge from the clouds below. This unique landscape caught the attention of American director James Cameron. He traveled here to find inspiration for the blockbuster movie Avatar and its mysterious fictional planet, Pandora.'),
(2168, N's2168', N'TV_SHOW', N'Humans', NULL, 2018, N'TV-14', 3, N'SEASONS', N'3 Seasons', N'In Series 3 of the hit sci-fi drama, a year has passed since the synths gained consciousness, but they''re fighting to survive in a world that hates and fears them.'),
(2169, N's2169', N'MOVIE', N'Human Flow', NULL, 2017, N'PG-13', 141, N'MINUTES', N'141 min', N'Artist, activist and director Ai Weiwei captures the global refugee crisis - the greatest human displacement since World War II - I in this breathtakingly epic film journey HUMAN FLOW.'),
(2170, N's2170', N'MOVIE', N'Hud', NULL, 1963, N'7+', 112, N'MINUTES', N'112 min', N'Paul Newman stars as Hud Bannon, the rebellious son of a respectable rancher who''s continually at odds with his aging father.'),
(2171, N's2171', N'MOVIE', N'Howie Mandel Presents: Howie Mandel at the Howie Mandel Comedy Club', NULL, 2019, NULL, 56, N'MINUTES', N'56 min', N'Howie Mandel presents Howie Mandel at the Howie Mandel Comedy Club is Howie''s first stand-up comedy special in over 20 years! After being a mainstay on the stand-up comedy circuit for 40 years, Howie takes the stage at the comedy club that bears his name in Atlantic City, NJ. 8 out of 10 critics agree.'),
(2172, N's2172', N'TV_SHOW', N'Howards End', NULL, 2018, N'TV-14', 1, N'SEASONS', N'1 Season', N'The Schlegel sisters are two independent and unconventional sisters seeking love and meaning as they navigate an ever-changing world.'),
(2173, N's2173', N'MOVIE', N'How We Got Gay', NULL, 2016, N'13+', 43, N'MINUTES', N'43 min', N'This film tells the incredible story of how gay men and women went from being the ultimate outsiders to occupying the halls of power. Society looked at homosexuality not just as a subculture apart from the mainstream, but a community of people who were sick and deviant. How did members of this community come to exert such a profound influence on our cultural, political and social lives?'),
(2174, N's2174', N'MOVIE', N'How Not to Die', NULL, 2016, N'18+', 82, N'MINUTES', N'82 min', N'The majority of premature deaths can be prevented through simple changes in diet and lifestyle. In How Not to Die, Dr. Michael Greger examines the fifteen top causes of death in America-heart disease, various cancers, diabetes, high blood pressure, and more. He explains how nutrition and lifestyle can sometimes trump prescription pills and other approaches, freeing us to live healthier lives.'),
(2175, N's2175', N'TV_SHOW', N'How I Met Your Mother', NULL, 2014, N'TV-PG', 10, N'SEASONS', N'10 Seasons', N'Throw away the Playbook for good! In the series'' hilarious final season, you''re invited to Barney and Robin''s epic wedding weekend, and we get to know Ted''s – wait for it – "The One"!'),
(2176, N's2176', N'MOVIE', N'How China Got Rich', NULL, 2019, N'13+', 57, N'MINUTES', N'57 min', N'Over the last 40 years, China has been transformed out of all recognition. The scale of its growth and the sheer speed of change has been astonishing. The country has seen the largest lifting of people out of poverty that has ever taken place in human history. How did an impoverished and backward communist country become an engine of global capitalism? What lies ahead for this economic behemoth?'),
(2177, N's2177', N'TV_SHOW', N'How 2', NULL, 1990, N'ALL', 1, N'SEASONS', N'1 Season', N'How 2 is a world-famous children''s programme dedicated to science and general trivia. Originally aired in 1966 under the title How, TVS brought it back to life in 1990. Though the name was changed, the format stayed the same: Three presenters sit around a table, and ask rhetorical questions'),
(2178, N's2178', N'MOVIE', N'House on Haunted Hill (in Color)', NULL, 1958, N'13+', 76, N'MINUTES', N'76 min', N'Price stars as a suave, eccentric millionaire who invites five guests to spend the night in a sinister haunted house, offering each $10,000 but only if they survive until morning! Restored and In Color!'),
(2179, N's2179', N'MOVIE', N'House of Sand and Fog', NULL, 2004, N'R', 126, N'MINUTES', N'126 min', N'Massoud Amir Behrani has spent most of his savings trying to enhance his daughter''s chances of a good marriage. Once she is married, he spends the remaining funds on a house at an auction, putting himself in the middle of a legal tussle with the property''s legal owner who''s a former drug addict.'),
(2180, N's2180', N'MOVIE', N'House', NULL, 1986, N'R', 92, N'MINUTES', N'92 min', N'Horror novelist Roger Cobb is a man on the edge, reeling from his recent divorce, haunted by the mysterious disappearance of his young son, and struggling with his new book about his traumatic experiences in Vietnam. But when he moves into the strange house left to him by his late aunt, Roger''s precarious sanity comes under siege by nightmares.'),
(2181, N's2181', N'MOVIE', N'Hotel Coolgardie', NULL, 2017, N'13+', 84, N'MINUTES', N'84 min', N'In remotest red-dust Australia is the sleepy mining town of Coolgardie. When two Finnish girls take jobs in the town''s pub, they find themselves in a trial of endurance, and soon realise that pouring pints is the least of their work. Amusing, disturbing, and thoroughly bizarre, this candid documentary reveals the struggles of adapting to life in an insular community.'),
(2182, N's2182', N'TV_SHOW', N'Hot Mess Millionaire', NULL, 2020, N'TV-MA', 1, N'SEASONS', N'1 Season', N'From the "mean streets" of Baltimore, Md to Stanford Ph.D. to Black Woman Millionaire, Dr. Venus Opal Reese reveals the "raw and uncut" reality of what it REALLY takes to be "self-made."'),
(2183, N's2183', N'MOVIE', N'Hot Guys With Guns', NULL, 2014, N'18+', 111, N'MINUTES', N'111 min', N'If you can imagine Lethal Weapon with Mel Gibson and Danny Glover as younger, hotter ex-boyfriends, you''ll have the basis for Hot Guys With Guns, a modern take on the old-fashioned detective story. It''s Chinatown meets Boystown.'),
(2184, N's2184', N'MOVIE', N'Hot Buttered Rum', NULL, 2011, N'NR', 38, N'MINUTES', N'38 min', N'Hot Buttered Run bring a good ol'' foot-stompin'' time on the Lower East Side.'),
(2185, N's2185', N'MOVIE', N'Hostile Border', NULL, 2016, N'R', 84, N'MINUTES', N'84 min', N'When she''s deported to México, Claudia must choose between reconciling with her estranged father or partnering with a dangerous smuggler to return to the U.S.'),
(2186, N's2186', N'MOVIE', N'Horse Tribe', NULL, 2014, N'PG', 57, N'MINUTES', N'57 min', N'Legendary as one of America''s greatest horse tribes, the 21st century Nez Perce decided to bring horses back to their land and lives with the unlikely help of a charismatic Navajo horseman, Rudy Shebala.'),
(2187, N's2187', N'TV_SHOW', N'Horrid Henry', NULL, 2014, N'ALL', 3, N'SEASONS', N'3 Seasons', N'Ever get the feeling that life just isn''t fair? Henry gets that feeling, all of the time. Of course he''s only a kid, but with a perfect little brother called Peter, a Mum and Dad who''d love him dearly if only he''d stop behaving, well, like a kid, and a moody girl next door who''s on a mission to make Henry''s life miserable, who can blame him?'),
(2188, N's2188', N'TV_SHOW', N'Horrible Science', NULL, 2015, N'TV-NR', 1, N'SEASONS', N'1 Season', N'The first ever series based on the well known books of the same name published by Scholastic. Originally produced for CiTV, ABC and Discovery and now available exclusively to Amazon Prime. Horrible Science is a spoof of a TV science show with behind the scenes and shiny floor drama starring Ben Miller.'),
(2189, N's2189', N'MOVIE', N'Hope Ranch', NULL, 2002, N'PG-13', 90, N'MINUTES', N'90 min', N'Former police officer and marine J.T. Hope starts a program for troubled teens on his ranch, Circle Hope Ranch, to help juvenile delinquents get started on a path away from crime and drugs through honest labor and teamwork.'),
(2190, N's2190', N'MOVIE', N'Hope Lost', NULL, 2016, NULL, 95, N'MINUTES', N'95 min', N'A young girl, bored with her small-town, dreams of a more glamorous life. At a club, she meets Gabriel, who claims to be a TV producer and wants to cast her in a reality TV show in Italy. When she arrives, she realizes this is a ruse when she is sold to a pimp. Things take an even darker turn with the arrival of Ettore, a sadist who intends to torture her and another young woman in a snuff movie.'),
(2191, N's2191', N'MOVIE', N'HooplaKidz Nursery Rhyme Time - Part 2', NULL, 2019, N'ALL', 17, N'MINUTES', N'17 min', N'HooplaKidz presents the popular nursery rhymes movie which will help children learn and have fun at the same time.Follow Annie, Ben and Mango as they move to "Humpty Dumpty", "If You''re happy And You Know It", "School Bus Song" and many more! Have a Hoopla time!'),
(2192, N's2192', N'MOVIE', N'Honeymoon Limited', NULL, 1935, N'13+', 72, N'MINUTES', N'72 min', N'Discouraged and unsuccessful writer Dick Gordon (Hamilton) concocts a plan to earn money and get publicity by walking from New York to San Francisco in six months, then writing a book on his experiences. Along the way, a horrible storm forces Dick to take refuge in what he believes to be a deserted, remote cabin. However, he finds a runaway and her two sisters also hiding out there. But all are placed in danger when the cabin''s owner shows up, along with his gangster pals, to retrieve their stolen money, which is hidden in the cabin. Never one to miss an opportunity, Dick is ecstatic to finally find an exciting true story worth writing about, but will he survive long enough to pen his book?'),
(2193, N's2193', N'MOVIE', N'Honest Thief', NULL, 2020, N'PG-13', 99, N'MINUTES', N'99 min', N'Wanting to lead an honest life, a notorious bank robber (Liam Neeson) turns himself in, only to be double-crossed by two ruthless FBI agents.'),
(2194, N's2194', N'TV_SHOW', N'Honest Men', NULL, 2017, N'TV-NR', 1, N'SEASONS', N'1 Season', N'Prepare for an open and honest conversation between fathers, their sons, and the boy next door. We meet Colby [King David] who is dealing with the death of his father; returning to his childhood home after four years of being away. And next door lives the infamous Mark [Donta Hensley], a man who is known up and down the block for his temper and violent ways. Then there''s JT [Tripp Ali].'),
(2195, N's2195', N'TV_SHOW', N'HomeMADE', NULL, 2009, N'ALL', 1, N'SEASONS', N'1 Season', N'HomeMADE is the biggest renovation competition ever attempted on television. Ten talented designers from around Australia will compete for a $100,000 cash prize when they take on the biggest challenge of their lives - to completely makeover two suburban family homes every week.'),
(2196, N's2196', N'TV_SHOW', N'Homecoming', NULL, 2020, N'16+', 2, N'SEASONS', N'2 Seasons', N'START WITH SEASON TWO and experience a new mystery when Jackie (Janelle Monáe) finds herself floating in a boat in the middle of a lake, with no memory of how she got there – or even who she is. Her search for identity will lead her into the heart of the Geist Group, an unconventional wellness company behind the controversial Homecoming Initiative.'),
(2197, N's2197', N'MOVIE', N'Home Sweet Home', NULL, 2020, NULL, 84, N'MINUTES', N'84 min', N'A young, flirtatious barista is bored with her social lifestyle and longs for real love. So when an eligible, handsome guy walks into her coffee shop, she turns on the charm, but he doesn''t respond to her flirting like men usually do. When she discovers that he runs a ministry that builds affordable housing, she decides to volunteer.'),
(2198, N's2198', N'MOVIE', N'Home for the Holidays', NULL, 1995, N'PG-13', 103, N'MINUTES', N'103 min', N'Claudia Larson is heading home for yet another chaotic and exasperating family Thanksgiving. But a new visitor offers some interesting possibilities. If they can duck the flying turkeys, this romance may just have a chance.'),
(2199, N's2199', N'TV_SHOW', N'Home Fires', NULL, 2017, N'TV-PG', 2, N'SEASONS', N'2 Seasons', N'Amidst the Battle of Britain, some of Great Paxford''s women find that the war throws off peacetime limitations, allowing them to flourish in unexpected ways-testing relationships, friendships, and loyalties as never before.'),
(2200, N's2200', N'TV_SHOW', N'Home and Away', NULL, 1989, N'13+', 2, N'SEASONS', N'2 Seasons', N'"Home and Away" chronicles the lives, loves, happiness and heart-breaks of the residents of Summer Bay, a small coastal town just outside of Sydney in New South Wales, Australia.');

Iori is looking forward to experiencing college life amidst the roar of the waves, the blazing sun, and his cute cousin who lives with him!
However, Iori runs into a group of tough guys playing strip rock-paper-scissors, and ends up joining Peek-a-Boo, the college''s diving club!'),
(2302, N's2302', N'TV_SHOW', N'Gracepoint', NULL, 2014, N'13+', 1, N'SEASONS', N'1 Season', N'When a young boy is found dead on an idyllic beach, a major police investigation gets underway in the small California seaside town where the tragedy occurred. Soon deemed a homicide, the case sparks a media frenzy, which throws the boy''s family into further turmoil and upends the lives of all of the town''s residents.'),
(2303, N's2303', N'MOVIE', N'Grace of God', NULL, 2015, N'16+', 99, N'MINUTES', N'99 min', N'Having lost his faith years ago, Detective Broadly is called to investigate the disappearance of the local church''s collection plate. As he questions its various church members, rumors swirl. When one unexpected church-goer confesses to stealing the funds, the confession resurrects Broadly''s views on God, and helps him see that through faith and belief there really is rebirth and redemption.'),
(2304, N's2304', N'MOVIE', N'Goyenda Junior', NULL, 2019, N'ALL', 118, N'MINUTES', N'118 min', N'Bikram (Rwitobroto Mukherjee), a teenage boy, spends his days mooning over his crush Tuki (Anusha Viswanathan), and reading lots of crime fiction. An odd twist of events leads Bikram on a quest to solve the perfect crime - a murder cleverly disguised as a natural death !'),
(2305, N's2305', N'TV_SHOW', N'Gown and Out in Beverly Hills', NULL, 2020, N'18+', 2, N'SEASONS', N'2 Seasons', N'Gown and Out in Beverly Hills is as revealing as it gets, taking you into the lives, excitement, magic and beauty of the show''s stars'', celebrity fashion designers, Pol'' Atteu, Patrik Simpson and their PawSonality, Lil'' SnowWhite90210. Their world-famous boutique caters to some of Hollywood''s most glamorous and demanding celebrities as they prepare them for Red-Carpet debuts.'),
(2306, N's2306', N'TV_SHOW', N'Gortimer Gibbon''s Life on Normal Street', NULL, 2016, N'7+', 3, N'SEASONS', N'3 Seasons', N'As the series comes to a close, Gortimer, Mel and Ranger grow closer than ever, even as growing up threatens to pull them apart. Their adventures on Normal Street continue as Mel learns the consequences of overextending herself, Ranger takes on other people''s problems while ignoring his own, and Gortimer grapples with the greatest challenge of all: leaving Normal Street'),
(2307, N's2307', N'MOVIE', N'Gorgeous Aerial Views', NULL, 2019, N'ALL', 60, N'MINUTES', N'60 min', N'Spectacular aerial nature video from around the world. Vistas include Black Sand Beach in Maui, Chicago River at night, Lower Manhattan in New York City, Castle Valley in Utah, Ho''okipa Beach in Hawaii, Los Arcos in Cabo San Lucas, Northern California Coast, Clearwater Beach in Florida, Rio Grand River in Texas, Island Espiritu Santo Baja California, Peruvian petroglyphs and more.'),
(2308, N's2308', N'MOVIE', N'Gook', NULL, 2017, N'18+', 95, N'MINUTES', N'95 min', N'In a predominantly African-American community in LA, two Korean-American brothers run a shoe store where they strike up a unique and unlikely friendship with a young African-American girl, Kamilla. As one brother dreams of becoming a recording artist and the other struggles to keep the store afloat, racial tensions build to a breaking point in L.A. as the "infamous" L.A. Riots break out.'),
(2309, N's2309', N'TV_SHOW', N'GooGoo: Learn Colors and vehicles with Funny Baby', NULL, 2018, N'ALL', 2, N'SEASONS', N'2 Seasons', N'GooGoo and GaaGaa are two 18 month old cute and curious babies. who are best friends and love to laugh. In each episode the two friends will encounter a funny shaped friend that will capture attention make them laugh and then come to life as a different musical instrument'),
(2310, N's2310', N'MOVIE', N'Goodbye World', NULL, 2014, NULL, 101, N'MINUTES', N'101 min', N'When a mysterious terrorist attack causes chaos in the cities, a group of friends take refuge in their countryside cabin. But the challenges of living in a post-apocalyptic world soon take their toll on relationships within the group.'),
(2311, N's2311', N'MOVIE', N'Goodachari', NULL, 2018, N'18+', 142, N'MINUTES', N'142 min', N'After being trained in an ultra competitive secret service program, Arjun, A young agent is framed for the murder of his bosses, suddenly turning him into India''s most wanted criminal. Who framed him? And why? For someone who was taught that the ''mission'' is everything, Arjun now realizes that now his mission is darker than expected.'),
(2312, N's2312', N'TV_SHOW', N'Good Omens', NULL, 2019, N'16+', 1, N'SEASONS', N'1 Season', N'The End of the World is coming, which means a fussy Angel and a loose-living Demon who’ve become overly fond of life on Earth are forced to form an unlikely alliance to stop Armageddon. But they have lost the Antichrist, an 11-year-old boy unaware he’s meant to bring upon the end of days, forcing them to embark on an adventure to find him and save the world before it’s too late.'),
(2313, N's2313', N'MOVIE', N'Good Intentions', NULL, 2010, N'PG-13', 85, N'MINUTES', N'85 min', N'Etta''s husband Chester, wannabe entrepreneur and liquor store owner, blows every nickel he makes trying to get rich on hare-brained inventions. After their young boys, sneak off to try smoking and blow up the backyard shed full of Chester''s homemade fireworks, smart and sassy Etta realizes she must take matters into her own hands to fulfill her dream of sending the boys to college one day.'),
(2314, N's2314', N'TV_SHOW', N'Good Girls Revolt', NULL, 2016, N'18+', 1, N'SEASONS', N'1 Season', N'In 1969, while a cultural revolution swept through the free world, there was still one place that refused to change with the times: newsrooms. Good Girls Revolt follows a group of young female researchers at "News of the Week," who ask to be treated fairly. Their revolutionary request sparks convulsive changes and upends marriages, careers, sex lives, love lives, and friendships.'),
(2315, N's2315', N'MOVIE', N'Gold', NULL, 2018, N'13+', 146, N'MINUTES', N'146 min', N'Set in 1948, the historical story of India''s first Olympic medal posts their independence.'),
(2316, N's2316', N'TV_SHOW', N'Going Viral Pvt. Ltd.', NULL, 2017, N'TV-NR', 1, N'SEASONS', N'1 Season', N'Going Viral Pvt. Ltd. is a place, where hopeful Indians come with their dreams and money - to do the one thing everyone aspires to- become famous by going viral. Can this firm win over social media? Or will it all end in disaster?'),
(2317, N's2317', N'MOVIE', N'Goin'' South', NULL, 1978, N'PG', 108, N'MINUTES', N'108 min', N'According to the laws of the Old West town where criminal Henry Lloyd Moon (Jack Nicholson) is about to be executed, a death row convict will be spared if a reputable woman promises to marry him and mend his ways. When Julia Tate (Mary Steenburgen) vouches for Henry, he is allowed to walk free, but now must deal with his old gang, the Sheriff, the bank, and his new wife.'),
(2318, N's2318', N'TV_SHOW', N'Gogo Dino Explorers', NULL, 2018, N'ALL', 2, N'SEASONS', N'2 Seasons', N'In the far reaches of the universe there is a planet called M25, on which many species exist, including dinosaurs that became extinct on earth thousands of years ago! Meet Rex, Tomo, Viki, Ping, and Rocky, the GoGo Dinos, whose mission is to explore M25, discovering new dinosaurs and always lending a helping hand to save the day!'),
(2319, N's2319', N'MOVIE', N'Gog', NULL, 1954, N'13+', 83, N'MINUTES', N'83 min', N'A giant brain machine is programmed to sabotage a government space station.'),
(2320, N's2320', N'TV_SHOW', N'God of Lost Fantasy', NULL, 2020, N'13+', 1, N'SEASONS', N'1 Season', N'Qin Wentian is born as a sickly child and his adopted parents are forced to send him to the Bai''s famiy to marry their daughter. However the Bai family tries to back out of the marriage proposal and kill Wentian.'),
(2321, N's2321', N'MOVIE', N'God City Da Movie', NULL, 2021, N'18+', 86, N'MINUTES', N'86 min', N'In the cold streets of Charlotte, where murder is on the rise, a drug deal gone wrong has now created a who done it in the city. With a shooting of a druglord thug on the streets and drugs stolen, the feds and rival gangsters are closing in on the towns 2 hustlers that are now on the chase starring down south rappers Chezzy Boy, Tee Grizzley Ralofamgoon and Bankroll Ziggy.'),
(2322, N's2322', N'TV_SHOW', N'Go with YoYo! Exercise, Yoga and Mindfulness for Kids', NULL, 2020, N'ALL', 1, N'SEASONS', N'1 Season', N'GO with YOYO is a place for fitness fun and playful yoga for kids. Jump around and get moving with YOYO, twist into fun yoga poses, and exercise with props you can find at home like your stuffed animal, paper plates and lots more! By blending educational elements with brain boosting movements and our attitude of gratitude, kids are making both their muscles and their mind strong!'),
(2323, N's2323', N'TV_SHOW', N'Go Go Babies in Car City', NULL, 2021, N'ALL', 1, N'SEASONS', N'1 Season', N'Chili, Sunny and Berry are three cute baby cars. Every day, they go around Car City to meet its inhabitants and new discover activities... to have fun and growing up !'),
(2324, N's2324', N'MOVIE', N'Go Fast. Go North.', NULL, 2017, N'16+', 99, N'MINUTES', N'99 min', N'The Race2Alaska is one of adventure racing''s greatest competitions - challenging mariners to navigate 750 miles of BC''s most infamous waterways by human or wind power alone. The rules are simple: no motors, no outside help or support, first boat over the line wins.'),
(2325, N's2325', N'MOVIE', N'Go Buster Tunes by Little Baby Bum', NULL, 2019, N'ALL', 26, N'MINUTES', N'26 min', N'Buster the yellow bus is back with some of his favourite tunes to sing along to! Brought to you by the creators of Little Baby Bum, your kids will love to sing to songs such as ''Wheels On The Bus'', ''Carwash Song'', and ''School Bus Song!'''),
(2326, N's2326', N'MOVIE', N'Go Buster - Exciting Adventures', NULL, 2019, N'ALL', 32, N'MINUTES', N'32 min', N'The creators of Little Baby Bum are proud to present you with a compilation filled with brand new Go Buster episodes! In this compilation, follow our favorite small yellow Buster as he loses his first baby tooth, plays hide and seek, and wins a game of soccer with his wonderful vehicle friends!'),
(2327, N's2327', N'MOVIE', N'Go Buster - Educational Cartoons for Kids', NULL, 2021, N'ALL', 35, N'MINUTES', N'35 min', N'Go Buster is an animated online educational kids series watched all over the globe. Go Buster encourages learning, creativity, and fun! Learn colors, shapes, numbers and more, with our well-loved characters!'),
(2328, N's2328', N'MOVIE', N'Go Buster - Christmas Special', NULL, 2020, N'ALL', 20, N'MINUTES', N'20 min', N'Join Buster the Bus and the family in this festive Christmas special collection! Go Buster is an animated online educational kids series watched all over the globe. Brought to you by the creators of Little Baby Bum, Go Buster encourages learning, creativity and fun! Learn colors, shapes, and numbers with our well-loved characters!'),
(2329, N's2329', N'MOVIE', N'Go Buster - Buster And Friends', NULL, 2019, N'ALL', 31, N'MINUTES', N'31 min', N'Buster is a sweet little bus who loves playing. He has a lot to learn about the world and he is always faced with different little challenges to overcome. He loves a giggle which he loves to share with his friends. In this compilation, follow Buster as he builds sandcastles with his friend Digger, stands up against his bully Robot Buster, and teaches you all sorts of cool shapes he''s learned!'),
(2330, N's2330', N'MOVIE', N'Go Buster - Baby Bus Cartoons', NULL, 2019, N'ALL', 34, N'MINUTES', N'34 min', N'Enjoy a collection of educational yet fun children''s stories with Buster, a bright little yellow bus who is curious about the world. Created by the minds behind Little Baby Bum, Go Buster teaches young pre-schoolers simple life lessons through the lens of Buster. Come join Buster as he plays with his friends, Terry the tractor and Scout the car!'),
(2331, N's2331', N'MOVIE', N'Go Buster - Awesome Songs', NULL, 2019, N'ALL', 32, N'MINUTES', N'32 min', N'Come and enjoy the hilarious and fun adventures of Buster the Bus! This collection of Go Buster videos includes "Stuck In The Mud", "Buster''s New Tires" and more.'),
(2332, N's2332', N'MOVIE', N'Go Buster - Adventures of Buster the Bus', NULL, 2018, N'ALL', 23, N'MINUTES', N'23 min', N'Buster the Bus is the smallest, youngest, yellow bus in town. When he finds himself in close scrapes his courage and bravery will help save the day. Follow Buster learn about being cleaned in the car wash, rescuing his friends from the storm and even how to decorate a Christmas tree!'),
(2333, N's2333', N'MOVIE', N'Glove And Boots - Goofs And Laughs', NULL, 2019, N'7+', 34, N'MINUTES', N'34 min', N'Glove and Boots is a puppet-based video blog. The two main characters are a red, bearded humanoid named Mario , and an anthropomorphic groundhog named Fafa. In this collection of videos, Mario and Fafa go off script and test out their improvisational skills!'),
(2334, N's2334', N'TV_SHOW', N'Gloriavale', NULL, 2014, N'ALL', 1, N'SEASONS', N'1 Season', N'In this series we visit Gloriavale, a closed community of Christian fundamentalists living on New Zealand''s isolated West Coast. This is a world untouched by feminism, where women live in submission to men, welcome every baby as a gift from God, and work each day for the benefit others while they wait for the world to end. Dwell into this isolated community through this three part series.'),
(2335, N's2335', N'MOVIE', N'Glitch', NULL, 2015, N'18+', 92, N'MINUTES', N'92 min', N'When Will and Harper''s game is illegally cloned, they seek an attorney. Hiring "golden boy" Keith, their chances look good. Then Will starts to fall for Sophie, who happens to be Keith''s girlfriend. This conflict of interest pits Will between his heart and both his work and best friend.'),
(2336, N's2336', N'TV_SHOW', N'Glee', NULL, 2015, N'TV-PG', 7, N'SEASONS', N'7 Seasons', N'GLEE takes its final bow with a sixth and final 13-episode season. GLEE airs Fridays at 8/7c on FOX.'),
(2337, N's2337', N'MOVIE', N'Gleason', NULL, 2016, N'R', 111, N'MINUTES', N'111 min', N'At the age of 34, Steve Gleason, former NFL defensive back and New Orleans hero, was diagnosed with ALS. Doctors gave him two to five years to live. So that is what Steve chose to do: live. This film incorporates personal video journals from Gleason for his then-unborn son to footage of his adventures undertaken as part of his mission to live his life to the fullest.'),
(2338, N's2338', N'MOVIE', N'Gladiators of Rome', NULL, 2012, N'PG', 94, N'MINUTES', N'94 min', N'A hero is born in this animated adventure! Timo, a student at the Gladiators Academy, has no desire to become a gladiator until Lucilla walks into his life. With help from his pals, Timo is determined to be the gladiator of her dreams.'),
(2339, N's2339', N'MOVIE', N'Girlz', NULL, 2019, N'13+', 135, N'MINUTES', N'135 min', N'An 18 year teenager Mati, wants to live a bold life like many other girls. Her mother realizes this & imposes restrictions on her. She feels dejected and thinks her life has become boring and worthless. She embarks on a solo trip to Goa & makes friends with two more young girls of her age, who comes from different family backgrounds.'),
(2340, N's2340', N'TV_SHOW', N'Girls'' Last Tour', NULL, 2017, N'TV-14', 1, N'SEASONS', N'1 Season', N'In a future where most of humanity has perished, two young girls explore the ruins of civilization looking for food and fuel.'),
(2341, N's2341', N'MOVIE', N'Girls In Chains', NULL, 1943, N'NR', 70, N'MINUTES', N'70 min', N'When a teacher loses her job because her brother-in-law is a racketeer, she takes a position at a girls'' reformatory.'),
(2342, N's2342', N'MOVIE', N'Girls in Chains', NULL, 1943, N'18+', 77, N'MINUTES', N'77 min', N'In this murder mystery revolving around a prison, a detective helps a female inmate obtain evidence on her crooked brother-in-law in order to put him behind bars. Her sister had recently been fired from her job due to her marriage to the crook, and she takes a job teaching at the reformatory. The two sisters join forces to gather enough evidence to put him, and the shady school superintendant, away for good.'),
(2343, N's2343', N'MOVIE', N'Girlfriends of Christmas Past', NULL, 2016, N'13+', 92, N'MINUTES', N'92 min', N'When three hilarious, strong-willed women join forces to seek the ultimate revenge on their cheating ex at his upcoming holiday retreat, lovestruck event planner Livvy meets Carter, the charming colleague organizing it all, leaving Livvy to question if she can leave off their revenge scheme long enough to finally forgive her ex and let a real holiday romance blossom.'),
(2344, N's2344', N'TV_SHOW', N'Girl/Girl Scene Flashback', NULL, 2011, N'TV-MA', 1, N'SEASONS', N'1 Season', N'Flashback to the early 2010''s and learn the backstory of the hit lesbian TV series Girl/Girl Scene! Made on a zero budget, this award-winning show tells the story of Evan, Maxine, and Jessie - three lesbians who break all the rules. Along with Elliott, Jessie''s transgender best friend, and Jessie''s mom Susan, their love stories entwine and the drama unfolds.'),
(2345, N's2345', N'TV_SHOW', N'Girl/Girl Scene', NULL, 2017, N'18+', 2, N'SEASONS', N'2 Seasons', N'Girl/Girl Scene is the sexy, award-winning lesbian drama series that shocked the world with its provocative vision of life as a modern gay girl. Follow bad-girl Evan, escort Avery, Southern belle Maxine, stoner Bender and teenage runaway Ling as they navigate their passionate and intertwining love lives.'),
(2346, N's2346', N'MOVIE', N'Girl Who Came Back', NULL, 1935, N'PG', 69, N'MINUTES', N'69 min', N'Gilda Gillespie (Grey), part of a gang of counterfeiters, decides to leave her life of crime and start over in a new city as Mary Brown. She manages to get a job as a bank teller, and begins a romance with fellow co-worker Bill Rhodes (Blackmer). However, her past catches up with her when her former gangster friends robs her bank, recognize her, and decide to kidnap Bill to blackmail Mary into helping them again. Mary is forced to confess her past sins to the police, and together they try to concoct a plan to rescue Bill and capture the gang members. The film ends with a wild and exciting chase, unusual for a Chesterfield movie.'),
(2347, N's2347', N'MOVIE', N'Gina Yashere: Skinny B*tch', NULL, 2008, N'18+', 58, N'MINUTES', N'58 min', N'Witty, razor-sharp observations abound in this stand-up performance from Gina Yashere. From bits about her mom and men, to colonic irrigation and luggage this special leaves no stone unturned.'),
(2348, N's2348', N'MOVIE', N'Gina Yashere: Laughing To America', NULL, 2014, NULL, 68, N'MINUTES', N'68 min', N'Filmed live in San Francisco, CA, UK''s premier black female comedian, Gina Yashere, has come to America! Her unique take on being a cultural insider and outsider never fails to raise the roof as she gives us her take on the news gripping the nation.'),
(2349, N's2349', N'TV_SHOW', N'Gina Brillon: The Floor is Lava', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'Gina Brillon has always had a unique approach to life’s ups and downs; handling them with a humor and sass that comes naturally to the Bronx born Latina. In her third stand up special, Brillon holds no punches when discussing her childhood, culture and the transition from single to married life with her Midwestern husband.'),
(2350, N's2350', N'MOVIE', N'Gimme Danger', NULL, 2016, N'R', 109, N'MINUTES', N'109 min', N'Jim Jarmusch’s new film GIMME DANGER chronicles the story of The Stooges, one of the greatest rock-n-roll bands of all time.'),
(2351, N's2351', N'MOVIE', N'Gil Mantera''s Party Dream', NULL, 2011, N'NR', 55, N'MINUTES', N'55 min', N'Bright costumes, vocoder, and retro dance tunes from this partying duo, Gil Mantera''s Party Dream.'),
(2352, N's2352', N'MOVIE', N'Ghosts On The Loose', NULL, 1943, N'PG', 65, N'MINUTES', N'65 min', N'The East Side Kids try to fix up a house for newlyweds, but find the place next door "haunted" by mysterious men.'),
(2353, N's2353', N'TV_SHOW', N'Ghost Town History with Ken and Brenda Gallacher', NULL, 2021, N'7+', 1, N'SEASONS', N'1 Season', N'In this episode of Ghost Town History Ken and Brenda Gallacher explore the mining town Silver Reef Utah and the Jarvie Ranch located in the far northeastern corner of Utah. They also look at the light line that was developed in the 1920''s to create national airmail service in the Historical ByWay.'),
(2354, N's2354', N'MOVIE', N'Ghost Team One', NULL, 2013, N'R', 84, N'MINUTES', N'84 min', N'When Brad and Sergio accidentally arouse the dead, they team up with sexy amateur ghost hunter, Fernanda. They soon discover the horny demon wants in on the action in this outrageous romp where only one thing is certain: someone is gonna get screwed.'),
(2355, N's2355', N'TV_SHOW', N'Ghost Stories', NULL, 2001, N'18+', 1, N'SEASONS', N'1 Season', N'When nearby construction disturbs a spiritual resting place, it''s disgruntled denizens do what any supernatural being would do after a rude awaking - they terrorize the local school. And that means it''s up to a scruffy band of young ghost hunters to expel their satanic schoolmates before everyone gets sent to permanent detention!'),
(2356, N's2356', N'MOVIE', N'Ghost of New Orleans', NULL, 2011, N'R', 98, N'MINUTES', N'98 min', N'In post-Katrina New Orleans, a disgraced detective encounters the ghost of a murdered woman who wants to help him identify her killer.'),
(2357, N's2357', N'TV_SHOW', N'Ghost Inside My Child - Special', NULL, 2016, N'TV-14', 1, N'SEASONS', N'1 Season', N'Children of all ages who claim they remember previous lives are quite common and hundreds of these accounts have been scientifically documented, researched and studied.'),
(2358, N's2358', N'MOVIE', N'Ghost in the Graveyard', NULL, 2019, N'16+', 93, N'MINUTES', N'93 min', N'Small town kids witness a death during a game of "Ghost in the Graveyard" only to be terrorized by the same unhappy spirit when they become teens.'),
(2359, N's2359', N'MOVIE', N'Ghost Hour', NULL, 2014, N'ALL', 7, N'MINUTES', N'7 min', N'Just like every other night, the ghost goes out to haunt and spook every one. Just like every other night,the little girl has to eat the healthy porridge that she doesn''t like. And this time it so happens that the girl and the ghost meet, and the girl doesn''t really want to be afraid of the ghost. So, they can''t do anything but laugh about misunderstandings and... become friends.'),
(2360, N's2360', N'MOVIE', N'Ghawre Bairey Aaj', NULL, 2019, N'16+', 134, N'MINUTES', N'134 min', N'A modern retelling of Rabindranath Tagore''s classic novel, the film chronicles a triangular love story which is as much a story of passionate romance as it is of clashing ideologies.'),
(2361, N's2361', N'MOVIE', N'Ghajinikanth', NULL, 2018, N'ALL', 138, N'MINUTES', N'138 min', N'The main plot of Ghajinikanth revolves around a youngster named Rajinikanth. Everything is perfect for him, but the fact that he has some issues with his memory and mind diversion problems pulls his prospects down. More often, he faces a lot of backlashes because of this issue.'),
(2362, N's2362', N'MOVIE', N'Getting to Know You', NULL, 2020, N'18+', 103, N'MINUTES', N'103 min', N'When his drunken ex-girlfriend won''t leave him alone, a man asks a married woman staying at the same hotel to pretend to be his wife in this delightful comedy about an unforgettable weekend.'),
(2363, N's2363', N'TV_SHOW', N'Getting On', NULL, 2012, N'TV-14', 3, N'SEASONS', N'3 Seasons', N'Getting On returns for more dark humor among the bedpans; set in the backwaters of the National Health Service this third season sees King Edwards closed and Den, Kim and Dr Moore transferred 12 miles to a newer ward. Cuts, re-structuring and life events once again dominate the daily grind.'),
(2364, N's2364', N'MOVIE', N'Getting Go: The Go Doc Project', NULL, 2014, N'18+', 91, N'MINUTES', N'91 min', N'After becoming infatuated with a beautiful New York go-go dancer, college boy Doc devises a plan to get close to his crush by asking him to be the main subject in a makeshift documentary. But as they grow closer, flirtation blurs the line between subject and filmmaker and Doc is confronted with more than he could ever have imagined.'),
(2365, N's2365', N'MOVIE', N'Get Duked!', NULL, 2020, N'16+', 87, N'MINUTES', N'87 min', N'Get Duked is an anarchic, hip-hop inspired comedy that follows four city boys on a wilderness trek as they try to escape a mysterious huntsman.'),
(2366, N's2366', N'MOVIE', N'Get A Job', NULL, 2020, N'16+', 91, N'MINUTES', N'91 min', N'Unemployed and living with the mother-in-law from hell, a young comedian and his childhood friend are sucked into the ride of their lives when they decide there is no time like the present to pursue their dreams of opening a comedy club.'),
(2367, N's2367', N'MOVIE', N'George Carlin: You Are All Diseased', NULL, 2003, N'18+', 63, N'MINUTES', N'63 min', N'"You Are All Diseased" is a new collection of Carlin comedy never before seen on home video. The hilarious routines include "Airport Security," "Fear of Germs," " Businessmen," and "Religion."'),
(2368, N's2368', N'MOVIE', N'Gentle Midnight Rain black screen 9 hours', NULL, 2017, N'ALL', 541, N'MINUTES', N'541 min', N'One of our most popular sleep videos is now available with a completely black screen to help you enjoy a deep, restful and rejuvenating slumber. The total black screen eliminates the blue-spectrum light that generates melatonin and inhibits REM sleep. All Sharecare Windows programs are included in your Prime membership.'),
(2369, N's2369', N'MOVIE', N'Gentle evening rain', NULL, 2016, N'ALL', 541, N'MINUTES', N'541 min', N'Beautiful and relaxing film shot on location in la Antigua in the central highlands of Guatemala, overlooking the active Volcán de Fuego. Soothing rainstorm, recorded on location, encourages healthy sleep patterns with dark-screen to reduce the REM-sleep-inhibiting blue spectrum light emitted from most screens. Sharecare Windows'' Sleepwell programs are included with your Prime Membership.'),
(2370, N's2370', N'MOVIE', N'Generation Wealth', NULL, 2018, N'18+', 106, N'MINUTES', N'106 min', N'Lauren Greenfield’s postcard from the edge of the American Empire captures a portrait of a materialistic, image-obsessed culture. Simultaneously personal journey and historical essay, the film bears witness to the global boom–bust economy, the corrupted American Dream, and the human costs of late stage capitalism, narcissism, and greed.'),
(2371, N's2371', N'TV_SHOW', N'Generation War', NULL, 2014, N'13+', 1, N'SEASONS', N'1 Season', N'Valor, courage, and betrayal come to the fore in this remarkable epic that shows the everyday realities of wartime life from a deeply personal perspective. Billed as a German Band of Brothers, Generation War vividly depicts the lives of five young German friends forced to navigate the unconscionable moral compromises of life under Hitler'),
(2372, N's2372', N'MOVIE', N'Generation Aami', NULL, 2018, N'13+', 119, N'MINUTES', N'119 min', N'This is a coming-of-age story of friendship, parenting, growing up and finding yourself. A 17-year-old boy''s relationship with his parents is tested as he discovers teenage rebellion and fun in the company of a cool but troubled 19-year-old girl who shakes things up giving him the courage to be true to himself.'),
(2373, N's2373', N'MOVIE', N'Gecko''s Wonderful Vehicles', NULL, 2019, N'ALL', 39, N'MINUTES', N'39 min', N'Beep Beep! Gecko loves to learn with cars trucks and buses, and you can too in this fantastic collection of vehicle-based Gecko''s Garage videos!'),
(2374, N's2374', N'MOVIE', N'Gecko''s Garage Vol. 4', NULL, 2019, N'ALL', 40, N'MINUTES', N'40 min', N'Gecko and his friends love having fun adventures. Join in with this collection of Gecko''s Garage videos, including "Bobby the Bus is Stuck in the Snow!" and lots more!'),
(2375, N's2375', N'MOVIE', N'Gecko''s Garage Vol. 1', NULL, 2019, N'ALL', 48, N'MINUTES', N'48 min', N'Come and join Gecko as he introduces you to his friends Rick the road roller, Mia the mini digger, Maisie the mower, Oscar the old bus and more!'),
(2376, N's2376', N'MOVIE', N'Gecko''s Garage Vol 2', NULL, 2019, N'ALL', 41, N'MINUTES', N'41 min', N'Gecko''s garage is here to present you some of his closest friends! Come and join him as they sing songs, drive around the town and more!'),
(2377, N's2377', N'MOVIE', N'Gecko''s Garage Real Vehicles Volume 2 (Trucks, Construction and Large Vehicles)', NULL, 2019, N'ALL', 35, N'MINUTES', N'35 min', N'Gecko visits lots of big vehicles and trucks in this learning series for children. This Gecko''s Real Vehicles compilation features excavators, a truck wash, and many more exciting vehicles!'),
(2378, N's2378', N'MOVIE', N'Gecko''s Garage Real Vehicles Volume 1 (Cars, Ambulance, etc)', NULL, 2019, N'ALL', 40, N'MINUTES', N'40 min', N'Gecko visits lots of big vehicles and trucks in this learning series for children. In this compilation, Gecko''s Real Vehicles features a brand new electric car, electric bus, and lots more!'),
(2379, N's2379', N'TV_SHOW', N'Gecko''s Garage 3D - Vehicle Cartoons for Kids', NULL, 2021, N'ALL', 1, N'SEASONS', N'1 Season', N'Enjoy this collection of educational kids cartoons with the all-new 3D Gecko''s Garage! Gecko will help children learn colors, learn shapes, learn numbers, learn the alphabet and much more. In this collection, watch as Gecko gets Frozen, Baby Truck Loses Her Dummy and many more educational adventures.'),
(2380, N's2380', N'MOVIE', N'Gecko''s Garage - Trucks Cartoon for Kids', NULL, 2019, N'ALL', 33, N'MINUTES', N'33 min', N'Join Gecko''s Garage as he introduces you to his truck friends Max the monster truck, Fiona the fire truck, Rebecca the recycling truck, and more!'),
(2381, N's2381', N'MOVIE', N'Gatling Gun', NULL, 1973, N'13+', 105, N'MINUTES', N'105 min', N'Doctor Gatling invented a war machine to beat all arrows, and guns.'),
(2382, N's2382', N'MOVIE', N'Gascoigne', NULL, 2015, N'16+', 87, N'MINUTES', N'87 min', N'Celebrating the life and achievements of naturally gifted Paul Gascoigne, a legendary young English soccer player who won the hearts of the English nation. From his humble beginnings through to his international stardom within the football world .The documentary features interviews with soccer legends Vinnie Jones, Gary Lineker, José Mourinho and Wayne Rooney.'),
(2383, N's2383', N'MOVIE', N'Gary Owen: Breakin'' Out The Park', NULL, 2008, N'18+', 48, N'MINUTES', N'48 min', N'In this brutally honest stand-up performance Owen confesses his hilarious history of growing up in and around trailer parks. Owen packs a comedic punch and this incredible live performance is not to be missed!'),
(2384, N's2384', N'MOVIE', N'Gary Gulman: In This Economy?', NULL, 2012, N'18+', 61, N'MINUTES', N'61 min', N'In this stand-up special, money is a wellspring for the comedy of funnyman Gary Gulman, who aims darts at the uberwealthy, including Donald Trump.'),
(2385, N's2385', N'MOVIE', N'Gary Gulman: Boyish Man', NULL, 2005, N'18+', 58, N'MINUTES', N'58 min', N'Gary Gulman, delivers with his clever wit and handsome boyish charm. Boyish Man features Hanukkah vs Christmas, all kinds of cookies (and crackers) dating, sex and everything in between.'),
(2386, N's2386', N'TV_SHOW', N'Garfield Specials', NULL, 1990, N'TV-G', 1, N'SEASONS', N'1 Season', N'Includes 9 Garfield Specials: A Garfield Christmas, A Garfield Thanksgiving, Garfield Gets A Life, Garfield Goes Hollywood, Garfield and His 9 Lives, Garfield In Paradis, Garfield In The Rough, Garfield''s Babes and Bullets, and Garfield''s Feline Fantasies.'),
(2387, N's2387', N'TV_SHOW', N'Gardeners'' World', NULL, 2017, N'TV-G', 2, N'SEASONS', N'2 Seasons', N'This long-running BBC show is packed with gardening ideas, tips and advice from experts.'),
(2388, N's2388', N'TV_SHOW', N'Garden Invaders', NULL, 2000, N'13+', 1, N'SEASONS', N'1 Season', N'Quiz show in which contestants battle to win items for a horticultural makeover.'),
(2389, N's2389', N'TV_SHOW', N'Gangstars (Telugu)', NULL, 2018, N'18+', 1, N'SEASONS', N'1 Season', N'Gangstars is set in the genre of "Jaane Bhi Do Yaaron". This 12-episode series revolves around two movie stars, two ex-lovers, and a ruthless gangster. It''s a dark comedy of interconnecting events and interconnecting lives, stemming from one incident that turns into a roller coaster ride for the characters involved!'),
(2390, N's2390', N'TV_SHOW', N'Gangstars (Tamil)', NULL, 2018, N'18+', 1, N'SEASONS', N'1 Season', N'Gangstars is set in the genre of "Jaane Bhi Do Yaaron". This 12-episode series revolves around two movie stars, two ex-lovers, and a ruthless gangster. It''s a dark comedy of interconnecting events and interconnecting lives, stemming from one incident that turns into a roller coaster ride for the characters involved!...'),
(2391, N's2391', N'TV_SHOW', N'Gangstars (Hindi)', NULL, 2018, N'13+', 1, N'SEASONS', N'1 Season', N'Gangstars is set in the genre of "Jaane Bhi Do Yaaron". This 12-episode series revolves around two movie stars, two ex-lovers, and a ruthless gangster. It''s a dark comedy of interconnecting events and interconnecting lives, stemming from one incident that turns into a roller coaster ride for the characters involved!'),
(2392, N's2392', N'MOVIE', N'Gangsta', NULL, 2018, N'18+', 125, N'MINUTES', N'125 min', N'The lives of four dealer friends spin out of control when they steal a shipment of cocaine. They trigger a full out war between them, an Amsterdam drug lord and the Colombian cartels.'),
(2393, N's2393', N'MOVIE', N'Gallowwalkers', NULL, 2013, N'R', 93, N'MINUTES', N'93 min', N'A mysterious gunman, Aman (Snipes), is the son of a nun who breaks her covenant with God to ensure his survival. This act brings a curse upon Aman - all those that die by his gun will return. Soon, he is hunted by a gang of his undead former victims, led by the vicious Kansa. Aman enlists Fabulos, a new young warrior, to fight by his side.'),
(2394, N's2394', N'MOVIE', N'Gallagher: We Need A Hero', NULL, 1992, N'13+', 58, N'MINUTES', N'58 min', N'Accompanied on stage by easily recognizable dummies of public figures, Gallagher claims "We Need A Hero" because so many of our politicians, queens and sports figures have let us down. Filmed in York, PA in 1992.'),
(2395, N's2395', N'MOVIE', N'Gallagher: The Bookkeeper', NULL, 1985, N'13+', 58, N'MINUTES', N'58 min', N'In his 1985 special, Gallagher talks how we unwisely spend our hard-earned cash. And of course he isn''t really the bookkeeper, but he does know the three things that appeal to everyone: Money, Money, and Money. But forget all that...here comes the amazing Sledge-o-Matic!'),
(2396, N's2396', N'MOVIE', N'Gallagher: That''s Stupid', NULL, 1982, N'16+', 63, N'MINUTES', N'63 min', N'In 1982 Gallagher had a lot on his mind. Forever the prop comedian, Gallagher points out all the things that annoy him - from the post office, to kitchen habits, to the media, no one is safe from his list.'),
(2397, N's2397', N'MOVIE', N'Gallagher: Stuck In the 60s', NULL, 1983, NULL, 58, N'MINUTES', N'58 min', N'Wacky, prop-laden comedian Gallagher rollerskates on stage, waxes philosophically about shoes and then jokes about coming of age in the sixties. Ending with the one, the only: Sledge-o-Matic routine.'),
(2398, N's2398', N'MOVIE', N'Gallagher: Sledge-O-Matic', NULL, 2000, N'16+', 54, N'MINUTES', N'54 min', N'Lock up your watermelons, and anything else that splatters! With a name like ''Sledge-O-Matic'' you know Gallagher is sure to get crazy in this special filmed in 2000!'),
(2399, N's2399', N'MOVIE', N'Gallagher: Over Your Head', NULL, 1984, N'13+', 58, N'MINUTES', N'58 min', N'Gallagher performs his ever-famous zany antics in Texas. Complete with a magical blimp ride over the rainbow, Gallagher takes you on an intelligent and wacky journey. Take a trip to the insane with Gallagher in a sea of laughter and Sledge-O-Matic goo!'),
(2400, N's2400', N'MOVIE', N'Gallagher: Melon Crazy', NULL, 1984, NULL, 58, N'MINUTES', N'58 min', N'A concert by stand-up comic, Gallagher, featuring his usual plays on words and his patented bizarre use of props, climaxing with a new use for watermelons.');




One day, 17-year-old Arato Endo meets the android Lacia and becomes her owner.
She is one of five androids with advanced AI.
Each of the five units have their own motivations, and fight to gain each other''s abilities.
What will the relationship between man and machine be moving forward?
That is something Arato must find.'),
(3126, N's3126', N'MOVIE', N'Beaten', NULL, 2005, N'16+', 59, N'MINUTES', N'59 min', N'Robson Green and Saira Todd star in a powerful love story exploring the roots of domestic violence.'),
(3127, N's3127', N'TV_SHOW', N'Beat', NULL, 2018, N'18+', 1, N'SEASONS', N'1 Season', N'Nobody in Berlin''s techno scene is better connected than club promoter Robert Schlag, aka Beat. In order to get to the masterminds of a criminal network, Beat is recruited by the European Secret Service. On the hunt for the masterminds behind the organized organ trafficking, the past catches up with Beat who quickly reaches his personal limits...'),
(3128, N's3128', N'MOVIE', N'Beast Mode', NULL, 2020, NULL, 89, N'MINUTES', N'89 min', N'After accidentally killing his lead star, has-been Hollywood producer turns to an ancient herbal elixir, in the hope it will save his career. Making a dark deal, he unleashes a band of bloodthirsty, shape-shifting, ferocious beasts on LA.'),
(3129, N's3129', N'TV_SHOW', N'Bear''s Wild Weekends', NULL, 2012, N'TV-G', 1, N'SEASONS', N'1 Season', N'Bear Grylls takes Miranda Hart & Jonathan Ross, two of Britain''s most high-profile stars, on once-in-a-lifetime adventures over two amazing weekend expeditions to some of the world''s most stunning natural environments.'),
(3130, N's3130', N'MOVIE', N'Bear With Us', NULL, 2017, NULL, 95, N'MINUTES', N'95 min', N'In an effort to salvage his relationship, a well-meaning control freak drags his girlfriend to a romantic cabin in the woods. Hilarity ensues when a ravenous bear, an affable forest ranger, and a crazy woodsman repeatedly interrupt his elaborate attempts at a marriage proposal.'),
(3131, N's3131', N'MOVIE', N'Beaconsfield', NULL, 2012, N'13+', 129, N'MINUTES', N'129 min', N'The true story of Brant Webb and Todd Russell, who were trapped nearly a kilometer below the surface.'),
(3132, N's3132', N'TV_SHOW', N'Be the BOSS', NULL, 2013, N'TV-PG', 1, N'SEASONS', N'1 Season', N'Connecticut is home to some of the richest suburbs in America, but it''s also home to an infestation of white-tailed deer. Watch as Mike Andronaco and his crew keep the deer population at bay by hunting on the sprawling properties of wealthy landowners.'),
(3133, N's3133', N'MOVIE', N'Be Somebody', NULL, 2016, N'PG', 87, N'MINUTES', N'87 min', N'A Pop Superstar Matthew Espinosa eager to escape the burden of fame meets an independent small town girl with big dreams Sarah Jeffery. Together they embark on a unexpected journey of friendship first love and self discovery.'),
(3134, N's3134', N'MOVIE', N'Be Afraid', NULL, 2017, N'18+', 96, N'MINUTES', N'96 min', N'In order to protect his family, Dr. John Chambers must solve the town''s deadly secret, which lives within the darkest shadows of the night.'),
(3135, N's3135', N'MOVIE', N'BBC Television Shakespeare: The Tempest', NULL, 1980, N'13+', 124, N'MINUTES', N'124 min', N'BBC presents the classic play by William Shakespeare. Michael Hordern and Derek Godfrey star. Exiled, Prospero lives on a desolate island with his daughter, Miranda. When Prospero''s usurping brother sails by the island, Prospero conjures a storm that wrecks the ship and changes all of their lives.'),
(3136, N's3136', N'TV_SHOW', N'Battlezone WWII: Nazi Blitzkrieg-The Battle For France', NULL, 2015, N'13+', 1, N'SEASONS', N'1 Season', N'This Battlezone series features Blitzkrieg - the Nazi''s Conquest and Occupation of France, and the Struggle to Liberate it.'),
(3137, N's3137', N'MOVIE', N'Battle Creek Brawl', NULL, 1980, N'16+', 96, N'MINUTES', N'96 min', N'Filmed in the U.S., Battle Creek Brawl is Jackie Chan''s first crossover movie into the international arena! Chan stars as Jerry Kwan, a Korean man seeking fame and fortune in Chicago in the 1930s, when his serene life is turned upside-down.'),
(3138, N's3138', N'TV_SHOW', N'Battle 360', NULL, 2008, N'TV-PG', 1, N'SEASONS', N'1 Season', N'For nearly a decade, the legendary World War II aircraft carrier USS Enterprise held a pivotal place on the turbulent seas of war, engaging in some of the fiercest multifront battles ever witnessed in modern combat.'),
(3139, N's3139', N'TV_SHOW', N'BATTERY the animation (English Subtitled)', NULL, 2016, N'TV-NR', 1, N'SEASONS', N'1 Season', N'Takumi Harada is a talented baseball player. Takumi meets Go Nagakura, a catcher who can catch Takumi''s fastest pitches. They join the school baseball team and grow together as a battery unit. (C)2016 AtsukoAsano,KADOKAWA /Animation Battery Committee'),
(3140, N's3140', N'MOVIE', N'Batla House', NULL, 2019, N'13+', 139, N'MINUTES', N'139 min', N'An action thriller based on the 2008 police encounter in Delhi''s Batla House.'),
(3141, N's3141', N'MOVIE', N'Bastille - ReOrchestrated', NULL, 2021, N'16+', 71, N'MINUTES', N'71 min', N'A bracingly honest new documentary sourced from hundreds of hours of unseen archive and all-new conversations captured during the pandemic, the film features open and frank insights from each band member plus collaborators inextricably linked to the group''s orchestral adventures.'),
(3142, N's3142', N'MOVIE', N'Bastard''s Crossing', NULL, 2021, N'16+', 96, N'MINUTES', N'96 min', N'One of 12 Westerns made in 12 Months, Bastard''s Crossing tells the story of Cam Talcutt, a man who won a trading post in a card game. Now, he''s stuck in the wilderness trying to run it when he learns the freight company who supplies his store won''t be coming anymore. Cam is in a bad spot and might have to do bad things to survive.'),
(3143, N's3143', N'TV_SHOW', N'Basil Rathbone Sherlock Holmes in Color!', NULL, 1946, N'7+', 1, N'SEASONS', N'1 Season', N'Basil Rathbone''s portrayal of the iconic Sherlock Holmes is certainly one of the best. In this amazing series you will see Sherlock come to life in beautifully restored color!'),
(3144, N's3144', N'MOVIE', N'Bashful Bachelor', NULL, 1942, N'PG', 76, N'MINUTES', N'76 min', N'Shy Abner trades his delivery car for a race horse, hoping to win a big race and be a hero to a small town girl.'),
(3145, N's3145', N'TV_SHOW', N'Barter Kings', NULL, 2013, N'TV-PG', 2, N'SEASONS', N'2 Seasons', N'The series Barter Kings features 2 of the best barterers in the business as they trade up from low-value items to worth thousands more.'),
(3146, N's3146', N'MOVIE', N'Barry Brewer: Chicago, I''m Home', NULL, 2019, N'13+', 78, N'MINUTES', N'78 min', N'Taped in front of two sold out crowds at the Studebaker Theater in his hometown of Chicago; this stand up comedy special is the culmination of Barry''s real life experiences interwoven with over fifteen years as a stand up comic.'),
(3147, N's3147', N'TV_SHOW', N'Barney', NULL, 2009, N'TV-Y', 10, N'SEASONS', N'10 Seasons', N'Travel the world with Barney and his friends! The search is on for colorful eggs in Kenya, a music box in Switzerland, birds of paradise in Hawaii, and a dancing horse in Spain. Baby Bop brings her butterfly Monty to Mexico, while Barney introduces Rusty to China. And everyone puts on a show in Greece. Sing along to your favorite songs on this worldwide adventure with Barney and his friends.'),
(3148, N's3148', N'MOVIE', N'Barista', NULL, 2015, N'16+', 102, N'MINUTES', N'102 min', N'Once a year, thousands of baristas square off in competitions around the U.S., but only one will become the National Champion. BARISTA takes the viewer on a humorous, emotional and enlightening look into the unimaginable world of coffee competitions and the passionate, lovable and quirky characters that devote their lives to them.'),
(3149, N's3149', N'MOVIE', N'Barefoot Boy (1938)', NULL, 1938, N'NR', 60, N'MINUTES', N'60 min', N'The film stars Jackie Moran as Billy Whittaker, a country boy whose life is thrown into turmoil when arrogant reform-school graduate Kenneth Hale (Bradley Metcalf) arrives. Kenneth picks fights over everything Billy believes in, and the new boy even makes a play for Billy''s girlfriend Pige Blaine (Marcia Mae Jones). Eventually Kenneth changes his ways after a brief encounter involving a gang of bond swindlers from the big city. Kenneth finally becomes a "regular guy", but not before Billy uses his fists to persuade the boy of the error of his ways. Billy''s faithful dog is none other than Toto the Dog (aka Terry) from "Wizard of Oz" fame.'),
(3150, N's3150', N'MOVIE', N'Barbie: Dreamtopia Special (English)', NULL, 2019, N'ALL', 46, N'MINUTES', N'46 min', N'With the help of her older sister, Barbie, Chelsea visits the lands of Dreamtopia where she learns valuable life lessons.'),
(3151, N's3151', N'TV_SHOW', N'Barbie Dreamtopia (Spanish Audio)', NULL, 2018, N'TV-Y', 1, N'SEASONS', N'1 Season', N'Barbie and her little sister Chelsea travel through the whimsical worlds of Dreamtopia. Through the eyes of Chelsea''s imagination, viewers explore delicious and delightful worlds and meet colorful characters who live there.'),
(3152, N's3152', N'TV_SHOW', N'Barbie Dreamtopia', NULL, 2019, N'TV-Y', 1, N'SEASONS', N'1 Season', N'Join Barbie and Chelsea on magical adventures in Dreamtopia, as they transform into mermaids, fly over Sweetville with fairy bubble wings and take a ride on the back of the Elephant King of Sparkle Mountain.'),
(3153, N's3153', N'TV_SHOW', N'Barbie - Vlogger', NULL, 2020, N'ALL', 2, N'SEASONS', N'2 Seasons', N'Hey everyone, welcome to my vlog! I share information about my life, my inspirations and my favourite things! I love to do silly challenges with my friends Ken, Harper, and Ryan, and my sister Chelsea. I hope these vlogs inspire you to be anything you want to be. Remember - Positive Attitude Changes Everything.'),
(3154, N's3154', N'MOVIE', N'Bang The Drum Slowly', NULL, 1973, N'PG', 98, N'MINUTES', N'98 min', N'The story of the friendship between a star pitcher, wise to the world, and a half-wit catcher, as they cope with the catcher''s terminal illness through a baseball season.'),
(3155, N's3155', N'TV_SHOW', N'Bang Baaja Baaraat', NULL, 2015, N'16+', 1, N'SEASONS', N'1 Season', N'Two people from very different backgrounds fall in love and decide to get married, but not without their parents blessings. Three days before the wedding they introduce each other with their respective parents and all hell breaks loose. It is the story of two crazy families and one mental wedding.'),
(3156, N's3156', N'MOVIE', N'Bandobast', NULL, 2019, N'13+', 164, N'MINUTES', N'164 min', N'In a world of political rivalry and corporate expansion, competition for supremacy is prevalent. Amidst such harsh climate for dominance, the lives of visionaries and leaders are always under threat. This film is about the life of security guards for such men. The challenges that they face, the risks that they take and their personal life, friends and love.'),
(3157, N's3157', N'TV_SHOW', N'Bandish Bandits', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'Radhe a singing prodigy from a classical background & Tamanna, a pop sensation on the rise meet. Radhe''s world is turned upside down when he falls in love with Tamanna. Torn between helping her achieve stardom and staying true to his own music and his family’s legacy, will he succeed in juggling both or will he lose everything he has?'),
(3158, N's3158', N'TV_SHOW', N'Bananas in Pyjamas Live Action', NULL, 1992, N'7+', 1, N'SEASONS', N'1 Season', N'Bananas in Pyjamas is about two giant, child-like bananas, B1 and B2. They are good friends and companions. Together they live on Cuddles Lane, with their friends, the Teddy Bears: Amy, Morgan, and Lulu, the Rat-in-a-Hat, and various other critters. The bananas are constantly teasing the Teddy Bears, but those silly bananas are always able to foil the Rat''s sly tricks.'),
(3159, N's3159', N'TV_SHOW', N'Bananas in Pyjamas', NULL, 2013, N'ALL', 2, N'SEASONS', N'2 Seasons', N'Come down the stairs and join B1 and B2 in the second season of the beloved preschool series, featuring all new adventures in Cuddlestown. Together with their well-known friends: the teddies - Amy, Lulu and Morgan - Rat, as well as some new friends, our Bananas do what they love to do best: help each other, work together and have fun.'),
(3160, N's3160', N'TV_SHOW', N'BANANA FISH', NULL, 2018, N'TV-NR', 1, N'SEASONS', N'1 Season', N'Ash Lynx, a 17-year-old boy, is the boss of a street-kids gang in New York. One day, a man who was murdered before his eyes entrusts him with something.
And the last words uttered by that dying man was the phrase, ""BANANA FISH"". That is the word his brother, Griffin, often mutters. Ash has a destined encounter with Eiji, a kind Japanese boy who comes to New York as a cameraman assistant.'),
(3161, N's3161', N'TV_SHOW', N'Bali', NULL, 2013, N'TV-Y', 1, N'SEASONS', N'1 Season', N'From PBS KIDS: Bali, a resolutely modern preschooler, lives a resolutely modern life in the big city.'),
(3162, N's3162', N'MOVIE', N'Bail Out', NULL, 1990, N'PG-13', 88, N'MINUTES', N'88 min', N'A funny, and often outright silly, action comedy about three bounty hunters who must bring the daughter of a millionaire to trial on drug charges. Lots of action and some great one-liners.'),
(3163, N's3163', N'MOVIE', N'Baggy in & as KungFu Bonda: A Mostly English Stand Up Comedy Special (4K UHD)', NULL, 2020, N'16+', 78, N'MINUTES', N'78 min', N'Baggy takes you on a hilarious journey about growing older, the changes it brings and coming to terms with it. His observations on adulting, parents, marriage, sex and grill gates will leave you in splits, while his anecdotal stories will keep you gripped through the show. Guaranteed to leave you laughing, content and hopefully a little more at peace with your own life''s developments.'),
(3164, N's3164', N'MOVIE', N'Badge of Honor', NULL, 1934, N'PG', 84, N'MINUTES', N'84 min', N'Spoiled wealthy playboy Bob Gordon (Crabbe) ends up in a small town overrun by corrupt local politicians. When Bob meets pretty Helen Brewster, he decides to pose as a newspaper reporter and try to gather enough evidence to put the crooked politicians in jail. Along the way, Bob gets himself into a number of touchy predicaments before succeeding in his endeavour, and winning the girl. Once thought to be a lost Buster Crabbe film, fans will be excited at its discovery.'),
(3165, N's3165', N'MOVIE', N'Bad Seed', NULL, 2000, N'R', 92, N'MINUTES', N'92 min', N'Preston Tylk is an ordinary guy living in Seattle. When he discovers that his wife, Emily, whom he adores, is having an affair, he is devastated. Storming out of the house, he returns later only to find her brutally murdered.'),
(3166, N's3166', N'MOVIE', N'Bad Match', NULL, 2017, NULL, 83, N'MINUTES', N'83 min', N'An internet-dating playboy''s life spirals out of control after meeting a woman online.'),
(3167, N's3167', N'MOVIE', N'Bad Kids of Crestview Academy', NULL, 2017, N'R', 101, N'MINUTES', N'101 min', N'Based on the best-selling graphic novel series, a group of spoiled "bad kids" have been placed in Saturday detention at the prestigious Crestview Academy. After one of the kids locks away their teacher,they find themselves trapped in school with no way out, wondering who (or what) set them up. Their ranks quickly dwindle as each falls victim to a gruesome "accident" while trying to escape.'),
(3168, N's3168', N'TV_SHOW', N'Bad Ink', NULL, 2014, N'TV-14', 2, N'SEASONS', N'2 Seasons', N'Set against the glitzy backdrop of Las Vegas, also known as "the mistake capital of the world," Bad Ink is a buddy comedy featuring renowned tattoo artist Dirk Vermin and his trusted sidekick and best friend of 20 years, Ruckus.'),
(3169, N's3169', N'MOVIE', N'Bad Company', NULL, 1972, N'PG', 93, N'MINUTES', N'93 min', N'A group of naive boys find that life as desperadoes in the west is more serious that they understood when they embark on abortive careers in bushwhacking. Violence, betrayal, sombre colours and a Beckettsian whimsy mark this ironic western.'),
(3170, N's3170', N'MOVIE', N'Bad Asses on the Bayou', NULL, 2015, N'R', 85, N'MINUTES', N'85 min', N'Frank Vega (Danny Trejo)) and Bernie Pope (Danny Glover) return, this time to Louisiana in an attempt to find a kidnapped friend.'),
(3171, N's3171', N'MOVIE', N'Bad Ass 2: Bad Asses', NULL, 2014, N'R', 91, N'MINUTES', N'91 min', N'Frank Vega (Danny Trejo) teams up with grumpy old agoraphobic Bernie Pope (Danny Glover) to kick ass and clean up the streets of L.A.'),
(3172, N's3172', N'MOVIE', N'Bad Ass', NULL, 2012, N'R', 90, N'MINUTES', N'90 min', N'A Vietnam veteran who becomes a local hero after saving a man from attackers on a city bus decides to take action when his best friend is murdered and the police show little interest in solving the crime.'),
(3173, N's3173', N'MOVIE', N'Backtrack', NULL, 1990, N'R', 100, N'MINUTES', N'100 min', N'Jodie Foster stars as Anne Benton, an artist who sees what she shouldn''t - a mob assassination.'),
(3174, N's3174', N'MOVIE', N'Back Page', NULL, 1934, N'18+', 63, N'MINUTES', N'63 min', N'Peggy Shannon plays a young female reporter who is fired from a big city newspaper, then decides to take over a troubled small town newsppaer. She encounters difficulties with small town politics, getting advertisers to help keep the paper afloat, and issues with 1930''s feminism in the resistance she receives from the town''s residents in her abilities to run the newspaper. An insightful story of a woman''s determination to succeed in an era long before the women''s rights movement.'),
(3175, N's3175', N'MOVIE', N'Babysitters Beware', NULL, 2012, N'PG', 72, N'MINUTES', N'72 min', N'Danny is the perfect kid; the only problem is he doesn''t have the perfect parents. Desperate to spend more time with his busy mom and dad, Danny and his friend Marco develops the ultimate master plan. With each antic crazier than the last, the film follows the duo on a hilarious and totally entertaining night of being very bad.'),
(3176, N's3176', N'TV_SHOW', N'BABYLON', NULL, 2020, N'TV-NR', 1, N'SEASONS', N'1 Season', N'Everyone knows that life is good. But what if that belief was shown to be wrong one day? Don’t miss the long-awaited animated version of Mado Nozaki’s sensational novel, which critics have described as a poison that enters your body when you read it! This story follows Zen Seizaki from the Tokyo District Public Prosecutors Office as he investigates a scandal involving a pharmaceutical company.'),
(3177, N's3177', N'TV_SHOW', N'BabyBus - Super Rescue Team', NULL, 2018, N'ALL', 1, N'SEASONS', N'1 Season', N'Super Rescue Team is one of the most popular animation series done by BabyBus. The episode focuses on the Super Rescue Team composed of baby panda Kiki, Miumiu, and their partners, whose mission is to build a beautiful home. Whenever the city is faced with various problems, they will use cool equipment to complete difficult tasks.'),
(3178, N's3178', N'MOVIE', N'BabyBus - Nursery Rhymes & Kids Songs (VOLUME 3)', NULL, 2020, N'ALL', 25, N'MINUTES', N'25 min', N'At BabyBus, our goal is to make learning a fun experience for kids aged 2 - 5 by creating classic nursery rhymes, kids songs, and stories with 2D & 3D animations. Children get to learn good habits, safety knowledge, letters, colors, numbers, and more by singing and dancing with our characters! Enjoy watching our videos!'),
(3179, N's3179', N'TV_SHOW', N'Baby U Series', NULL, 2015, N'ALL', 1, N'SEASONS', N'1 Season', N'Class is in session! Join BabyU for all the basic fundatmentals for your baby including language, counting, art exploration and more.'),
(3180, N's3180', N'TV_SHOW', N'Baby U (Spanish audio)', NULL, 2018, N'ALL', 1, N'SEASONS', N'1 Season', N'It''s learning 101 for your little one! Join in and count from 1 to 5, learn about farm animals, and explore colors, too. Spanish audio.'),
(3181, N's3181', N'MOVIE', N'Baby Shark & More Kids Songs - Little Baby Bum', NULL, 2019, N'ALL', 48, N'MINUTES', N'48 min', N'Little Baby Bum is a fun, educational children''s nursery rhyme channel watched globally by kids. Learn colors, shapes, numbers with some of our most well-loved characters! Sing along to some of the most classic nursery rhymes. This collection includes Halloween Baby Shark, Peekaboo, Bedtime Song, Name Song, and much more!'),
(3182, N's3182', N'MOVIE', N'Baby Pirates - The Golden Statue', NULL, 2016, N'G', 12, N'MINUTES', N'12 min', N'Avi, Mike, Nina and Xu are ordinary city babies. But when they enter the day care they become imaginary pirates going out on the seven seas for adventures It''s about friendship and learning. Baby Pirates are fun entertainment for the youngest audience (0-3yrs). This is the first episode. New episodes will be coming summer 2017.'),
(3183, N's3183', N'MOVIE', N'Baby Cat', NULL, 1986, N'R', 84, N'MINUTES', N'84 min', N'Baby Cat, a sultry tease and top Paris fashion model, plans an elaborate kidnapping. A climactic striptease by Baby Cat high-lights this fast-paced look into the world of jet setters, mansions, private beaches and lusty lives.'),
(3184, N's3184', N'MOVIE', N'Babru', NULL, 2019, N'13+', 106, N'MINUTES', N'106 min', N'Arjun (Mahi Hiremath) has to reach Vancouver to propose to his girlfriend. He discovers that his rental car named BABRU has already been given to Sana (Suman Nagarkar). He has no choice but to travel with her. Gu (Rey Tostado) hitches a ride with them. Rico (Sunny Moza) is on a killing spree as his love is held captive. The interesting twists, turns, journey and destiny form the story.'),
(3185, N's3185', N'TV_SHOW', N'Babies Behind Bars', NULL, 2018, N'TV-14', 1, N'SEASONS', N'1 Season', N'A staggering 7,500 babies are born behind bars each year in the US. In most cases, babies are separated from their mother immediately after birth. Currently there are 8 experimental prison nursery programs nationwide and we have exclusive access to 1 of them.'),
(3186, N's3186', N'MOVIE', N'Azeem Banatwalla: Cometh The Hour', NULL, 2016, N'18+', 60, N'MINUTES', N'60 min', N'Azeem Banatwalla is back with jokes and observations about the perils of married life, road rage, millennials, and confused African kids.'),
(3187, N's3187', N'MOVIE', N'Ayogya', NULL, 2019, N'13+', 148, N'MINUTES', N'148 min', N'A corrupt police officer decides to alter his life choices and change his actions after her encounters the death of a young innocent child.'),
(3188, N's3188', N'TV_SHOW', N'Ax Men', NULL, 2016, N'TV-14', 2, N'SEASONS', N'2 Seasons', N'Ax Men Season 9 returns with even higher stakes and more danger at every turn. This season you''ll get a 360 degree view of what it takes to grow a logging empire. After losing King of the Mountain, Rygaard is on the brink of collapse while rival Papac Alaska may strike gold.'),
(3189, N's3189', N'TV_SHOW', N'Avocado Toast the series', NULL, 2020, N'TV-14', 1, N'SEASONS', N'1 Season', N'Avocado Toast is an intergenerational sex comedy exploring the comforts and awkwardness of sex from age 25 to 69. When it comes to millennials and baby boomers, these nuts haven''t fallen so far from the family tree.'),
(3190, N's3190', N'MOVIE', N'Avenging Squad (2015) Full Movie', NULL, 2015, N'13+', 5, N'MINUTES', N'5 min', N'The $0 remake of Marvel''s "The Avengers". The Captain (Logan Xavier) leads his team of heroes against an invading army of androids from space.'),
(3191, N's3191', N'TV_SHOW', N'Avatar: The Last Airbender', NULL, 2008, N'TV-Y7', 3, N'SEASONS', N'3 Seasons', N'Fire promises to be the most exciting season yet! Aang wakes up from his battle with Azula to discover that Ba Sing Se has fallen and the world thinks he''s dead. So he and his friends set off undercover to find Firelord Ozai before the Day of Black Sun.'),
(3192, N's3192', N'MOVIE', N'Ava''s Possessions', NULL, 2016, N'R', 87, N'MINUTES', N'87 min', N'A young woman recovers from a demonic possession.'),
(3193, N's3193', N'MOVIE', N'Author The JT LeRoy Story', NULL, 2016, N'R', 112, N'MINUTES', N'112 min', N'A look inside the mysterious case of 16-year-old literary sensation JT LeRoy – a creature so perfect for his time that if he didn''t exist, someone would have had to invent him. The strangest story about story ever told.'),
(3194, N's3194', N'MOVIE', N'Auschwitz: The Great Escape', NULL, 2007, N'13+', 46, N'MINUTES', N'46 min', N'Escape from Auschwitz uncovers the true story of the spectacular escape from the camp in 1944 by two young Slovak jews -Rudolf Vrba and Alfred Wetzler. The Nazi''s extermination plan relied on the truth about the camp''s purpose being kept secret from the outside world.'),
(3195, N's3195', N'MOVIE', N'Au Revoir Simone', NULL, 2011, N'NR', 31, N'MINUTES', N'31 min', N'Au Revoir Simone bring the rich, therapeutic, synthetic driven songcraft of The Bird of Music to Webster Hall for a haunting, hometown performance.'),
(3196, N's3196', N'MOVIE', N'Attack! The Battle Of New Britain', NULL, 1944, N'NR', 59, N'MINUTES', N'59 min', N'Documentary film depicting the attack by Allied forces on the Japanese strong-holds of Arawe Beach and Cape Gloucester, New Britain, in the South Pacific theatre of the Second World War in 1943.'),
(3197, N's3197', N'MOVIE', N'Atone', NULL, 2019, N'13+', 90, N'MINUTES', N'90 min', N'When head of security candidate Laura Ryan shows up for work at the largest church in America, she is forced to take down a team of hijackers determined to drain the mega church of everything it has.'),
(3198, N's3198', N'TV_SHOW', N'Atom: the Beginning', NULL, 2017, N'TV-14', 1, N'SEASONS', N'1 Season', N'Umataro Tenma and Hiroshi Ochanomizu are attempting to build a humanoid robot who not only looks like a human, but can feel like one. With no interested investors, they must pick up odd jobs to help fund their research.'),
(3199, N's3199', N'MOVIE', N'Atlas Shrugged: Part III', NULL, 2014, N'PG-13', 99, N'MINUTES', N'99 min', N'As crime and fear take over the countryside, the government continues to exert its brutal force against the nation''s most productive who are mysteriously vanishing - leaving behind a wake of despair.'),
(3200, N's3200', N'MOVIE', N'Atlas Shrugged: Part II', NULL, 2012, N'PG-13', 112, N'MINUTES', N'112 min', N'Railroad owner Dagny Taggart and steel mogul Hank Rearden search desperately for the inventor of a revolutionary motor as the U.S. government continues to spread its control over the national economy.');

However, the threat of the Empire looms once again.
With his trusty eagle Iskender, will Mahmut be able to thwart the threat of Balt-Rhein and bring peace to his nation?'),
(3308, N's3308', N'MOVIE', N'Alphabet City', NULL, 1984, N'R', 85, N'MINUTES', N'85 min', N'A 19 year-old New York City drug dealer is King of Alphabet City, 50 blocks of urban decay that houses an underground narcotics market, decides to get out of the business, but has to flee from mobsters.'),
(3309, N's3309', N'TV_SHOW', N'Alpha House', NULL, 2014, N'18+', 2, N'SEASONS', N'2 Seasons', N'An Amazon Original series: They work in the Senate. They live in the house - Alpha House. Created by Garry Trudeau (Doonesbury, Tanner ''88).'),
(3310, N's3310', N'MOVIE', N'Alonzo Bodden: Who''s Paying Attention?', NULL, 2011, N'18+', 60, N'MINUTES', N'60 min', N'"Last Comic standing" star Alonzo Bodden tackles the absurdity of pop culture and the decline of western civilization in this hilarious 2010 New York stand-up concert.'),
(3311, N's3311', N'MOVIE', N'Alonzo Bodden: Tall Dark And Funny', NULL, 2005, N'18+', 54, N'MINUTES', N'54 min', N'Alonzo touches upon every subject from tsuamis to terrorists, Democrats to desperate housewives, marriage to midgets, and more. Shot at the historic El Portal Theater in Los Angeles, Alonzo brings down the house with hilarious comedy.'),
(3312, N's3312', N'MOVIE', N'Alonzo Bodden: Historically Incorrect', NULL, 2016, N'18+', 62, N'MINUTES', N'62 min', N'Alonzo Bodden returns with a hilarious look at the historical inaccuracies of the present and past from his unique comedic perspective in Historically Incorrect.'),
(3313, N's3313', N'TV_SHOW', N'Alonzo Bodden: Heavy Lightweight', NULL, 2019, N'16+', 1, N'SEASONS', N'1 Season', N'In this day and age if it were all heavy it wouldn’t be a comedy special, it would be a depression special, and Alonzo Bodden is very aware of this. That’s why he goes back and forth, from Heavy to Lightweight, because he knows we need a break from news in comedy. He likes to mix it up and he hopes you will join him for a laugh and a think or two.'),
(3314, N's3314', N'MOVIE', N'Alone For Christmas', NULL, 2013, N'ALL', 88, N'MINUTES', N'88 min', N'When a family visits Grandma''s house on Christmas Eve, they leave their dog at home alone. And when burglars try to take the presents from under the tree, the dog must use every trick it knows to stop them'),
(3315, N's3315', N'TV_SHOW', N'Almost Royal', NULL, 2016, N'TV-MA', 2, N'SEASONS', N'2 Seasons', N'BBC America: British aristocrats, Georgie and Poppy Carlton, make their triumphant and highly-anticipated return to the United States to closely examine the subjects that define American life today.'),
(3316, N's3316', N'MOVIE', N'Alley Cat', NULL, 1970, N'R', 83, N'MINUTES', N'83 min', N'Billie Clark is twenty, smart and pretty. She''s also a black belt in karate. When the young woman beats up a gang of thugs trying to steal her tires, they retaliate by murdering her grandparents. She vows to see justice done and avenge their deaths.'),
(3317, N's3317', N'TV_SHOW', N'All Together Now', NULL, 2019, N'16+', 2, N'SEASONS', N'2 Seasons', N'Altogether Now, our favourite Saturday night singalong is back with a bang! The new series brings us outstanding talent, a huge range of musical styles and a load of laughs from host Rob Beckett.'),
(3318, N's3318', N'MOVIE', N'All She Wishes', NULL, 2014, N'7+', 89, N'MINUTES', N'89 min', N'When her birthday wish magically summons wacky Hollywood actor Drake to her small Midwestern town, Sophie has to figure out how to help him fit in until she can get him back home. But Drake is more interested in helping Sophie stand out.'),
(3319, N's3319', N'MOVIE', N'All Roads Lead Home', NULL, 2020, N'7+', 113, N'MINUTES', N'113 min', N'When Belle, struggling with the loss of her mom, is sent to live with her grandfather, she soon becomes the savior of all living things! An old race horse and Atticus the dog change Belle''s life, and in turn the life of those who love her.'),
(3320, N's3320', N'MOVIE', N'All Over Town', NULL, 1937, N'13+', 64, N'MINUTES', N'64 min', N'Olsen and Johnson, along with their trick seal Sally, try to stage a fundraising vaudeville show in a "jinxed" theater, in order to help pretty Joan Eldredge (Howard) from losing her father''s theater. However, during one of the rehearsals, a potential financier is murdered, with Sally the seal a suspect. To gain publicity for their show, Olsen and Johnson state that they will reveal the true killer''s identity on opening night. However, the killer has other plans, and a hilarious chase through the dark theater ensues, along with some hilarious slapstick hijinks. Rated the funniest appearance of Olsen and Johnson together on screen.'),
(3321, N's3321', N'TV_SHOW', N'All or Nothing: Tottenham Hotspur', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'Go behind the scenes of Tottenham Hotspur Football Club during one of the most defining seasons in their history. Chairman Daniel Levy makes the mid-season decision to sack manager Mauricio Pochettino and hire José Mourinho. Players including Dele Alli, Heung-Min Son and Harry Kane fight to put the club amongst Europe’s elite against the backdrop of the global coronavirus crisis.'),
(3322, N's3322', N'TV_SHOW', N'All or Nothing: The Michigan Wolverines', NULL, 2018, N'16+', 1, N'SEASONS', N'1 Season', N'All or Nothing: The Michigan Wolverines goes behind-the-scenes of the winningest program in college football to chronicle Michigan’s 2017 season. Head coach Jim Harbaugh leads his alma mater’s young team as the series provides an intimate look at the lives, both on the field and off, of the student athletes charged with carrying on Michigan’s legacy.'),
(3323, N's3323', N'TV_SHOW', N'All Or Nothing: New Zealand All Blacks', NULL, 2018, N'16+', 1, N'SEASONS', N'1 Season', N'For the first time ever, The New Zealand All Blacks rugby team, known as the winningest team in global sports history, allows cameras into their super secretive world to witness one of their most difficult seasons yet. Over four months, they face the demands of the most physically grueling team sport on the planet to uphold a legacy of excellence and dominance that goes back well over a century.'),
(3324, N's3324', N'TV_SHOW', N'All or Nothing: Manchester City', NULL, 2018, N'16+', 1, N'SEASONS', N'1 Season', N'In this ground-breaking docu-series, follow Manchester City behind the scenes throughout their Premier League winning, record-breaking ‘17-18 season. Get an exclusive look into one of the best global sports clubs, including never-before-seen dressing room footage with legendary coach Pep Guardiola, and delve into the players’ lives off and on the pitch.'),
(3325, N's3325', N'TV_SHOW', N'All or Nothing: Brazil National Team', NULL, 2020, N'18+', 1, N'SEASONS', N'1 Season', N'The Brazilian National Team goes on a journey of faith, brotherhood, and hard work to reimagine their identity and to re-engage a disgruntled fanbase as they attempt to win the 2019 Copa América on home soil. From the locker room, trough the trainings, to the games, we go exclusively behind-the-scenes with the world’s most famous football team.'),
(3326, N's3326', N'TV_SHOW', N'All or Nothing (TV-14)', NULL, 2020, N'16+', 5, N'SEASONS', N'5 Seasons', N'One season has passed since Philadelphia’s first Super Bowl championship and expectations are once again soaring. Carson Wentz, Pro Bowl tight end Zach Ertz and defensive stalwarts Malcolm Jenkins, Fletcher Cox, and Brandon Graham lead a loaded roster intent on returning the Lombardi Trophy to Philadelphia, where the Eagles are more than just a football team-they’re a way of life.'),
(3327, N's3327', N'TV_SHOW', N'All or Nothing', NULL, 2020, N'16+', 5, N'SEASONS', N'5 Seasons', N'One season has passed since Philadelphia’s first Super Bowl championship and expectations are once again soaring. Carson Wentz, Pro Bowl tight end Zach Ertz and defensive stalwarts Malcolm Jenkins, Fletcher Cox, and Brandon Graham lead a loaded roster intent on returning the Lombardi Trophy to Philadelphia, where the Eagles are more than just a football team – they’re a way of life.'),
(3328, N's3328', N'MOVIE', N'All is Bright', NULL, 2013, N'R', 107, N'MINUTES', N'107 min', N'Starring Paul Rudd and Oscar-nominee Paul Giamatti. Two low-level con men attemp to pull off one last job: selling Christmas trees in New York City.'),
(3329, N's3329', N'MOVIE', N'Alien Uprising', NULL, 2013, N'R', 101, N'MINUTES', N'101 min', N'A group of friends awake one morning to find all electricity and power shut off, and an immense alien aircraft hovering in the air above their heads. Suddenly this regular group of friends is battling to survive, as the entire human race is threatened by the alien army hovering ominously above.'),
(3330, N's3330', N'TV_SHOW', N'Alien Monkeys', NULL, 2015, N'ALL', 1, N'SEASONS', N'1 Season', N'Alien Monkeys is story about two monkeys exploring the world together with unexpected musical adventures. Oki is full of curiosity about everything on Earth and Taki is determined to find a bottle of "Earth soda". Surprisingly, they create fantastic musical performances while they are making trouble.'),
(3331, N's3331', N'MOVIE', N'Alien Crash Retrievals', NULL, 2016, NULL, 67, N'MINUTES', N'67 min', N'Learn the shocking truth about Extraterrestrial beings on Planet Earth. World governments and military factions are not only aware of the Alien presence; they may be in communication with alien races via an exchange program...'),
(3332, N's3332', N'TV_SHOW', N'Alien Conspiracy: They Are Here', NULL, 2021, N'13+', 1, N'SEASONS', N'1 Season', N'We are slowly starting to realize that we probably aren''t alone in the universe but evidence keeps mounting to suggest we need to fast track that realization and contend with aliens from outer space whether we''re ready or not.'),
(3333, N's3333', N'MOVIE', N'Alien Code', NULL, 2018, N'16+', 101, N'MINUTES', N'101 min', N'After deciphering a message found in a satellite, genius cryptographer Alex Jacobs finds himself being stalked by government agents and otherworldly beings.'),
(3334, N's3334', N'TV_SHOW', N'Alice Wetterlund: My Mama Is A Human And So Am I', NULL, 2019, N'16+', 1, N'SEASONS', N'1 Season', N'Follow comedian / actor Alice Wetterlund as she reveals her personal struggles with peeping toms, cat-rearing, alcoholism and the secret alien conspiracy behind new country music in her breakout comedy special. Best known for HBO’s "Silicon Valley" and "Mike and Dave Need Wedding Dates", Wetterlund shines in this tour de force hour long special taped at the Gothic Theater in Denver, CO.'),
(3335, N's3335', N'TV_SHOW', N'Alice Fraser: Savage', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'Alice Fraser''s critically acclaimed comedy show, Savage, is about paper towels and how not to murder people who “mean well”. A hilarious and heartbreaking show that walks you through the razor edges of a life stripped bare. How you deal with losing everything, what Buddhists do with rage and how bubble blowers work at funerals. Savage talks about things that are actually sad and also very funny.'),
(3336, N's3336', N'TV_SHOW', N'Alias', NULL, 2006, N'TV-14', 5, N'SEASONS', N'5 Seasons', N'The final season kicks off with a shocking revelation and never lets you catch your breath. Jennifer Garner stars as a secret agent facing one mother of a challenge. Old enemies and favorite guests return for the action-packed series finale.'),
(3337, N's3337', N'MOVIE', N'Alexi Murdoch', NULL, 2011, N'NR', 48, N'MINUTES', N'48 min', N'Acoustic tunes from a DIY singer/songwriter, Alexi Murdoch.'),
(3338, N's3338', N'MOVIE', N'Alcatraz', NULL, 2018, N'16+', 87, N'MINUTES', N'87 min', N'A group of prisoners, led by an armed robber and a gangster, attempt to escape from the infamous Alcatraz Island.'),
(3339, N's3339', N'MOVIE', N'Albion: The Enchanted Stallion', NULL, 2017, NULL, 106, N'MINUTES', N'106 min', N'A twelve-year-old girl is transported by a magical black stallion to the mystical world of ALBION, where she discovers that she alone is the key to saving an entire race of people.'),
(3340, N's3340', N'TV_SHOW', N'Albert & Junior: Journey of discovery for babies', NULL, 2015, N'ALL', 1, N'SEASONS', N'1 Season', N'Albert loves exploring the world around him! He has many questions about how things work, and always relies on his trusty buddy Junior to help explain the answers.'),
(3341, N's3341', N'TV_SHOW', N'Alaska Off-Road Warriors', NULL, 2015, N'TV-14', 1, N'SEASONS', N'1 Season', N'Alaska Off-Road Warriors pits five teams of two in a grueling off-road challenge across Alaska, journeying from the Pacific Ocean to the Arctic Ocean in an intense expedition of epic proportions.'),
(3342, N's3342', N'MOVIE', N'Alabama Dirt', NULL, 2017, N'13+', 90, N'MINUTES', N'90 min', N'Love and dirt car racing collide in the hard-driving Alabama Dirt. Ty Hargrove is a poor country boy who dreams of becoming a state champion. When his biggest rival''s girl falls for him, he seems to have it all until a tragedy veers him off course.'),
(3343, N's3343', N'MOVIE', N'Al Jackson: Baby Steps in a Yellow Tuxedo', NULL, 2015, N'18+', 70, N'MINUTES', N'70 min', N'Al Jackson navigates you through life in his hilarious comedy special, Baby Steps in a Yellow Tuxedo: proving no matter how often you stumble, you can do it with class.'),
(3344, N's3344', N'MOVIE', N'Aida''s Secrets', NULL, 2017, N'13+', 95, N'MINUTES', N'95 min', N'A web of family secrets unravels in this documentary about two brothers, Izak and Shep, who were born inside the Bergen-Belsen displaced persons camp in 1945 and separated as babies, never told of the other''s existence. Nearly 70 years later, the discovery of family records leads the brothers to an emotional reunion with their elderly mother, Aida, who hid more from them than just each other.'),
(3345, N's3345', N'MOVIE', N'Agent Sai Srinivasa Athreya', NULL, 2019, N'13+', 145, N'MINUTES', N'145 min', N'Agent Sai Srinivasa Athreya is an authentic humorous investigative thriller revolving around the adventures of a detective based out of Nellore.'),
(3346, N's3346', N'MOVIE', N'Agent Sai (Hindi)', NULL, 2020, N'13+', 133, N'MINUTES', N'133 min', N'Agent Sai, a Nellore-based detective, faces trouble when he investigates the case of an unidentified body found near a railway track.'),
(3347, N's3347', N'MOVIE', N'Agent Fox', NULL, 2014, N'G', 87, N'MINUTES', N'87 min', N'Super spy Agent F.O.X. arrives in Carrot Town with one objective: infiltrate the community of friendly rabbits and locate a mysterious artifact. But the mission goes awry when the secret agent is mistaken for a distant cousin.'),
(3348, N's3348', N'TV_SHOW', N'Agatha Christie''s The Pale Horse', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'A mysterious list of names is found in the shoe of a dead woman. What is the connection to the village of Much Deeping?'),
(3349, N's3349', N'TV_SHOW', N'Agatha Christie''s The ABC Murders', NULL, 2019, N'16+', 1, N'SEASONS', N'1 Season', N'1933. Hercule Poirot, older and greyer, receives letters threatening murder. The sender signs themselves only as “A.B.C.” When he takes the letters to the police looking for help, Hercule finds all his old friends have moved on. But soon there is a murder and the once-great detective must take matters into his own hands.'),
(3350, N's3350', N'TV_SHOW', N'Agatha Christie''s Ordeal By Innocence', NULL, 2018, N'16+', 1, N'SEASONS', N'1 Season', N'When wealthy philanthropist, Rachel Argyll, is murdered at her family estate, her adopted son Jack is arrested for her murder. He vehemently protests his guilt and eighteen months later, the identity of the murder is thrown in doubt. Now it is up to the rest of the family to decipher a killer amongst them.'),
(3351, N's3351', N'TV_SHOW', N'After the Rain', NULL, 2018, N'TV-NR', 1, N'SEASONS', N'1 Season', N'Akira Tachibana(17) used to be the ace of a track club, but gave up running due to her injury. Masami Kondo(45) is a manager at a family restaurant called Garden, where Akira works. This story is set in a seaside town, and depicts a girl who stopped at a cross-point in her youth, and a man who reached a turning point of life. Everybody wants that moment where they get fraught with great emotions.'),
(3352, N's3352', N'MOVIE', N'After School', NULL, 1988, N'R', 90, N'MINUTES', N'90 min', N'September Johnson is the perfect student, full of brains and beauty. But her favorite subject is Michael, an attractive young professor. What September wants to learn from him isn''t taught in the classroom. Now the lesson really begins - after school.'),
(3353, N's3353', N'TV_SHOW', N'Afsos', NULL, 2020, N'16+', 1, N'SEASONS', N'1 Season', N'A suicidal man and a deadly assassin encounter the world of immortality in this black comedy suspense thriller.'),
(3354, N's3354', N'MOVIE', N'Adventures of Kii & Yii - Little Baby Bum', NULL, 2018, N'ALL', 51, N'MINUTES', N'51 min', N'A compilation highlighting the adventures of Kii and Yii brought to you by Little Baby Bum!'),
(3355, N's3355', N'TV_SHOW', N'Adventure Agents', NULL, 2020, N'TV-PG', 4, N'SEASONS', N'4 Seasons', N'Come join the Adventure Agents Family with Agents Axe, Tex, A-Ninja and Trinity as they solve the mystery of the Island Raiders in Hawaii! They learn about the amazing history, nature and culture of the Hawaiian islands. Remember, life is an adventure and Love is the key. This family friendly video series is for kids and adults alike, and is produced by the family from The Axel Show.'),
(3356, N's3356', N'MOVIE', N'Adimurai', NULL, 2020, N'ALL', 140, N'MINUTES', N'140 min', N'An ancient Martial art form of Tamilnadu is in the verge of extinction. The hero wants to make it popular yet again among the current generation showcasing it''s rich values & merits. Will the hero be able to accomplish his desire ?'),
(3357, N's3357', N'MOVIE', N'Adam Ferrara: Funny As Hell', NULL, 2009, N'18+', 61, N'MINUTES', N'61 min', N'Adam Ferrara takes the stage to regale his audience with sidesplittingly funny and all-too-true observations about life, from wacked-out family dynamics to dysfunctional romantic relationships and more.'),
(3358, N's3358', N'TV_SHOW', N'Action Team', NULL, 2018, N'16+', 1, N'SEASONS', N'1 Season', N'Action Team are faced with an evil network masterminded by Vladimir Schevchenko, an attention seeking leader of a tiny republic of Russia, who is as inept as he is unpredictable. Vlad attempts to become the world number one bad guy and will stop at nothing to get what he wants. It is up to Action Team to infiltrate the secret organisation and get their hands on the world''s most deadly device.'),
(3359, N's3359', N'TV_SHOW', N'Act of Will', NULL, 1989, N'16+', 1, N'SEASONS', N'1 Season', N'The story of Audra, born in 1907, her daughter Christina and granddaughter Kyle.'),
(3360, N's3360', N'TV_SHOW', N'Across the Pacific', NULL, 2020, N'TV-G', 1, N'SEASONS', N'1 Season', N'Across the Pacific is a series about a great aviation milestone: the 1935 crossing of the Pacific Ocean by the Pan Am flying boat China Clipper. It features re-enactments, interviews, archival photographs, newsreels and feature films.'),
(3361, N's3361', N'MOVIE', N'Ace In The Hole', NULL, 1951, N'PG', 111, N'MINUTES', N'111 min', N'A cave collapse traps a man, and all eyes turn toward the tragedy including those of Charles "Chuck" Tatum (Kirk Douglas), a washed-up newspaper reporter who sees the incident as a ticket back to his former days at the top of the journalism heap.'),
(3362, N's3362', N'MOVIE', N'Accidentally Engaged', NULL, 2016, N'13+', 86, N'MINUTES', N'86 min', N'Famous actor Chas Hunter and aspiring actress Clarissa Byers agree to fake an engagement to improve both their reputations. However, playing pretend starts to feel all too real as the two start to fall for one another.'),
(3363, N's3363', N'TV_SHOW', N'Absentia', NULL, 2020, N'18+', 3, N'SEASONS', N'3 Seasons', N'Season 3 picks up after the Dramatic events of Season 2 with Emily nearing the end of her FBI suspension. Everything is upended when one of Nick’s criminal cases threatens the lives of Emily’s family. Her efforts to unravel a dangerous conspiracy take Emily to Europe, testing her like never before and forcing her to learn to trust and love again as she finally realizes her true place in the world.'),
(3364, N's3364', N'MOVIE', N'Above & Beyond', NULL, 2015, NULL, 57, N'MINUTES', N'57 min', N'Above and Beyond highlights one of the most compelling escape and survival stories from World War II. On December 1, 1943, Bruce Sundlun''s bomber drew fire from German fighter planes and crashed in Nazi-occupied Belgium. With help from an underground network, Bruce fled to occupied France, where he joined the Resistance. He would go on to spy for the OSS, the precursor to the CIA.'),
(3365, N's3365', N'MOVIE', N'About Alex', NULL, 2014, N'R', 100, N'MINUTES', N'100 min', N'After the stress of adulthood takes its toll, seven college friends reunite for a weekend of partying and shared laughs. Together for the first time in years, old crushes and rivalries are rekindled and a combination of wine, weed and an unexpected dog sends the weekend to unexpected places.'),
(3366, N's3366', N'MOVIE', N'Ablaze', NULL, 2002, N'R', 97, N'MINUTES', N'97 min', N'An oil refinery blows up, causing a firestorm that threatens a hospital and everyone inside.'),
(3367, N's3367', N'MOVIE', N'Abilene Town', NULL, 1946, N'13+', 89, N'MINUTES', N'89 min', N'Abilene, Kansas, town marshal Dan Mitchell (Scott) has managed to keep a tenuous peace by keeping saloons, gambling, and guns on one side of Main Street, and the stores, women, children, and farmers on the other side. Violence and killings begin when homesteaders arrive in town in droves. Dan convinces the shopkeepers to side with the homesteaders. To save his town, Dan pits the saloon owners and cowboys against each other, resulting in a vicious bloodbath. In the midst of the chaos, Dan must make a decision between the two women he loves.'),
(3368, N's3368', N'MOVIE', N'Aberdeen City', NULL, 2011, N'NR', 27, N'MINUTES', N'27 min', N'Newcomers Aberdeen City open for Electric Six with swirling, guitar-driven rock.'),
(3369, N's3369', N'MOVIE', N'Abducted', NULL, 2007, N'16+', 89, N'MINUTES', N'89 min', N'Melanie is married to Tom, a controlling, cold and self-centered man who happens to be the Prison Warden. He finds her to be a liability in his career aspirations and secretly plans to have her kidnapped and killed by a dangerous inmate, Jack.'),
(3370, N's3370', N'MOVIE', N'ABC Ice Cream Cones with The LuvBugz  Learn the Alphabet', NULL, 2018, N'ALL', 17, N'MINUTES', N'17 min', N'Learn the alphabet with The LuvBugz Nursery Rhymes & Kids Songs and these Delicious Ice Cream Cones - Teach ABC in English.'),
(3371, N's3371', N'TV_SHOW', N'ABC Galaxy (Spanish audio)', NULL, 2018, N'ALL', 1, N'SEASONS', N'1 Season', N'Travel the ABC Galaxy with Giggs & Hugg, two adorable friends. Spanish audio.'),
(3372, N's3372', N'MOVIE', N'Aakaasam Nee Haddhu Ra (Telugu)', NULL, 2020, N'16+', 150, N'MINUTES', N'150 min', N'Inspired by the book ‘Simply Fly’, the film tells the story of Nedumaaran Rajangam known to friends as Maara, the son of a teacher, who sets out to make the common man fly and takes on the most capital intensive industry in the world with the help of his friends, family and sheer will power.'),
(3373, N's3373', N'MOVIE', N'Aadar Malik: Stand Up The Musical', NULL, 2017, N'NR', 65, N'MINUTES', N'65 min', N'An extremely high energy standup comedy show much like Aadar himself, it mocks the very talents that he so confidently boasts of.'),
(3374, N's3374', N'MOVIE', N'Aadai', NULL, 2019, N'18+', 127, N'MINUTES', N'127 min', N'A free-spirited girl gets the shock of her life when she finds herself without any clothes in an abandoned building after a late-night party.'),
(3375, N's3375', N'MOVIE', N'A Year in Port', NULL, 2016, N'16+', 86, N'MINUTES', N'86 min', N'With renowned wine importer Martine Saunier as our guide, we journey into Portugal''s spectacular Douro Valley to explore the mystery and complexity of the world of port'),
(3376, N's3376', N'MOVIE', N'A Year in Champagne', NULL, 2015, N'13+', 82, N'MINUTES', N'82 min', N'With renowned wine importer Martine Saunier as our guide, we get a rare glimpse behind the scenes into the real Champagne through six houses, from small independent makers to the illustrious houses of Gosset and Bollinger which have been instrumental in shaping the image of Champagne around the world.'),
(3377, N's3377', N'MOVIE', N'A Year in Burgundy', NULL, 2013, N'13+', 89, N'MINUTES', N'89 min', N'The film follows seven wine-making families in the Burgundy region of France through the course of a full year, and delves into the cultural and creative process of making wine, as well as its deep ties to the land. The film is in four season-sections, and plays out against that backdrop: spring showers, drought, heat wave, hail and storms, harvest moons and the damp cold of winter.'),
(3378, N's3378', N'MOVIE', N'A World Away', NULL, 2019, N'ALL', 73, N'MINUTES', N'73 min', N'Six kids take a trip to the Grand Canyon, but instead find themselves in a whole other world. A Dove approved production.'),
(3379, N's3379', N'MOVIE', N'A Woman Scorned: The Betty Broderick Story: Part I', NULL, 1992, NULL, 93, N'MINUTES', N'93 min', N'When all-American housewife and mother of four Betty Broderick learns that her successful husband Dan is leaving her for another woman, Betty vows vindication and revenge.'),
(3380, N's3380', N'TV_SHOW', N'A Very English Scandal', NULL, 2018, N'16+', 1, N'SEASONS', N'1 Season', N'The shocking true story of the first British politician to stand trial for conspiracy to murder. Jeremy Thorpe (Hugh Grant), the leader of the Liberal party, has a secret he''s desperate to hide. His ex-lover Norman Scott (Ben Whishaw) is putting Thorpe''s brilliant political career at risk so Thorpe schemes and deceives until he realizes there’s only one way to silence Scott for good'),
(3381, N's3381', N'MOVIE', N'A Turtle''s Tale 2: Sammy''s Escape from Paradise', NULL, 2011, N'G', 93, N'MINUTES', N'93 min', N'When Sammy and Ray find themselves trapped in The Tank, an underwater aquarium, they must hatch a plan to escape and reunite with their grandkids, Ricky and Ella, and protect them from the dangers of the ocean.'),
(3382, N's3382', N'MOVIE', N'A Turma do sextou - A TV ideal', NULL, 2020, N'13+', 6, N'MINUTES', N'6 min', N'They are back! Lygia beatriz & Jean chambre bring back the two friends involved in fun and unexpected situations, this time our favorite duo needs to buy a TV over the internet! it''s fun for the whole family'),
(3383, N's3383', N'MOVIE', N'A Turma do Sextou - A Princesa , o Sapo e a Escolinha', NULL, 2020, N'13+', 3, N'MINUTES', N'3 min', N'New version of the classic in which a Princess kisses a frog to break a spell. the short also brings a segment in the school of professor Lucas'),
(3384, N's3384', N'MOVIE', N'A Trip Under the Sea', NULL, 2013, N'ALL', 60, N'MINUTES', N'60 min', N'Sharecare Windows presents World-renowned underwater photographer Nick Martorano bringing to life the vibrant underwater world of Palau. Experience some of the planets most amazing natural wonders including gardens of coral just beneath the clearest waters to "sting-less" jellyfish, underwater caves, A soothing video postcard with no narration or music-simply the natural sounds and video.'),
(3385, N's3385', N'MOVIE', N'A Trip Through The World''s Greatest Cities', NULL, 2012, N'ALL', 60, N'MINUTES', N'60 min', N'This relaxing video postcard takes you to some of the world''s most interesting destinations. You''ll enjoy these HD videos accompanied by the naturally occurring ambient sounds. Destinations include; Amsterdam, Chicago, Buenos Aries, Venice, Sao Paulo, New York City, Valencia and Barcelona, Harbin China, and Tokyo. No passport required.'),
(3386, N's3386', N'MOVIE', N'A Trip Through Lake Tahoe', NULL, 2013, N'ALL', 60, N'MINUTES', N'60 min', N'A relaxing video postcard format with no narration or music-simply the natural sounds and video in HD. Relax with vistas of Lake Tahoe''s spectacular natural beauty including beaches, waterfalls and mountains. Relax with Sharecare Windows.'),
(3387, N's3387', N'MOVIE', N'A Tour Through Hawaii', NULL, 2012, N'ALL', 60, N'MINUTES', N'60 min', N'A relaxing video postcard with no narration or music-simply the natural sounds and video in HD. Enjoy the spectacular natural beauty of Hawaii including, Eternity Beach, Ioa Valley Park, Blowhole, Rainbow Falls, Kawaiola Bay, Lotus Flower ponds, Jungle Waterfall, Makapu''u Tide Pools, Maui Twin Falls, Kaeohe Bay, Tunnels Beach at Hanalei, Waimoku Falls, Haleakala National Forest, and more.'),
(3388, N's3388', N'MOVIE', N'A Taxi Driver', NULL, 2017, NULL, 137, N'MINUTES', N'137 min', N'In this powerful drama based on a true story, a down-on-his-luck taxi driver hired by a foreign journalist finds himself in a life-or-death struggle in the midst of the Gwanju Uprising.'),
(3389, N's3389', N'MOVIE', N'A Talent For The Game', NULL, 1991, N'PG', 91, N'MINUTES', N'91 min', N'Virgil Sweet is on the verge of losing his job as a talent scout with the California Angels when he discovers Sammy Bodeen, a country boy with no pro ball experience, but with a pitching arm no one has seen the like of.'),
(3390, N's3390', N'TV_SHOW', N'A Stitch in Time', NULL, 2016, N'ALL', 1, N'SEASONS', N'1 Season', N'The series is presented by fashion historian Amber Butchart and features a range of period garments lovingly reconstructed using only period techniques. Taking fashion in traditional works of art as her inspiration, she works with historical costumier, Ninya Mikhaila, fellow costumier Harriet Waterhouse and student Hannah Marples, to recreate extraordinary historical garments all made by hand.'),
(3391, N's3391', N'MOVIE', N'A Song is Born', NULL, 1948, N'7+', 113, N'MINUTES', N'113 min', N'With her gangster boyfriend under investigation by the police, a nightclub singer hides out in a musical research institution staffed by bachelor professors - one of whom begins to fall for her.'),
(3392, N's3392', N'TV_SHOW', N'A Series of Light', NULL, 2020, N'18+', 1, N'SEASONS', N'1 Season', N'From the award-winning filmmakers behind the hit LGBTQ* films "This World We Live In" and "Wretched Things" comes a new anthology series weaving tales of intimacy, deceit, heartbreak and disconnection within such a heavily connected world.'),
(3393, N's3393', N'MOVIE', N'A Second Chance', NULL, 2019, N'13+', 94, N'MINUTES', N'94 min', N'When best friends Daniella and Cheyann both start to have feelings for Cheyann''s best guy friend Darius something unexpected happens. Faced with the possibility of losing Darius makes Cheyann realizes that she really loves him causing the friends to be caught in a triangle of confusion, deceit and decisions. But they come to realize that everyone deserves a second chance.'),
(3394, N's3394', N'MOVIE', N'A Refuge of Last Resort', NULL, 2017, N'13+', 63, N'MINUTES', N'63 min', N'This no holds barred, award winning documentary chronicles the days before, during and after Hurricane Katrina. Told from the viewpoint of several families stuck in New Orleans, this moving and unflinching story says so much by saying so little. Most of this footage has never been seen by the public, and there is absolutely no stock footage used in this film.'),
(3395, N's3395', N'MOVIE', N'A Reckoning', NULL, 2018, NULL, 81, N'MINUTES', N'81 min', N'After her husband is brutally murdered, a widowed homesteader seeks revenge and leaves everything behind to hunt down his killer.'),
(3396, N's3396', N'MOVIE', N'A Rainy Day in New York', NULL, 2020, N'13+', 93, N'MINUTES', N'93 min', N'Woody Allen returns to the romantic fields of previous hits Vicky Cristina Barcelona and Midnight in Paris, assembling an all-star cast including Timothée Chalamet, Elle Fanning, Selena Gomez, Jude Law, Diego Luna and Liev Schreiber, for a charming, comedic tale set amidst the dizzying streets of The Big Apple, as romantic weekend plans are soon dashed as quickly as the sunlight turns to showers.'),
(3397, N's3397', N'MOVIE', N'A Promise to My Father', NULL, 2013, N'13+', 56, N'MINUTES', N'56 min', N'A Promise to My Father follows Israel "Izzy" Arbeiter as he returns to the sites of his darkest hours and relives the Holocaust''s unimaginable horrors. With his grandson in tow, Izzy travels to Treblinka, Auschwitz and Stuttof, and various Holocaust memorials, with the hope of bringing closure to this painful chapter of his life.'),
(3398, N's3398', N'MOVIE', N'A Promise to Astrid', NULL, 2019, N'7+', 89, N'MINUTES', N'89 min', N'A Promise to Astrid is a captivating account of a woman whose unusual gift and stubborn determination leads to a greater purpose. When a car accident leaves a family in a predicament, Astrid intervenes and is dismissed as an eccentric elderly neighbor. Despite the family''s resistance, Astrid''s demonstration of faith and selflessness defy all expectations.'),
(3399, N's3399', N'TV_SHOW', N'A Portrait Of Postwar Japan', NULL, 2017, N'13+', 1, N'SEASONS', N'1 Season', N'Since its defeat in WWII, Japan became a world economic power at lightning speed, and underwent an unprecedented economic boom in the mid-1980''s, known as the "bubble economy." However, after the bubble burst, the Japanese financial system has continued to slowdown. This series sheds light from an economic angle how the Japanese people have lived during the 70 years since World War II.'),
(3400, N's3400', N'MOVIE', N'A Place in the Sun', NULL, 1951, N'13+', 122, N'MINUTES', N'122 min', N'George Eastman is a poor young man determined to win a place in society and the heart of a beautiful socialite (Elizabeth Taylor). Shelley Winters plays the factory girl whose dark secret threatens Eastman''s professional and romantic prospects.');







































































































































































































































































































































































































































































































































































































