CREATE VIEW dbo.vw_content_summary
AS
SELECT
    c.id,
    c.source_id,
    c.title,
    c.content_type,
    c.release_year,
    c.rating,
    c.duration_value,
    c.duration_unit,
    (SELECT COUNT(*) FROM dbo.content_person cp
       WHERE cp.content_id = c.id AND cp.role = N'CAST') AS cast_count,
    (SELECT COUNT(*) FROM dbo.content_person cp
       WHERE cp.content_id = c.id AND cp.role = N'DIRECTOR') AS director_count,
    (SELECT COUNT(*) FROM dbo.content_genre cg
       WHERE cg.content_id = c.id) AS genre_count
FROM dbo.content c;
GO

-- VALIDACIÓN FINAL
SELECT N'content' AS tabla, COUNT_BIG(*) AS filas FROM dbo.content
UNION ALL SELECT N'person', COUNT_BIG(*) FROM dbo.person
UNION ALL SELECT N'genre', COUNT_BIG(*) FROM dbo.genre
UNION ALL SELECT N'country', COUNT_BIG(*) FROM dbo.country
UNION ALL SELECT N'content_person', COUNT_BIG(*) FROM dbo.content_person
UNION ALL SELECT N'content_genre', COUNT_BIG(*) FROM dbo.content_genre
UNION ALL SELECT N'content_country', COUNT_BIG(*) FROM dbo.content_country;

-- Debe devolver 0 filas.
SELECT cp.*
FROM dbo.content_person cp
LEFT JOIN dbo.content c ON c.id = cp.content_id
LEFT JOIN dbo.person p ON p.id = cp.person_id
WHERE c.id IS NULL OR p.id IS NULL;
GO
